const RAW_EPISODES = [
  { title: "Masculinisme et complotisme", url: "https://www.franceinfo.fr/replay-radio/complorama/masculinisme-et-complotisme_8092463.html", img: "assets/episodes/1aa94761-98e4-48fc-aa9d-e4a53d8c6d45.webp", youtube: null, description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama, les liens entre cette idéologie antiféministe et le complotisme.", date: "2026-07-03", body: "Le point de départ de ce 112e numéro de Complorama, ce sont ces deux attentats survenus en l'espace de quelques semaines. L'un s'est déroulé à San Diego, en Californie, l’autre à Montréal, au Canada, mais tous les deux portent des signatures semblables : leurs auteurs avaient des liens avec la communauté incel. Les incels, ce sont ces “célibataires involontaires” qui accusent les femmes de tous leurs maux. Il s'agit en réalité d'un courant du masculinisme, cette idéologie antiféministe qui véhicule des thèses sexistes, réactionnaires, souvent racistes, antisémites et complotistes. Ce masculinisme inquiète jusqu’en France puisque la Direction générale de la sécurité intérieure (DGSI) a tiré la sonnette d'alarme, n'hésitant plus à parler de la \"menace terroriste masculiniste\". Un rapport du Sénat révélé fin juin appelle également à \"réveiller les consciences\" face à la montée de ce phénomène qualifié de \"risque réel pour notre démocratie\".Une structure complotiste\"Le masculinisme n'emprunte pas au complotisme par accident : il en a la structure même\", explique Rudy Reichstadt. Le documentaire masculiniste \"The End of Men\" sorti en 2022 et réalisé par l'ancien présentateur vedette de Fox News, le complotiste Tucker Carlson, permet de comprendre ce qu'il y a de conspirationniste dans le masculinisme. \"Le film part d'un noyau de réalité, la baisse tendancielle du taux de testostérone et de la concentration spermatique, bien documentée, et imputable à l'obésité, aux modes de vie,…" },
  { title: "Le retour des biolabs", url: "https://www.franceinfo.fr/replay-radio/complorama/le-retour-des-biolabs_8069006.html", img: "assets/episodes/2bc885ea-1d9a-4232-9fe2-7ae231b004c8.webp", youtube: "https://www.youtube.com/watch?v=uC58db99Cts", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama, le retour de la théorie du complot selon laquelle les Etats-Unis financeraient des laboratoires secrets en Ukraine pour préparer des armes biologiques.", date: "2026-06-19", body: "Le 111e numéro de Complorama examine comment, en quelques heures, la directrice du Renseignement national américain Tulsi Gabbard a relancé la rumeur autour des biolabs.Tulsi Gabbard et ses \"documents déclassifiés\"Vendredi 12 juin, dans une vidéo publiée sur X, la cheffe du Renseignement américain, affirme que \"le gouvernement américain finance depuis longtemps plus de 120 laboratoires biologiques dans plus de 30 pays\", ajoutant au passage que \"bon nombre de ces laboratoires biologiques mènent ou ont mené des recherches utilisant des agents pathogènes dangereux et hautement contagieux, et dans certains cas, ont mené des recherches dangereuses sur le gain de fonction.\" Dans cette même vidéo, Tulsi Gabbard assure avoir déclassifié des documents qui en attestent. Pourtant, \"le chiffre de 120 laboratoires mis en avant par Tulsi Gabbard n'a rien d'un secret d'État que son administration aurait découvert\", balaye Rudy Reichstadt, directeur du site ConspiracyWatch. \"Elle prétend que les États-Unis ont caché qu'ils finançaient des biolabs à l'étranger, mais c’est faux, ces financements sont publics, votés par le Congrès et documentés officiellement depuis 2005 pour l'Ukraine. Même si elle ne le dit pas comme cela, elle laisse entendre que ces laboratoires auraient été secrets. C’est faux, là encore, il s'agit de cliniques, d'universités, de laboratoires de recherche vétérinaire et de centres de recherche épidémiologique civils tout à fait officiels\", explique Rudy Reichstadt.Les doc…" },
  { title: "PODCAST. Et si le Moyen Âge n'avait jamais existé ?", url: "https://www.franceinfo.fr/replay-radio/complorama/podcast-et-si-le-moyen-age-n-avait-jamais-existe_8046515.html", img: "https://www.franceinfo.fr/pictures/qg5T1P8YwQcnXPALmbd5xixM6i8/0x0:1920x1080/2656x1494/filters:format(avif):quality(50)/2026/06/05/6a22df5bdec1f631887921.jpg", youtube: "https://www.youtube.com/watch?v=lRgCYQYsWCg", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama, la théorie du récentisme, aussi connue sous le nom de \"Nouvelle chronologie\".", date: "2026-06-05", body: "Le 110e numéro de Complorama est une plongée chez les récentistes. Et si tout ce que nous croyons savoir du passé était faux ? Et si des siècles entiers de notre histoire avaient été inventés ? C’est le moteur narratif de la théorie conspirationniste du récentisme ou Nouvelle chronologie. Après être restée plutôt confidentielle dans les années 1980, celle-ci surgit soudainement plus de quatre décennies plus tard, relayée par des personnalités très médiatiques. À lire aussi : Podcast Le négationnisme et la complosphère Roger Avary et Tyler Herro la popularisent\"Je ne crois pas à l'histoire à antérieure à 1600\". C'est ce que déclare Roger Avary, le coscénariste du film \"Pulp Fiction\", le 11 février 2026 au micro du célèbre podcast de l'américain Joe Rogan. Ce jour-là, Roger Avary expose dans le podcast le plus écouté au monde, son allégeance à la théorie du récentisme. Ce moment déclenche dans la foulée un intérêt inédit pour cette théorie complotiste.Un pic confirmé par les données de Google Trends qui analysent en temps réel les requêtes effectuées sur le moteur de recherche. Le 11 février, la courbe pour l'expression \"new chronology\" atteint un niveau jamais vu en cinq ans. Quelques mois plus tôt, un autre pic pour la \"Nouvelle chronologie\" est constaté dans les \"tendances\" Google. En mai 2025, il correspond à l'interview sur Youtube du basketteur américain et star de la NBA Tyler Herro. Celui-ci déclare alors : \"Je ne crois pas en l'histoire. Je ne crois à rien de ce qui s…" },
  { title: "La saga Alex Jones", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-6612076", img: "assets/episodes/346b9cab-c8d2-4b5c-a371-d20b45cd00e7.webp", youtube: "https://www.youtube.com/watch?v=gUMr9Ipeg6k", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama le parcours de cet homme considéré comme l'une des figures les plus influentes du conspirationnisme aux Etats-Unis.", date: "2026-05-22", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama le parcours de cet homme considéré comme l'une des figures les plus influentes du conspirationnisme aux Etats-Unis. Le 109e numéro de Complorama Ouverture dans un nouvel onglet raconte la \"saga Alex Jones\". Cet américain est l'animateur et fondateur du média Infowars et a construit sa notoriété sur la diffusion de théories du complot. Alex Jones a surtout transformé cette mécanique en un modèle économique extrêmement rentable. En avril, il a perdu son média historique après une procédure judiciaire qui aura duré près d'une dizaine d'années, lancée par les familles de victimes de la tuerie de Sandy Hook. Publicité Alex Jones a fondé Infowars en mars 1999 et l'aura donc exploité durant près de trois décennies. À son apogée, en 2017, le site recensait environ 10 millions de visites mensuelles, soit plus que The Economist ou Newsweek à la même époque. Infowars deviendra une véritable marque en ligne, loin d'être un blog confidentiel, explique Tristan Mendès France, maître de conférences associé à l'université de Paris, spécialisé sans les cultures numériques. L'ADN éditorial est d'ailleurs verrouillé d'entrée : défiance d'État, Nouvel Ordre Mondial, globalistes, \"eux contre nous\". Le modèle économique viendra plus tard, mais la grammaire idéologique est posée dès 1999. Et c'est donc via Infowars qu'Alex Jones va qualifier la tuerie de Sandy Hook d…" },
  { title: "Trump et la fracture MAGA", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-30-avril-8083070", img: "assets/episodes/8d4664e5-c221-4e24-a3e5-2031f562c42e.webp", youtube: "https://www.youtube.com/watch?v=Q37sSG-H_08", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment la \"magasphère\" se divise autour de Donald Trump.", date: "2026-04-30", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment la \"magasphère\" se divise autour de Donald Trump. Le 108è numéro de Complorama examine cette semaine la fracture idéologique profonde qui divise actuellement la mouvance MAGA et les partisans de Donald Trump. L'un des faits révélateurs est la tentative d'attentat du 25 avril dernier. Pour Tristan Mendès-France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques, la complosphère s'est emballée : \"on a d'ailleurs des chiffres assez assez significatifs, notamment le terme staged, qui veut dire mise en scène, et qui a été employé plus d'un million de fois en moins de 48 heures\". Rudy Reichstadt, directeur de Conspiracy Watch observe que la complosphère a aussi fait, après l'attaque, un travail collaboratif \"non pas d'un faisceau de preuves, mais d'un mille feuilles d'arguments censés démontrer la mise en scène, la manipulation\". Tristan Mendès-France observe également une \"hybridation des théories du complot\", où des opposants de gauche et d'extrême droite s'unissent pour qualifier les récentes tentatives d'attentat contre Trump de mises en scène orchestrées. Publicité Autrefois fidèle, la \"magasphère\" se retourne contre le président Trump, en l'accusant de trahison sur des dossiers comme l'affaire Epstein ou les tensions avec l'Iran. Pour Rudy Reichstadt, \"cela commence avec Marjorie Taylor Greene…" },
  { title: "Hongrie : Viktor Orbán en campagne", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-6976216", img: "assets/episodes/d5ac8a53-743e-49e5-a32f-758c1cd6d117.webp", youtube: "https://www.youtube.com/watch?v=wjqEVrKDgNY", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment le Premier ministre hongrois Viktor Orbán utilise le complotisme comme stratégie électorale.", date: "2026-04-08", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment le Premier ministre hongrois Viktor Orbán utilise le complotisme comme stratégie électorale. Le 107è numéro de Complorama examine cette semaine la campagne électorale en Hongrie. Le vote a lieu le 12 avril. Viktor Orbán est au pouvoir depuis seize ans. Pour la première fois, les sondages ne lui sont pas favorables. Publicité Les cibles traditionnelles, durant la campagne, comme George Soros ou l'Union européenne, ont été remplacées par des accusations d'ingérence ukrainienne orchestrées par Volodymyr Zelensky. Pour Tristan Mendès-France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques : \"Le sujet de l'Ukraine est évidemment central dans la communication politique d'Orban depuis au moins le début du conflit avec la Russie\" ajoutant qu'Orban a une \"proximité idéologique avec Poutine\". Durant cette campagne, le paradoxe de l'ingérence est atteint avec la venue du vice-président américain. J.D. Vance dénonce d'un côté \"l'ingérence ukrainienne dans les élections, à la fois aux États-Unis et en Hongrie\" mais pour Tristan Mendès-France le plus extraordinaire reste l'explication du 7 avril à Budapest Ouverture dans un nouvel onglet , lorsque Vance dit \"explicitement avoir été envoyé par Trump pour dénoncer une supposée ingérence de Bruxelles tout en appelant explicitement à la réélection d'Orban\". S…" },
  { title: "En attendant les aliens", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-2400018", img: "assets/episodes/7796482f-f516-49e3-86c6-f1598532c3a7.webp", youtube: "https://www.youtube.com/watch?v=BiXIPwBVwY0", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment le thème des extraterrestres est passé du divertissement populaire à un outil de déstabilisation politique et de désinformation. C", date: "2026-03-20", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment le thème des extraterrestres est passé du divertissement populaire à un outil de déstabilisation politique et de désinformation. C'est le 106e numéro de Complorama. Complorama examine, cette semaine, comment la thématique des extraterrestres est passée de la culture populaire aux sphères de la désinformation, notamment politique. Publicité Le 14 février dernier, Barack Obama évoque les aliens dans une interview. L'ancien président des Etats-Unis déclare qu'il ne sait rien et qu'il n'a vu aucun document. Pour Rudy Reichstadt, directeur de Conspiracy Watch : \"ces propos ont immédiatement été interprétés par la complosphère comme des aveux\". De son côté Donald Trump accuse Barack Obama d'avoir révélé des documents classifiés et promet une prochaine déclassification de documents relatifs à la vie extraterrestre, aux phénomènes aériens non identifiés et aux objets volants non identifiés. Pour le directeur de Conspiracy Watch c'est une \"manière de donner un os à rongé au complotistes à un moment où il est très embarrassé par l'affaire Epstein\". De son côté, Tristan Mendès-France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques, ajoute que le président des Etats Unis essaie \"de créer une sorte de diversion avec un sujet très très porteur essentiellement pour sa base\". \"E.T\"., \"Independence day\", \"R…" },
  { title: "Complorama spécial Guerre en Iran", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-1733186", img: "assets/episodes/60790cde-0c17-45ab-8377-9db25aa4e068.webp", youtube: "https://www.youtube.com/watch?v=BBsttFpjLGw", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment l", date: "2026-03-06", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment l'offensive militaire américano-israélienne contre l'Iran alimente les théories du complot à l'échelle mondiale. C'est le 105è numéro de Complorama. Ce nouvel épisode de Complorama analyse la prolifération des théories du complot entourant les frappes militaires menées par les États-Unis et Israël contre l’Iran. Nous étudions dans ce podcast différentes comme celle annonçant qu'Ali Khamenei serait toujours vivant, et pour Tristan Mendès-France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques : \"C'est vraiment le complot par excellence qu'on trouve dans tout bon polar aujourd'hui avec le méchant ou le gentil qui aurait simulé sa mort\". Publicité Quand le conflit iranien rencontre le dossier Epstein, Tristan Mendès-France parle \"d'hybridation des séquences\". L'universitaire commente une vidéo dans laquelle François Asselineau, ancien candidat à l'élection présidentielle en 2017, évoque l'hypothèse que \"cette intervention américaine en Iran pourrait être le résultat d'un chantage de l'État israélien, qui posséderait des documents concernant Epstein et qui compromettraient Trump\". Tristan Mendès-France explique bien que dans cette vidéo : \"François Asselineau ne sait pas si c'est vrai mais il est certain que certains y croient, et c'est la base de son argumentation\". L'intervention militaire amé…" },
  { title: "Le complotisme boosté à l’IA", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-9433022", img: "assets/episodes/c3f63fdf-e466-4f04-9c3a-8368f53c9029.webp", youtube: "https://www.youtube.com/watch?v=sZrYBhbUTIs", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama, comment l", date: "2026-02-20", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama, comment l'intelligence artificielle générative transforme la diffusion des théories du complot. \"Le complotisme boosté à l’IA” c'est le 104è numéro de Complorama. Un Sommet mondial consacré à l'IA a eu lieu en Inde cette semaine, en présence d’Emmanuel Macron. Dans le même temps, la France vient de publier sa \"stratégie nationale contre les manipulations de l’information” dont une partie intéresse tout particulièrement Complorama : “Réguler les plateformes en ligne et les services d’intelligence artificielle générative”. A l’approche des élections municipales, et de la présidentielle, l’an prochain, l’IA est un outil à surveiller. Publicité Grok, l'intelligence artificielle de X, dans sa version grand public, a commis des dérapages inquiétants. Rudy Reichstadt, directeur de Conspiracy Watch parle même de \"bug\", notamment en mai 2025, lorsqu'elle était interrogée sur le salaire d'un joueur de baseball, cette IA \"s'est mise à délirer sur l'existence d'un génocide blanc contre les fermiers blancs sud-africains\". Un thème relayé par Elon Musk et \"Donald Trump, lui-même, avait offert l'asile aux États-Unis, aux Afrikaners, les descendants des colons européens en Afrique du Sud\". Les IA peuvent aussi être victimes d'attaques, on parle dans ce cas-là \"d'opérations d'empoisonnement\" selon Tristan Mendès-France qui s'appuie sur un cas précis révélé pa…" },
  { title: "Les démons de la complosphère", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-9520870", img: "assets/episodes/eabde422-204a-4b4d-a220-57aa7824b648.webp", youtube: "https://www.youtube.com/watch?v=K-_SY7IGOZk", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama, comment la complosphère utilise la rhétorique démoniaque. \"Les démons de la complosphère\", c", date: "2026-02-06", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama, comment la complosphère utilise la rhétorique démoniaque. \"Les démons de la complosphère\", c'est le 103è numéro de Complorama. Dans ce nouveau numéro de Complorama, nous n'allons pas parler de l'affaire Epstein, mais un peu quand même. Nous partons du mot \"démon\" qui serait associé à un compte bancaire du délinquant sexuel, aujourd'hui disparu. \"Les démons de la complosphère\", c'est le 103è numéro de Complorama. Publicité Epstein est qualifié de \"démon\" par certains, mais dans ce podcast, nous nous intéressons à une figure satanique associée à l'un de ses comptes bancaires. Il s'agit de \"Baal\", qui apparaitrait sur un document. \"Baal\" est souvent associé à une figure démoniaque. Il n'en fallait pas plus pour enflammer la complosphère. A la question sur un compte bancaire au nom de \"baal\" ayant appartenu à Jeffrey Epstein, la réponse de Tristan Mendès-France, maître de conférences associé à l’université Paris-Cité, spécialiste des cultures numériques est directe : \"Non\", ajoutant : \"Le document original a été mal scanné\". Le mot \"bank\" aurait, en effet, été transformé en mot \"Baal\" et pour Tristan Mendès-France : \"ça a suffi évidemment pour allumer la complosphère internationale\". Dans les hautes instances dirigeantes américaines, l'utilisation des figures démoniaques est également utilisée. Paula White qui dirige le bureau de la foi à la Mais…" },
  { title: "Le Davos des complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-9243030", img: "assets/episodes/eb437276-87d7-4560-a41f-08ec588c1ba9.webp", youtube: "https://www.youtube.com/watch?v=ndz43WZuDps", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment la complosphère voit le Forum Economique Mondial", date: "2026-01-23", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama comment la complosphère voit le Forum Economique Mondial C'est à DAVOS dans le canton des Grisons en Suisse , que tous les ans, les grands dirigeants de la planète se retrouvent au Forum économique mondial. Ils y discutent des grands enjeux de notre monde. Il n’en faut pas plus pour que la complosphère s’agite. \"Désinformation et mésinformation\" sont d’ailleurs les principaux risques mondiaux dénoncés par le Forum économique Mondial dans son rapport annuel. Davos est donc victime de ce qu’il dénonce. Le Davos des complotistes, c’est le 102e numéro de Complorama. Publicité Quand les puissants se réunissent dans une station de ski huppée en Suisse sous très haute sécurité, l'imaginaire conspirationniste se représente, pour Rudy Reichstadt : \"des élites mondialisées qui parlent un langage souvent technocratique, obscur\". Le directeur de Conspiracy Watch ajoute que s'il y a bien des règles de confidentialité, certaines \"prises de parole sont tout à fait publiques et retransmises sur YouTube et sur les chaînes d'info\". De son côté Tristan Mendès-France, maître de conférences associé à l’université Paris-Cité, spécialiste des cultures numériques, nous rappelle que ce genre de fantasmes existaient déjà lors de la création \"du groupe Bilderberg qui réunit des leaders de de la planète depuis les années 50 ou la Commission trilatérale fondée par David R…" },
  { title: "Complorama : le Venezuela vu de la complosphère", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-1941086", img: "assets/episodes/382ece95-f5fe-4765-b4ab-8eb5d0351462.webp", youtube: "https://www.youtube.com/watch?v=31WKG8Z6rto", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama l", date: "2026-01-09", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce nouveau numéro de Complorama l'enlèvement, le 3 janvier, de Nicolas Maduro par les forces américaines. L'opération militaire visant à enlever Nicolas Maduro au Venezuela est devenue un catalyseur de théories du complot divergentes au sein des sphères militantes mondiales. Nous allons étudier, avec Rudy Reichstadt et Tristan Mendès France, les divisions de la complosphère américaine sur cette opération. Certaines théories évoquent aussi un lien avec la fraude électorale de 2020. Publicité Pour ou contre l'opération militaire américaine au Venezuela ? La complosphère est divisée. Pour Rudy Reichstadt les divisions ne sont pas nouvelles, ce fut le cas \"sur le conflit entre Israël et le Hamas à Gaza, sur l'opportunité de de frapper les installations nucléaires iraniennes en juin dernier et sur le dossier Epstein\". Il y a deux donc deux parties qui s'opposent au sein de la galaxie \"Make America Great Again\" : la galaxie pro-Trump, ceux qui sont dans l'affirmation de la puissance américaine et en face, \"le pôle le plus complotiste, très souvent le plus tolérant à l'antisémitisme pour pas dire ouvertement antisémite\" nous explique le directeur de Conspiracy Watch. Il existe un gros malaise dans la complosphère pro-russe. Elle est habituellement alignée sur la position du président Trump. La Russie étant alliée du pays de Maduro, cette opération contre le Venezuela, \"qui est un a…" },
  { title: "PODCAST. La 100e de Complorama", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-6775353", img: "assets/episodes/5b84d509-d42e-4eb9-b1d1-97d9bfa3a708.webp", youtube: "https://www.youtube.com/watch?v=Oem1jxpcizQ", description: "Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce 100e épisode, l", date: "2025-12-12", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt et Tristan Mendès France décryptent et analysent, dans ce 100e épisode, l'activité de la complosphère depuis les débuts de Complorama. Une émission spéciale réalisée en public à la Maison de la radio et de la musique. Le 22 janvier 2021, franceinfo lançait un podcast pour analyser et décrypter les théories du complot. Pour ce 100e numéro, Complorama est enregistré en public à la Maison de la radio et de la musique avec Rudy Reichstadt et Tristan Mendès France. Publicité Ensemble, nous replongeons dans les archives de Complorama. Voici par exemple les titres des trois premiers podcasts en 2021 qui annoncent bien les thèmes qui seront abordés tout au long des cinq années : \"États-Unis : les complotistes et l'après Donald Trump\", puis \"Les complotistes et le business du Covid 19\" et enfin \"Russie, Chine, Iran, géopolitique du complotisme\". Les thèmes autour du Covid, de Trump, de la Russie, avec l'Ukraine sont toujours d'actualité. Nous allons les décrypter et voir leur évolution au fil des ans. Bienvenue dans le numéro 100 de Complorama ! Merci aux élèves de l'école EFAP présents dans le public, voici quelques extraits de leurs échanges avec Rudy Reichstadt et Tristan Mendès France. COMPLORAMA N°100 - Complorama Questions-Réponses 9 min 100e numéro de Complorama, un épisode enregistré en public avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, sp…" },
  { title: "Epstein, l'obsession complotiste", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-3932564", img: "assets/episodes/077978f1-e113-482d-b63e-9aa084ccf2d3.webp", youtube: "https://www.youtube.com/watch?v=GTYV28BNgOk", description: "Dans ce 99è numéro de Complorama nous revenons avec Rudy Reichstadt et Tristan Mendès-France sur l", date: "2025-11-28", body: "Complorama Par Rudy Reichstadt Dans ce 99è numéro de Complorama nous revenons avec Rudy Reichstadt et Tristan Mendès-France sur l'affaire Epstein devenue un mythe central et increvable au sein de la complosphère internationale. Donald Trump a signé en novembre 2025, une loi obligeant le ministère américain de la Justice à publier tous les documents non classifiés liés à l'affaire Epstein. C'est un revirement de la part du Président américain qui affirme \"nous n'avons rien à cacher\". Ce n'est pas ce que pense la complosphère, ni certains proches du clan Trump. Pour Rudy Reichstadt, directeur de Conspiracy Watch : \"cette affaire colle à Donald Trump comme le sparadrap du capitaine Haddock, ça revient vers lui en boomerang, cette théorie du complot\". Il est vrai que dans son propre camp c'est la division avec notamment Marjorie Taylor Greene, cette républicaine a décidé de démissionner du Congrès et réclame à publication des dossiers Epstein. Autre rupture dans le camp présidentiel, celle avec Elon Musk qui avait publié sur X que : \"Donald Trump figure dans les fichiers. C'est la vraie raison pour laquelle ils n'ont pas été rendus publics\" selon Rudy Reichstadt qui ajoute que \"face au tollé qu'il provoque, Musk supprime rapidement le message et dira ensuite qu'il était allé trop loin, mais le mal est fait\". Publicité L'affaire Epstein remonte à 2005. Le financier américain est accusé d'abus sexuels sur mineurs. Envoyé en prison, on le retrouve pendu dans sa cellule en 2019. Le…" },
  { title: "PODCAST. Quand la complosphère s'empare du climat", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complorama-3357361", img: "assets/episodes/21f3d4a0-3607-4dc7-a235-c21f7589090a.webp", youtube: null, description: "Le 98è numéro de Complorama s", date: "2025-11-14", body: "Complorama Par Rudy Reichstadt Le 98è numéro de Complorama s'intéresse au climato-complotisme et à la désinformation qui entourent le sujet du dérèglement climatique à l'occasion de la COP30 qui se tient au Brésil. A l'occasion de la COP30 au Brésil, Complorama revient sur la sphère climato complotiste. 10% de la désinformation actuelle est consacrée au climat selon Laurence Tubiana qui dirige la Fondation européenne pour le climat. Actuellement, le climat serait, justement, favorable aux climato complotistes. Donald Trump, par exemple, s'est exprimé en septembre à l'ONU Ouverture dans un nouvel onglet contre les énergies vertes, ce qui fait dire à Rudy Reichstadt, directeur de Conspiracy Watch : \"c'est sans doute le seul chef d'État à être allé aussi loin en matière de déclaration climato sceptique, climato complotiste, climato dénialiste même. Il dit quand même avoir gagné contre le canular, du changement climatique\". Publicité Les avions dans le ciel laissent souvent derrière eux des traces blanches. Ce sont des trainées de condensation. Mais pour certains, il s'agit \"de pulvérisations chimiques nocives\" nous dit Rudy Reichstadt. C'est la théorie des \"chemtrails\". Un complot derrière lequel il y aurait \"des programmes secrets militaires, les ouragans seraient pilotés par l'armée américaine et d'autres institutions\" nous explique Tristan Mendès-France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques. En Floride, des projets de l…" },
  { title: "Antivax, le retour", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/podcast-antivax-le-retour-3433552", img: "assets/episodes/150a6599-35b6-4360-8a16-23f41fe1a492.webp", youtube: "https://www.youtube.com/watch?v=qVsDhuLyaZc", description: "Complorama explore le renouveau du mouvement anti-vaccin et son lien avec la complosphère en France et à l", date: "2025-10-17", body: "Complorama Par Rudy Reichstadt Complorama explore le renouveau du mouvement anti-vaccin et son lien avec la complosphère en France et à l'international. Ce 96è Complorama se penche sur la résurgence du mouvement antivaccin en France et dans le monde. Publicité Nous analysons la viralité des messages de figures controversées comme le professeur Didier Raoult, qui a établi un lien non prouvé entre le vaccin anti-Covid et l'augmentation des cas de cancer. Pour Rudy Reichstadt, directeur de Conspiracy Watch, on est là \"dans un cas typique de confusion entre corrélation et causalité. Corrélation, deux phénomènes qui se produisent en même temps. La causalité, c'est que le phénomène B est la conséquence du phénomène A. C'est ce que suggère et affirme Didier Raoult. Ce n'est pas ce que suggèrent, ni ce qu'affirment, les auteurs mêmes de ces études\". Nous abordons également la montée du complotisme qui associe les vaccins à des maladies graves comme les \"turbocancers\" et le rôle des algorithmes des plateformes en ligne qui favorisent la visibilité des contenus vaccinosceptiques. La raison est simple pour Tristan Mendès-France : \"c'est qu'en fait les communautés les plus extrêmes interagissent plus que les autres sur ces types de plateformes. Cette interaction en ligne autour de certains ouvrages est perçue par les algorithmes comme une potentialité de vente\". Nous mettons en lumière dans ce numéro l'institutionnalisation du discours antivaccin à l'échelle transatlantique, notamment a…" },
  { title: "PODCAST. La complosphère mondiale et Brigitte Macron", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/podcast-la-complosphere-mondiale-et-brigitte-macron-8431389", img: "assets/episodes/b63f5a2d-5872-45db-a50f-93480ae27119.webp", youtube: "https://www.youtube.com/watch?v=v2GhU9M-a9Y", description: "Complorama revient sur le procès pour cyberharcèlement contre Brigitte Macron. Rudy Reichstadt et Tristan Mendès-France examinent les lignes de défense des dix prévenus et analysent la généalogie de la rumeur.", date: "2025-10-10", body: "Complorama Par Rudy Reichstadt Complorama revient sur le procès pour cyberharcèlement contre Brigitte Macron. Rudy Reichstadt et Tristan Mendès-France examinent les lignes de défense des dix prévenus et analysent la généalogie de la rumeur. Jugés pour cyberharcèlement à l'encontre de Brigitte Macron, dix prévenus étaient devant le tribunal correctionnel de Paris lundi et mardi. Ils ont évoqué avoir voulu faire \"de l'humour\" ou \"informer\" en relayant une infox mondiale sur sa prétendue transidentité et pédophilie. Rudy Reichstadt et Tristan Mendès-France examinent les lignes de défense des dix prévenus et analysent la généalogie de la rumeur. Publicité Il y a plusieurs leviers selon Tristan Mendès-France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques et membre de l'observatoire du conspirationnisme : \"On convoque un imaginaire qui est déjà très fertile dans la complosphère, qui est celui de d'élite supposément dégénérée, corrompue dans sa sexualité, dans l'identité sexuelle, et orientation sexuelle\". Ce genre de rumeur ne peut s'éteindre comme le dit Rudy Reichstadt, directeur de Conspiracy Watch : \"c'est une rumeur zombie, une rumeur qui refuse de mourir, aucune réfutation ne peut venir à bout\". Au départ, il y a Natacha Rey, qui se revendique journaliste indépendante, et qui commence à développer la rumeur selon laquelle Brigitte macron est un homme. Elle va contacter plusieurs médias et puis en juin 20021 selon Rudy Reichstadt…" },
  { title: "Demain les MedBeds ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/demain-les-medbeds-5322920", img: "assets/episodes/3673186d-54b6-4f9c-b0c2-37691b528d07.webp", youtube: "https://www.youtube.com/watch?v=Ev1cYJdvHNk", description: "Donald Trump a publié puis supprimé une vidéo sur son réseau social, dans laquelle il annonce des MedBeds pour tous les Américains. Une vidéo générée par IA. Ces lits médicalisés n", date: "2025-10-03", body: "Complorama Par Rudy Reichstadt Donald Trump a publié puis supprimé une vidéo sur son réseau social, dans laquelle il annonce des MedBeds pour tous les Américains. Une vidéo générée par IA. Ces lits médicalisés n'existent pas, mais ils font le lit de la complosphère ! C'est le 95è numéro de Complorama. C’est l’histoire d’un président des Etats-Unis qui publie une vidéo réalisée par Intelligence Artificielle, annonçant l'arrivée des MedBeds dans les hôpitaux américains. La vidéo du 27 septembre, imitait une émission de Fox News avec Lara Trump. Le lendemain la vidéo est retirée du compte Truth Social de Donald Trump. Interrogée par la presse, la porte-parole de la Maison Blanche Karoline Leavitt a répondu : \"Je pense que le président a vu la vidéo, l'a publiée puis l'a supprimée et il a le droit de le faire.\" Pour Rudy Reichstadt, directeur du site ConspiracyWatch : \"ça dit tout, je crois, du chaos informationnel dans lequel on est plongé\". Publicité Les MedBeds sont des lits médicalisés futuristes qui guérissent, qui rajeunissent, mais aucune technologie médicale, validée à ce jour, ne correspond aux descriptions de ces fameux MedBeds. Pour Tristan Mendès France, maître de conférences associé à l'université de Paris spécialisé dans les cultures numériques : \"cette fausse vidéo générée par sur le compte de Trump a évidemment excité toute la complosphère internationale et notamment française. On a de nombreux comptes français qui ont évidemment relayé cette vidéo, ils lui ont d…" },
  { title: "Podcast. La complosphère et l'assassinat de Charlie Kirk", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/podcast-la-complosphere-et-l-assassinat-de-charlie-kirk-6793545", img: "assets/episodes/49dc6c0f-1c11-484f-96ea-7154351a1c7f.webp", youtube: "https://www.youtube.com/watch?v=H6lNYghXN3c", description: "Cet épisode du podcast Complorama se concentre sur l", date: "2025-09-19", body: "Complorama Par Rudy Reichstadt Cet épisode du podcast Complorama se concentre sur l'assassinat de Charlie Kirk, une figure majeure de l'ultra conservatisme américain et sur les théories complotistes qui ont émergé. L'influenceur ultra-conservateur américain Charlie Kirk , porte-drapeau de la jeunesse pro-Trump, a été tué par balle mercredi 10 septembre lors d'une réunion publique dans une université de l'Utah. Pendant les deux jours qui ont séparé le meurtre de l'identification du suspect, le pays a vécu un moment de sidération. La complosphère s'y est engoufrée. Publicité La réaction a la mort de Kirk été immédiate et a touché l'ensemble du spectre politique. Donald Trump a accusé la \"gauche radicale\" sans preuve, illustrant le concept de \"complotisme sans théorie\" selon Rudy Reichstadt directeur du site ConspiracyWatch. Paradoxalement, des figures de sa propre sphère d'influence (\"magasphère\"), comme Candace Owens, Steve Bannon et Alex Jones, ont rapidement émis des doutes sur la version officielle de l'administration Trump, suggérant une manipulation des preuves par le FBI. Tristan Mendès-France, maître de conférences associé à l’université de Paris spécialisé dans les cultures numériques explique ainsi le \"syndrome Epstein\" où la suspicion se retourne contre son propre camp. À gauche, bien que la condamnation de l'acte soit unanime au sein de \"l'establishment démocrate\", des théories ont également émergé, illustrant le phénomène de \"contamination complotiste\" selon Rudy…" },
  { title: "\"Bloquons tout\" : la complosphère en embuscade le 10 septembre ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/podcast-bloquons-tout-la-complosphere-en-embuscade-le-10-septembre-9852523", img: "assets/episodes/1c9e8394-a3b3-4cf1-80fc-415d2b1af56b.webp", youtube: "https://www.youtube.com/watch?v=8M5AZHW480Q", description: "\"Le 10 septembre, le peuple reprend la main\". Si le tout premier message est apparu en mai dernier, l", date: "2025-09-05", body: "Complorama Par Rudy Reichstadt \"Le 10 septembre, le peuple reprend la main\". Si le tout premier message est apparu en mai dernier, l'appel prend de l'ampleur sur les réseaux sociaux au début du mois de juillet. La complosphère est-elle en embuscade derrière \"bloquons tout\"? C'est le sujet de nouveau numéro de Complorama. \"Bloquons tout\" : vous n'avez pas pu échapper à cet appel à la mobilisation générale. Début juillet, les premiers messages à l'origine de ce mouvement indiquent que \"le 10 septembre, le peuple reprend la main\". Ils sont publiés sur un compte appelé \"Les essentiels\" et pour Rudy Reichstadt, directeur de Conspiracy Watch, c'est le nouveau nom d'un \"cercle Saint-Eloi\" renommé au printemps dernier : \"c'était un café associatif de tendance souverainiste, un compte très clairement perméable pour pas ne pas dire imbibé de complotisme\". Publicité Les messages diffusés reprennent souvent le \"ils\" qui indiquent selon Rudy Reichstadt \"l'idée que eux ne font pas partie du peuple, le vrai peuple qui lui serait légitime à exprimer sa sa colère\"? L'appel \"bloquons tout\" est constitué de plusieurs revendications, hétérogènes et parfois contradictoires. Mais pour Rudy Reichstadt il y a \"clairement l'expression d'un ras-le-bol, d'un dégagisme, l'idée qu'ils s'en aillent tous, l'idée que la classe politique est quand même corrompue\". Pour Tristan Mendès-France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques et membre de l'observato…" },
  { title: "La Russie, l'eldorado des complotistes français", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/la-russie-l-eldorado-des-complotistes-francais-3514278", img: "assets/episodes/1688fc7c-82b6-45d5-b348-f6b44fc1fc1f.webp", youtube: "https://www.youtube.com/watch?v=xSSQ82UwGd4", description: "La Russie de Vladimir Poutine exerce une fascination sur de nombreux complotistes français. Certains n", date: "2025-06-27", body: "Complorama Par Rudy Reichstadt La Russie de Vladimir Poutine exerce une fascination sur de nombreux complotistes français. Certains n'hésitent pas à s'y rendre pour afficher des positions pro-Kremlin, comme le polémiste d'extrême droite Alain Soral ou le chanteur Francis Lalanne. Pourquoi ces Français sont-ils si bien reçus ? Lors d'une conférence à Moscou, en Russie , Alain Soral affirmait, en mai dernier, que \"Vladimir Poutine serait, dans l'époque actuelle et à venir, le Katechon qui permettrait d'empêcher le triomphe définitif du mal\". Le polémiste d'extrême droite défend ainsi le régime russe, mettant en avant la liberté d'expression et la lutte du bien contre le mal. Pour Rudy Reichstadt, directeur du site Conspiracy Watch, \"Alain Soral, polémiste national socialiste selon sa propre définition, reprend tout simplement à son compte les thèses du juriste nazi Carl Schmitt, juriste officiel du 3e Reich sur le Katechon, c'est-à-dire cette force métaphysique qui travaillerait à empêcher le règne du chaos\". Publicité **>> Russie : les complotistes français adoubés par le Kremlin Ouverture dans un nouvel onglet **Alain Soral n'est pas le seul à être très bien accueilli par la Russie. Parmi les Français présents, cette fois lors d'une cérémonie de commémoration des 80 ans de la victoire russe sur l'Allemagne nazie, le 9 mai dernier, on compte aussi Franck Pengam, fondateur du media complotiste Géopolitique profonde, qui a cette occasion a obtenu une interview de Maria Zakharov…" },
  { title: "Aux États-Unis, le complotisme contre la science", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/aux-etats-unis-le-complotisme-contre-la-science-1168735", img: "assets/episodes/38dabc9b-ce8e-46c3-9920-57d1dc9fb632.webp", youtube: "https://www.youtube.com/watch?v=BXVF2D9G9bc", description: "Depuis le début du second mandat de Donald Trump, la science et ses institutions subissent des attaques sans précédent aux États-Unis. Les coupes budgétaires, les purges sémantiques, ou encore les menaces et intimidations visent universités, revues scientifiques et agences de l", date: "2025-06-13", body: "Complorama Par Rudy Reichstadt Depuis le début du second mandat de Donald Trump, la science et ses institutions subissent des attaques sans précédent aux États-Unis. Les coupes budgétaires, les purges sémantiques, ou encore les menaces et intimidations visent universités, revues scientifiques et agences de l'État, tandis que les plus hauts responsables relaient des théories directement issues de la complosphère. \"8 millions de dollars pour rendre des souris transgenres !\", dénonçait le président américain Donald Trump le 30 mai dernier devant les caméras présentes dans le bureau ovale à la Maison blanche. Il a annoncé de nouvelles coupes budgétaires pour \"arrêter le gaspillage\" dont il accuse les scientifiques financés par l'État américain, déjà largement touchées par des mesures drastiques depuis son retour au pouvoir en janvier dernier. Des allégations \"lunaires\" contre des recherches qui n'ont \"rien à voir avec l'identité de genre\" mais \"essentielles pour des avancées sur le cancer, la fertilité ou les hormones\", analyse Tristan Mendès-France, maître de conférences associé à l'université de Paris, spécialisé dans les cultures numériques. Une séquence cependant \"symptomatique\" de \"l'acculturation scientifique au plus haut niveau de l'État américain, alimenté par la désinformation et le complotisme\". Publicité Au-delà des coupes drastiques dans les budgets des agences fédérales et des licenciements qui les accompagnent, le président américain a signé plusieurs décrets inter…" },
  { title: "\"Génocide blanc\" en Afrique du Sud : itinéraire d'une théorie complotiste", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/genocide-blanc-en-afrique-du-sud-itineraire-d-une-theorie-complotiste-3138298", img: "assets/episodes/667ca888-078b-4b77-ba45-ebfc46b4df04.webp", youtube: "https://www.youtube.com/watch?v=htJOWGqdfPw", description: "En recevant le président sud-africain dans le bureau ovale, Donald Trump a diffusé des vidéos montrant, selon lui, des \"familles entières\" d", date: "2025-05-30", body: "Complorama Par Rudy Reichstadt En recevant le président sud-africain dans le bureau ovale, Donald Trump a diffusé des vidéos montrant, selon lui, des \"familles entières\" d'agriculteurs blancs fuyant leurs terres. Pour le président américain, les agriculteurs blancs sud-africains sont victimes d’un \"génocide\". \"C'est un génocide qui est en train de se passer\" : lors d’une conférence de presse , le 12 mai dernier, Donald Trump affirmait devant les médias que \"des fermiers blancs sont brutalement tués et leurs terres confisquées en Afrique du Sud\". Quelques mois plus tôt, le 7 février, le président américain signait un décret pour créer une procédure d’asile pour les \"réfugiés afrikaners\" et encourager leur réinstallation aux États-Unis. Mais c'est lors d'une rencontre avec le président sud-africain Cyril Ramaphosa que Donald Trump a prononcé des affirmations non étayées, présentant devant la presse des vidéos censées montrer des familles d'agriculteurs blancs fuyant leurs terres. Décrivant une situation \"terrible\", le président américain a soutenu que les fermiers blancs étaient \"brutalement tués\" et que \"leurs terres sont confisquées\". Publicité À écouter Les Etats-Unis accueillent des Afrikaners, victimes d'un \"génocide\" en Afrique du Sud, selon Donald Trump D'un monde à l'autre 2 min Mais aucune donnée ne permet aujourd'hui de parler ni de génocide ni de persécution systématique des Blancs en Afrique du Sud. \"Donald Trump va enchaîner les contre-vérités en sortant des docum…" },
  { title: "Roumanie, le complotisme à l'heure des élections", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/roumanie-le-complotisme-a-l-heure-des-elections-4919353", img: "assets/episodes/0f69178e-0e7a-473f-ad26-b594cb4a2de6.webp", youtube: "https://www.youtube.com/watch?v=UMI0Xl2gRbQ", description: "À deux jours de l’élection présidentielle roumaine, les théories complotistes s’invitent dans le débat électoral. Nationaliste, antivax et fan de Donald Trump, le candidat d’extrême droite George Simion donne du grain à moudre à la sphère complotiste déjà bien implantée en Roumanie.", date: "2025-05-16", body: "Complorama Par Rudy Reichstadt À deux jours de l’élection présidentielle roumaine, les théories complotistes s’invitent dans le débat électoral. Nationaliste, antivax et fan de Donald Trump, le candidat d’extrême droite George Simion donne du grain à moudre à la sphère complotiste déjà bien implantée en Roumanie. \"Je pense que nous avons complètement démoli les mondialistes ici, en Roumanie, nous avons gagné\", s'est exprimé Georges Simion le 5 mai dernier au micro de Steeve Bannon dans son podcast WarRoom, bien connu pour son penchant complotiste. À l'issue du premier tour des élections présidentielles, le candidat roumain d'extrême droite Ouverture dans un nouvel onglet a récolté plus de 40% des voix Ouverture dans un nouvel onglet . Ce dimanche, il affrontera l'actuel maire de Bucarest, le centriste et pro-européen Nicușor Dan. Deux candidats que tout oppose. Publicité Alors que la Covid 19 relèverait d'une \"dictature sanitaire\", la Moldavie serait un pays \"artificiel\". Le nationaliste George Simion est friand des théories complotistes. \"Outre le fait qu'il soit lui-même un fan absolu de Donald Trump, on le voit surtout fricoter avec la frange radicale et complotiste des fans de Trump\", observe Tristan Mendès France. Son intervention au micro de l'ancien conseiller à la Maison Blanche Steeve Bannon n'est pas son unique apparition auprès des proches du président américain. Pour Tristan Mendès France : \"Ces interventions médiatiques s'inscrivent dans une stratégie de rapproc…" },
  { title: "Quatre-vingt ans après, la mort d’Adolf Hitler réveille la complosphère", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/quatre-vingt-ans-apres-la-mort-d-adolf-hitler-reveille-la-complosphere-8831796", img: "assets/episodes/7350df6c-7798-420f-a84f-731b987286a8.webp", youtube: "https://www.youtube.com/watch?v=UyE7gAmLn1k", description: "Quatre-vingt ans après sa mort, les théories complotistes autour d", date: "2025-05-02", body: "Complorama Par Rudy Reichstadt Quatre-vingt ans après sa mort, les théories complotistes autour d'Adolf Hitler persistent : survie en Argentine, fausses généalogies, mythes technologiques... Des récits servant une \"normalisation plutôt inquiétante de la réécriture de l'histoire\". Le 30 avril 1945, Adolf Hitler se retrouve réfugié dans un bunker sous Berlin dévasté. Cerné par les flammes de la guerre qu’il a déclenchée, le Führer et son épouse se suicident. Mais sa figure continue d'animer la sphère complotiste. Loin des faits historiques établis, de nombreuses théories persistent, suggérant qu'il aurait survécu et se serait réfugié en Amérique du Sud. Ce récit, ancien mais régulièrement réactivé, a récemment refait surface suite à la déclassification de documents sur les criminels nazis installés en Argentine après la Seconde Guerre mondiale. Publicité À lire aussi \"Il y a eu une résistance au nazisme\" en Allemagne : l'historien Luc Mary raconte les 42 tentatives d'assassinat contre Adolf Hitler Le monde d'Élodie 16 min Ces théories, populaires sur des plateformes comme YouTube, notamment via l'émission Redacted News, décrivent une évasion rocambolesque d'Hitler, utilisant des tunnels souterrains pour rejoindre une piste d'atterrissage, puis s'enfuyant à bord de sous-marins vers l'Argentine. Selon ces récits, il y aurait vécu près de vingt ans, installant une sorte de \"deuxième base d'opération\" pour le Troisième Reich, avec la complicité des Alliés. Ces documents argentins…" },
  { title: "Canada : le complotisme à l'heure des élections", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/canada-le-complotisme-a-l-heure-des-elections-6097449", img: "assets/episodes/608a20cb-8a6d-4cea-ba14-5edeedc1b12f.webp", youtube: "https://www.youtube.com/watch?v=zQemCvFC6Js", description: "À la fin du mois, les Canadiens se rendront aux urnes afin de voter aux élections fédérales anticipées afin d", date: "2025-04-18", body: "Complorama Par Rudy Reichstadt À la fin du mois, les Canadiens se rendront aux urnes afin de voter aux élections fédérales anticipées afin d'élire les 343 députés de la 45e législature de la Chambre des communes du Canada. Une séquence électorale sous tension, la complosphère n’étant jamais très loin des débats. Le 28 avril, c’est jour de vote pour les Canadiens. Ils devront voter aux élections fédérales anticipées afin d'élire les 343 députés de la 45e législature de la Chambre des communes du Canada. Dans un contexte politique tendu marqué par la démission de Justin Trudeau, la complosphère s'invite dans les débats, opposant notamment Mark Carney, l'actuel chef du gouvernement libéral, à son principal rival, le conservateur Pierre Poilièvre. Publicité La campagne électorale canadienne est marquée par la présence de théories conspirationnistes qui ne sont jamais loin des discussions. La vidéo du complotiste américain Alex Jones apportant son soutien à Pierre Poilièvre, en avril 2024, a suscité une vive réaction au Canada. Justin Trudeau avait d'ailleurs réclamé une condamnation de la part de Pierre Poilièvre, surnommé le \"Trump canadien\". Selon Rudy Reichstadt, ce n'est pas sans raison, car le candidat a adopté une rhétorique populiste très forte, s'inspirant de Donald Trump en critiquant les élites et en défendant la liberté individuelle contre les abus de l'État. Il avait également soutenu en 2022 le \"convoi des libertés\", un mouvement anti mesures sanitaires où se mêlaie…" },
  { title: "L'Otan dans l’imaginaire complotiste", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/l-otan-dans-l-imaginaire-complotiste-4006197", img: "assets/episodes/af581429-e89d-4948-985d-2b990f4c476d.webp", youtube: "https://www.youtube.com/watch?v=w3FytzenhWE", description: "Alors que Donald Trump remet en question l", date: "2025-04-04", body: "Complorama Par Rudy Reichstadt Alors que Donald Trump remet en question l'engagement des États-Unis au sein de l'OTAN, la complosphère s'empare de cette prise de distance pour accuser l'Alliance d'être responsable de la guerre en Ukraine, de manipuler des mouvements sociaux et même de se cacher derrière les chemtrails. Comment l'Otan, l'Organisation du traité de l'Atlantique nord, est-elle devenue une cible privilégiée des théories du complot ? Ces dernières semaines, Donald Trump a torpillé l'Alliance atlantique, multipliant les déclarations Ouverture dans un nouvel onglet allant contre cette alliance politico-militaire créée le 4 avril 1949. Ses prises de position n'ont pas manqué de faire réagir les complotistes. Mais de quoi accusent-ils l'Otan ? Publicité L'invasion russe de l'Ukraine a ravivé une théorie complotiste pro-Kremlin selon laquelle cette action militaire serait une réponse préventive à l'encerclement de la Russie par l'Otan. Selon les tenants de cette idée, comme l'influenceur Le Raptor, figure de l'extrême droite pro-Kremlin, la Russie aurait été \"acculée à la guerre par l'Otan\". Rudy Reichstadt souligne que Le Raptor reprend une \"antienne des agents d'influence de Vladimir Poutine en Europe\". Il est important de rappeler que l'Otan n'est pas en guerre contre la Russie et que l'Ukraine n'est même pas membre de l'alliance. De plus, la Russie ne partage que 11% de ses frontières terrestres avec des pays de l'Otan, démentant l'idée d'un encerclement. Au-delà d…" },
  { title: "Le Covid-19, la grande bascule complotiste", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/le-covid-19-la-grande-bascule-complotiste-9607240", img: "assets/episodes/1440277b-54f0-4442-8ed7-3cc69acd5078.webp", youtube: "https://www.youtube.com/watch?v=lJOadM9Rpg0", description: "La pandémie de Covid-19 a marqué un tournant majeur dans l", date: "2025-03-21", body: "Complorama Par Rudy Reichstadt La pandémie de Covid-19 a marqué un tournant majeur dans l'histoire du complotisme, agissant comme un catalyseur pour l'émergence et la propagation de nombreuses théories. L'épisode explore en profondeur ce phénomène avec les analyses de Rudy Reichstadt et Tristan Mendès France. Il y a cinq ans, le monde basculait avec la pandémie de Covid-19 . Trois confinements, une campagne de vaccination massive, un pass sanitaire… Et avec le virus, un foisonnement de théories du complot : le Covid-19 n'existe pas, la pandémie est planifiée, Big Pharma tire les ficelles... Publicité Dès les premiers jours de la pandémie, une trame conspirationniste s'est mise en place à une vitesse fulgurante. Selon Rudy Reichstadt, \"dès le 20 janvier 2020, le moment où on parle du début de cette pandémie, En réalité, en 24 heures à 48 heures, on a toute la dramaturgie complotiste qui va servir de toile de fond à à toute la crise sanitaire qui est déjà en place\". Cette dramaturgie mettait en scène des puissances occultes, Big Pharma comme une entité unique et toute-puissante, et l'idée de projets criminels de dépopulation. À lire aussi Covid-19, une pandémie sans fin La pandémie de Covid-19 a créé un contexte particulièrement propice à l'essor des théories du complot. Tristan Mendès France souligne que l'une des particularités notables de ce moment, \"c'est le fait qu'il a frappé de de plein fouet l'univers de l'intime\". Que ce soit par la contamination, la vaccination, les…" },
  { title: "Quand le pape François était dans le viseur des complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/le-pape-dans-le-viseur-des-complotistes-8271047", img: "assets/episodes/1f51722b-7300-49ff-aec5-892c26d458ac.webp", youtube: "https://www.youtube.com/watch?v=w0VtdU36n1A", description: "Le pape François était-il secrètement un franc-maçon, un agent du nouvel ordre mondial, ou même un pédocriminel ? Le souverain pontife argentin, mort lundi à l", date: "2025-03-07", body: "Complorama Par Rudy Reichstadt Le pape François était-il secrètement un franc-maçon, un agent du nouvel ordre mondial, ou même un pédocriminel ? Le souverain pontife argentin, mort lundi à l'âge de 88 ans, était devenu une cible de choix pour les complotistes de tous bords. Cet épisode a été enregistré et diffusé avant la mort du Pape François, lundi 21 avril. Publicité Le pape François , mort lundi 21 avril à l'âge de 88 ans, était au centre des pires rumeurs et théories, après son hospitalisation à Rome pour une bronchite, mi-février. Premier souverain pontife sud-américain, Jorge Bergoglio était devenu le 266e chef de l'Eglise catholique le 13 mars 2013. Le pape François était devenu une cible privilégiée des complotistes, des accusations de franc-maçonnerie aux allégations de pédocriminalité, en passant par son rôle supposé dans un nouvel ordre mondial. Les positions progressistes du pape François sur des sujets tels que la désinformation et l'immigration lui ont valu l'hostilité des complotistes. Rudy Reichstadt souligne que le pape avait \"tout pour déplaire aux manipulateurs de l'info\", notamment en raison de sa dénonciation de la désinformation et de son soutien au fact-checking. Son ouverture envers les pauvres et les étrangers, symbolisée par son choix du nom de François en hommage à Saint-François d'Assise, est également mal perçue par les tenants du catholicisme identitaire. Le fait que le pape François soit le premier pape jésuite de l'histoire réactive de vieill…" },
  { title: "Des services secrets américains au Mossad, le monde du renseignement au cœur du complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/des-services-secrets-americains-au-mossad-le-monde-du-renseignement-au-coeur-du-complotisme-7667491", img: "assets/episodes/050e560b-bcc8-4f5c-b736-5bebfd597917.webp", youtube: "https://www.youtube.com/watch?v=b2cUmWgxkSE", description: "Aux Etats-Unis, après Tulsi Gabbard à la tête du renseignement national, c", date: "2025-02-21", body: "Complorama Par Rudy Reichstadt Aux Etats-Unis, après Tulsi Gabbard à la tête du renseignement national, c'est Kash Patel qui prend les rênes du FBI. Une vague de nominations qui interroge, quand on sait que ces personnalités flirtent avec le conspirationnisme. L'occasion pour Complorama de s'intéresser aux services secrets. Donald Trump place ses pions au sein des services secrets américains. Jeudi 20 février, Kash Patel, ancien procureur fédéral de 44 ans, a été confirmé comme chef du FBI à une voix près, par le Sénat. Une figure \"extrêmement virulente\" et populaire dans la complosphère américaine pour Tristan Mendès France qui décrit un personnage a l'\"empreinte complotiste marquée\". Quelques semaines plus tôt, Tulsi Gabbard, ancienne députée de l'aile gauche démocrate, pro-russe, a été confirmée par le Sénat à la direction du renseignement américain. Rudy Reichstadt souligne que \"le plus inquiétant, c'est que tous ces gens dans l'administration de Trump ont un tropisme conspirationniste très prononcé\". Publicité D'anciennes figures du renseignement ont pu basculer dans le complotisme ou du moins relayer la propagande russe. Rudy Reichstadt mentionne le cas d'un ancien analyste de la CIA, accusant l'USAID d'être un outil de manipulation et de propagande. Une rhétorique souvent utilisée par les complotistes pour dénaturer les actions de promotion de la démocratie et des droits de l'Homme à l'étranger. La CIA se trouve régulièrement au centre de récits conspirationnistes, co…" },
  { title: "L'intelligence artificielle et le complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/l-intelligence-artificielle-et-le-complotisme-9921300", img: "assets/episodes/d873fe82-d929-4294-9b4f-85373a924e27.webp", youtube: "https://www.youtube.com/watch?v=T0_z5MTpuzs", date: "2025-02-07", body: "Complorama Par Rudy Reichstadt A l'occasion du sommet mondial sur l'intelligence artificielle à Paris, Complorama s'intéresse à cette technologie, utilisée pour alimenter et propager les théories du complot. Elle peut aussi, dans certains cas, être un levier pour lutter contre les dérives complotistes. L'intelligence artificielle (IA) est devenue un outil puissant, capable de générer des contenus à la fois crédibles et trompeurs. Les plateformes comme TikTok sont inondées de vidéos créées par IA, souvent basées sur des théories complotistes. Ces vidéos, dont la voix, le texte et l'image sont générés par IA, sont produites à une échelle quasi industrielle. Cette facilité de production a créé un véritable business, où des comptes monétisent ces contenus en attirant un large public. \"C'est vrai qu'aujourd'hui, il y a des outils qui permettent en un clic de faire à la fois la génération de l'histoire que l'on veut écrire, explique Ari Kouts, consultant spécialisé en innovation technologique, invité de Complorama. Et il y a un vrai business parce qu'il n'y a pas besoin de faire des millions de vues pour chaque vidéo. Il y a besoin de faire des millions de vidéos avec quelques vues et ça fera à peu près le même revenu derrière si on arrive à avoir assez de vues. Donc c'est une façon de pousser aussi du contenu comme ça.\" Publicité À lire aussi ChatGPT : l'intelligence artificielle au service du complotisme ? Complorama 28 min Parallèlement, le coût de production de la désinformati…" },
  { title: "Le négationnisme et la complosphère", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/le-negationnisme-et-la-complosphere-7276248", img: "assets/episodes/858c9f7c-14fa-45dc-b76a-1b5ed45a042d.webp", youtube: null, description: "Le négationnisme, cette remise en cause du génocide des Juifs par les nazis, est un système de pensée, une idéologie qui cherche à réhabiliter le nazisme en niant les crimes de la Shoah. Cet épisode explore les racines du négationnisme, ses figures clés, et son lien étroit avec le complotisme.", date: "2025-01-24", body: "Complorama Par Rudy Reichstadt Le négationnisme, cette remise en cause du génocide des Juifs par les nazis, est un système de pensée, une idéologie qui cherche à réhabiliter le nazisme en niant les crimes de la Shoah. Cet épisode explore les racines du négationnisme, ses figures clés, et son lien étroit avec le complotisme. Le terme \"négationnisme\" a été forgé par l'historien français Henry Rousso en 1987. Il sert à distinguer cette idéologie d'une démarche scientifique ou critique, contrairement à ce que prétendent les négationnistes qui se présentent comme des \"révisionnistes\". Le négationnisme n'est pas un travail d'historiens désintéressés ; il s'inscrit dans une volonté idéologique de réhabiliter le nazisme et de nier les crimes de la Shoah. Comme l'explique Rudy Reichstadt, directeur du site Conspiracy Watch, \"nier la Shoah, c'est pas simplement nier un événement du passé. C'est aussi dire que les rescapés, ceux qui ont survécu à l'extermination et qui en témoignent sont des menteurs et qu'ils profitent de ce mensonge\". Le négationnisme est donc intrinsèquement lié à l'antisémitisme, car il contient toujours \"l'idée d'une grande escroquerie organisée par les juifs\". Publicité Vincent Reynouard est considéré comme l'un des négationnistes français les plus influents aujourd'hui. Il assume publiquement ses convictions nationales-socialistes et s'appuie sur les thèses de Robert Faurisson, autre figure majeure du négationnisme français. D'autres personnalités comme Dieudonn…" },
  { title: "Allemagne : le complotisme à l’aube des élections", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/allemagne-le-complotisme-a-l-aube-des-elections-2036685", img: "assets/episodes/5365dfef-eb64-4ecf-9e74-c5ae654458cd.webp", youtube: null, date: "2025-01-10", body: "Complorama Par Rudy Reichstadt À l'approche des élections fédérales en Allemagne, l'ingérence d'Elon Musk, soutenant l'AfD, le parti d'extrême droite, a soulevé des inquiétudes quant à l'influence du complotisme sur le processus électoral. Complorama explore cette situation ainsi que d'autres théories conspirationnistes. Elon Musk a apporté son soutien au parti d'extrême droite AfD, suscitant des réactions en Allemagne. Une influenceuse allemande, Naomi Seibt, a affirmé que l'Allemagne pourrait annuler les élections en cas de résultats défavorables pour l'AfD, en raison d'ingérences sur le réseau social X. Tristan Mendès France la décrit comme une \"figure montante de la complosphère allemande et une militante active du parti d'extrême droite AfD\". Rudy Reichstadt souligne que l'utilisation de X par Musk comme \"machine de guerre politico-idéologique\" pose un problème, bien qu'il ait le droit de soutenir qui il veut. Publicité Selon Sébastien Baer, correspondant de Radio France en Allemagne, les Allemands qu'il a pu rencontrer étaient \"tous, sans exception, choqués par ces interventions d'Elon Musk dans la campagne électorale. Ils étaient vraiment, même pour certains, sidérés\". \"Les Allemands s'inquiètent qu'Elon Musk puisse influencer un certain nombre d'électeurs parmi les plus sceptiques et les encourager, les inciter à voter pour l'AfD, pour l'extrême droite allemande qui, rappelons-le, est quand même en très bonne position.\" L'AfD et ses militants \"relayent depuis le débu…" },
  { title: "Complotisme : le guide de survie pour les fêtes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/complotisme-le-guide-de-survie-pour-les-fetes-6005608", img: "assets/episodes/7b0f657d-9104-4865-932b-2ecefb754299.webp", youtube: "https://www.youtube.com/watch?v=j5Nr3v0OnJI", description: "Les fêtes de fin d", date: "2024-12-20", body: "Complorama Par Rudy Reichstadt Les fêtes de fin d'année approchent et avec elles le risque de tensions familiales autour de la table. Ces moments de convivialité peuvent tourner au cauchemar lorsque des proches adhèrent à des théories conspirationnistes. Mode d'emploi pour y faire face. Que se passe-t-il quand un parent ou un ami tombe dans le conspirationnisme ? Comment et pourquoi peut-il en arriver là ? Et surtout : que faire pour renouer le dialogue ? Dans cet épisode de Complorama, à l'occasion des fêtes de fin d'année, Rudy Reichstadt et Tristan Mendès France analysent le moment de bascule vers le complotisme, les répercutions sur les relations et l'attitude à adopter face à un proche qui croît à des thèses complotistes. Immersion dans le quotidien de personnes grâce aux témoignages du podcast Réveillez-vous Ouverture dans un nouvel onglet de Conspiracy Watch. Publicité Selon Rudy Reichstadt, l'adhésion aux théories du complot est souvent liée à une vulnérabilité individuelle, \"l'idée d'une faille personnelle, d'une fragilité, d'un moment de vulnérabilité qui peut être lié à une période de crise, une instabilité professionnelle ou sociale, une situation d'isolement en tout cas, une frustration aussi par rapport à son travail par exemple\". Ces moments de fragilité peuvent rendre une personne plus réceptive aux discours complotistes qui offrent une explication simpliste à des situations complexes. De son côté, Tristan Mendès France souligne le rôle des événements majeurs…" },
  { title: "La communauté LGBT+, cible privilégiée des complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/podcast-la-communaute-lgbt-cible-privilegiee-des-complotistes-5393813", img: "assets/episodes/b9d8734e-be52-4b78-90b8-98218e854d6f.webp", youtube: "https://www.youtube.com/watch?v=kVHMpLOtoB0", date: "2024-12-06", body: "Complorama Par Rudy Reichstadt De l'extrême droite aux sphères antivax, découvrez comment la communauté LGBT est diabolisée et transformée en bouc émissaire par des acteurs du monde entier. \"LGBTisme\", \"pédopiégeage\", \"agenda mondialiste\"... Complorama décrypte les mécanismes d'une dangereuse panique morale. L'homosexualité serait-elle un complot orchestré par des forces obscures pour détruire la civilisation ? Des figures comme Dieudonné, Alain Soral et Christine Boutin accusent la communauté LGBT de vouloir imposer un \"agenda\" dangereux, menaçant nos enfants et nos valeurs. Publicité Cette rhétorique s'inscrit dans un courant complotiste plus large qui voit l'homosexualité non comme une orientation sexuelle, mais comme une idéologie dangereuse, un \"LGBTisme\" orchestré par des \"forces occultes\" telles que George Soros ou Klaus Schwab. La théorie du \"pédopiégeage\" LGBT est également évoquée, une théorie particulièrement inquiétante qui accuse la communauté LGBT de vouloir normaliser la pédophilie et de représenter un danger pour les enfants. De la Russie à l'Iran en passant par les États-Unis, la peur de l'autre et le rejet de la différence nourrissent une panique morale mondiale. Il existe un lien étroit et toxique entre la LGBT-phobie et le complotisme. En Russie, le mouvement LGBT est assimilé à un \"terrorisme\" et à une menace pour les valeurs traditionnelles. Des affiches électorales du parti de Vladimir Poutine dénoncent \"l'homosexualisme\" comme un danger pour la sociét…" },
  { title: "COP29 : le changement climatique dans le radar des complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/cop29-le-changement-climatique-dans-le-radar-des-complotistes-3948010", img: "assets/episodes/14508a66-86e5-4ba2-b3f0-603ce04537a8.webp", youtube: "https://www.youtube.com/watch?v=_pJJR_pR1qQ", description: "La COP29, le retour de Donald Trump, les inondations en Espagne... L", date: "2024-11-22", body: "Complorama Par Rudy Reichstadt La COP29, le retour de Donald Trump, les inondations en Espagne... L'actualité nourrit les théories du complot les plus folles. Cet épisode dissèque les discours qui nient ou minimisent le changement climatique, et analyse comment ils se propagent, de la sphère politique aux réseaux sociaux. L'élection de Donald Trump marque un tournant dans le débat sur le climat Ouverture dans un nouvel onglet . Le futur président des États-Unis a qualifié le réchauffement climatique de \"canular\" et a promis de retirer les États-Unis des accords de Paris. Ses nominations, notamment celle de Chris Wright, un climatosceptique soutenu par les pétroliers, au poste de secrétaire à l'Énergie, confirment cette orientation. La présence de personnalités comme Robert F. Kennedy Junior, qui relaie des théories complotistes comme celle des chemtrails, aux côtés de Donald Trump, est également préoccupante. Publicité **>> COP29 à Bakou : six choses à savoir sur la conférence de l'ONU pour le climat qui s'est ouverte en Azerbaïdjan Ouverture dans un nouvel onglet **La COP29 Ouverture dans un nouvel onglet a été, comme les précédentes, un terrain fertile pour les théories du complot. Tristan Mendès France observe une \"migration des communautés complotistes\" du Covid-19 et de la guerre en Ukraine vers le climat, attisée par l'actualité et les débats autour des politiques climatiques. Les inondations qui ont ravagé l'Espagne en octobre 2024 ont été l'occasion de propager de fa…" },
  { title: "Donald Trump, le retour du complotisme à la Maison Blanche", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/donald-trump-le-retour-du-complotisme-a-la-maison-blanche-8163584", img: "assets/episodes/7c9f4099-e72d-49ca-8518-dc82f09f812c.webp", youtube: "https://www.youtube.com/watch?v=Z0ubzv5t2tM", description: "Exaltée par ce nouveau mandat de Donald Trump, la sphère complotiste n’espère qu’une chose : que le futur président réforme en profondeur le pays et puisse vaincre \"l", date: "2024-11-08", body: "Complorama Par Rudy Reichstadt Exaltée par ce nouveau mandat de Donald Trump, la sphère complotiste n’espère qu’une chose : que le futur président réforme en profondeur le pays et puisse vaincre \"l'Etat profond\" qui entrave sa politique. Une obsession tenace, partagée au sein même de la garde rapprochée du président. L’élection de Donald Trump marque non seulement une victoire républicaine, mais aussi, et surtout, une victoire éclatante du complotisme. Portée par des figures influentes telles que Steve Bannon, Michael Flynn et Alex Jones, cette mouvance se réjouit du retour de Trump et nourrit des ambitions de revanche inquiétantes. Quelles sont les implications de ce triomphe du complotisme pour l'avenir de la démocratie américaine et au-delà ? Publicité Dès le soir de l'élection, le ton est donné par Steve Bannon, figure emblématique du trumpisme, qui promet un châtiment sans pitié aux \"ennemis de l'intérieur\". Cette rhétorique violente, qui fait écho aux heures les plus sombres de l'histoire, s'inscrit dans un discours complotiste qui gangrène une partie de l'Amérique. L'idée d'un \"Deep State\", d'une cabale occulte qui manipulerait les institutions, est ainsi devenue un mythe fondateur de la mouvance trumpienne, alimentant un climat de peur et de suspicion. À lire aussi Élections américaines : la revanche de Donald Trump La victoire de Donald Trump est aussi celle d'un écosystème médiatique alternatif, dominé par des podcasts et des émissions en ligne qui relaient sans re…" },
  { title: "Elon Musk, pilier complotiste de la campagne de Donald Trump", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/elon-musk-pilier-complotiste-de-la-campagne-de-donald-trump-6582061", img: "assets/episodes/5a19f149-b54e-46d2-b99f-a7bcbc26c9af.webp", youtube: "https://www.youtube.com/watch?v=hUwHW8uDeEU", description: "Le milliardaire est un fervent partisan de Donald Trump. Mais son soutien va bien au-delà des simples déclarations. Cet épisode de Complorama explore comment Elon Musk soutient activement la campagne de Donald Trump, alimentant un climat de désinformation et de manipulation.", date: "2024-10-25", body: "Complorama Par Rudy Reichstadt Le milliardaire est un fervent partisan de Donald Trump. Mais son soutien va bien au-delà des simples déclarations. Cet épisode de Complorama explore comment Elon Musk soutient activement la campagne de Donald Trump, alimentant un climat de désinformation et de manipulation. Elon Musk pourrait-il influencer le cours de l'élection présidentielle américaine Ouverture dans un nouvel onglet ? Fervent soutien au candidat républicain Donald Trump, le milliardaire est prêt à tout pour faire élire le candidat républicain, organisant des réunions publiques, finançant massivement sa campagne, et multipliant les sorties complotistes en sa faveur. Publicité >> Campagne numérique, financement massif, meetings : comment Elon Musk est devenu le premier soutien de Donald Trump pour la présidentielle Ouverture dans un nouvel onglet Depuis quelques semaines, Elon Musk organise des réunions publiques en soutien de Donald Trump dans l'État clé de Pennsylvanie. Sa dernière initiative : il a annoncé distribuer un million de dollars \"au hasard\", une fois par jour, à un électeur inscrit dans un des sept Etats clés, en échange de la signature d'une pétition conservatrice. Mais Elon Musk ne s'arrête pas là : il propage des théories du complot largement utilisées par les Républicains, comme lorsqu'il affirmait, à tort, le 18 octobre dernier que les machines à voter Dominion étaient utilisées à Philadelphie et étaient responsables de fraudes électorales en 2020. Tristan M…" },
  { title: "De l'Atlantide aux pyramides, quand la complosphère revisite les grands mythes historiques", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-l-atlantide-aux-pyramides-quand-la-complosphere-revisite-les-grands-mythes-historiques-7457279", img: "assets/episodes/dbe6beae-d06c-4330-a7ee-3808cefb6738.webp", youtube: "https://www.youtube.com/watch?v=XNJbunt1h9I", description: "Dans ce nouvel épisode de Complorama, Tristan Mendès France et Rudy Reichstadt explorent la fascination de la complosphère pour les mythes historiques, examinant comment ces récits sont déformés et instrumentalisés à des fins idéologiques.", date: "2024-10-11", body: "Complorama Par Rudy Reichstadt Dans ce nouvel épisode de Complorama, Tristan Mendès France et Rudy Reichstadt explorent la fascination de la complosphère pour les mythes historiques, examinant comment ces récits sont déformés et instrumentalisés à des fins idéologiques. Pourquoi les grands mythes de notre Histoire passionnent tant les complotistes ? La série À l'aube de notre histoire, qui défend l'existence d'une civilisation technologiquement avancée disparue à la fin de l'ère glaciaire, fait son grand retour sur Netflix pour une deuxième saison, après une première saison critiquée par les archéologues. Publicité \"En réalité, les livres et les films de Hancock sont considérés par les scientifiques comme relevant de la pseudoscience\", souligne Rudy Reichstadt. La série documentaire alimente un discours anti-science en présentant Hancock comme un lanceur d'alerte face à un establishment scientifique qui cacherait la vérité. \"Une partie du succès de sa série, c'est de se positionner comme une sorte de résistant à la pensée unique scientifique\", analyse Tristan Mendès France. Dans la première saison, un épisode était consacré au mythe de l'Atlantide. Graham Hancock, le narrateur de la série, n'affirme pas que l'Atlantide se trouve aux Bahamas, mais il utilise ce mythe pour appuyer sa théorie d'une civilisation avancée disparue lors de la dernière période glaciaire. \"L’Atlantide c’est la preuve qu’on peut écrire, produire, rêver de quelque chose qui n’existe pas pendant des siè…" },
  { title: "États-Unis : quand le complotisme s'installe dans la campagne présidentielle", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/etats-unis-quand-le-complotisme-s-installe-dans-la-campagne-presidentielle-2368490", img: "assets/episodes/c721ab86-6c84-448b-9296-5f662ee8e659.webp", youtube: "https://www.youtube.com/watch?v=-mjyA1iQylc", description: "Les théories du complot sont la raison de vivre des partisans de Donald Trump, qui semblent préférer cette vérité alternative où Kamala Harris se servirait du vote des immigrés pour truquer l", date: "2024-09-27", body: "Complorama Par Rudy Reichstadt Les théories du complot sont la raison de vivre des partisans de Donald Trump, qui semblent préférer cette vérité alternative où Kamala Harris se servirait du vote des immigrés pour truquer l'élection ou que l'Etat profond aurait tenté d'assassiner leur candidat. Après 2016, puis 2020, une partie de l'électorat américain a glissé vers un complotisme assumé. Leur nouvelle cible : Kamala Harris. Le sénateur américain J. D. Vance, colistier de Donald Trump Ouverture dans un nouvel onglet , affirme lors d'un rassemblement le 5 septembre dernier que les démocrates soutiennent la fraude électorale : ils veulent que les immigrés clandestins \"volent le vote de tout le monde\". L'un de leur argument phare : les démocrates chercheraient à faire voter les personnes qui n'ont pas la nationalité américaine. Sauf que les étrangers n'ont pas le droit de voter aux élections fédérales, ni aux élections présidentielles. Comme le souligne Rudy Reichstadt, l'immigration est utilisée comme une arme pour \"truquer\" et donc \"voler\" l'élection. Publicité >> Présidentielle américaine : Donald Trump tiendra un meeting sur les lieux de sa tentative d'assassinat en Pennsylvanie Ouverture dans un nouvel onglet **Pendant ce temps, Donald Trump continue d'affirmer sans preuve sur son réseau Truth Social que le Parti démocrate incite les migrants à entrer illégalement afin de les faire voter pour Kamala Harris. Pour Tristan Mendès France, les discours anti migrants ont des cons…" },
  { title: "D'Hugo Chavez à Nicolas Maduro, le complotisme au Venezuela", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/d-hugo-chavez-a-nicolas-maduro-le-complotisme-au-venezuela-4295612", img: "assets/episodes/921477a4-5d13-4105-bb0b-a420df25dd00.webp", youtube: "https://www.youtube.com/watch?v=RkG4HGkkJp8", description: "Nicolas Maduro a été réélu à la tête du Venezuela le 28 juillet dernier, mais l’opposition dénonce une fraude électorale massive. Tristan Mendès France et Rudy Reichstadt décryptent et analysent les théories du complot dont est friand le régime vénézuélien.", date: "2024-09-13", body: "Complorama Par Rudy Reichstadt Nicolas Maduro a été réélu à la tête du Venezuela le 28 juillet dernier, mais l’opposition dénonce une fraude électorale massive. Tristan Mendès France et Rudy Reichstadt décryptent et analysent les théories du complot dont est friand le régime vénézuélien. Alors que Nicolas Maduro a été réélu à la présidence du Venezuela, le 28 juillet dernier, le camp opposé évoque une élection truquée. Son candidat Edmundo Gonzalez Urrutia Ouverture dans un nouvel onglet a trouvé refuge le 8 septembre en Espagne. Cette élection fait ressurgir diverses théories du complot dont est friand le régime vénézuélien. Publicité Répression des manifestations, arrestations des leaders de l'opposition, le président y voit un complot international pour le renverser... Avant lui, les théories du complot autour du \"Comandante\" avaient de nombreux partisans. Il affirme même l'opposition \"financée\" par une conspiration juive mondiale. >> REPORTAGE. \"Nous irons jusqu'au bout !\" : au Venezuela, un mois après la victoire contestée de Nicolas Maduro à la présidentielle, ses opposants à nouveau dans la rue Ouverture dans un nouvel onglet Dans ses prises de parole, Nicolas Maduro accuse le \"sionisme international\" de soutenir la contestation postélectorale. Sur ce complot juif mondial, \"le thème du 'sionisme international' est mobilisé régulièrement par les chavistes depuis plus de 20 ans\", note Rudy Reichstadt, directeur de Conspiracy Watch. Le président vénézuélien est un adepte…" },
  { title: "Les Jeux olympiques du complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/podcast-les-jeux-olympiques-du-complotisme-8352365", img: "assets/episodes/3c8b7205-5bce-4520-8823-3fe3088ad08b.webp", youtube: null, description: "Un plan secret de propagation d", date: "2024-06-28", body: "Complorama Par Rudy Reichstadt Un plan secret de propagation d'un virus, un projet d'attaque terroriste ou nucléaire... De nombreuses théories complotistes visant les Jeux de Paris 2024 circulent depuis plusieurs mois sur les réseaux sociaux. Mais l'olympisme inspire la sphère conspirationniste depuis au moins les années 70. \"Si j'étais à la tête d'un Etat comme Israël par exemple, qu'est-ce que je chercherais à faire aux Jeux olympiques? Je chercherais à faire un attentat qui soit imputable aux Palestiniens pour essayer de faire décroître leur cote dans le monde entier. Ce genre d'actions sous faux drapeau serait une bénédiction pour Israël\", déclare Dominique Delawarde dans une vidéo publiée sur X Ouverture dans un nouvel onglet le 1er avril 2024. Publicité >> Paris 2024 : une campagne de désinformation liée à l'Azerbaïdjan a ciblé les Jeux olympiques, selon un rapport Ouverture dans un nouvel onglet Ce militaire à la retraite, connu pour \"ses propos jugés antisémites et complotistes\", rappelle Rudy Reichstadt, développe une rhétorique classique de la sphère complotiste : l'attentat sous faux drapeau. \"O__n ne compte plus les attentats réels ou supposés attribués à Israel ou le Mossad, explique Tristan Mendès France. On peut remonter aux attentats du 11 septembre voire plus loin encore. Ce qui est intéressant ici c’est que l'intervenant cherche à mélanger deux sujets pour maximiser l’impact de son récit complotiste : d’un côté, le conflit entre le Hamas et Israel avec cet…" },
  { title: "Dissolution de l'Assemblée nationale, élections européennes… La complosphère en embuscade", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/dissolution-de-l-assemblee-nationale-elections-europeennes-la-complosphere-en-embuscade-3069262", img: "assets/episodes/b8f730bc-9032-447f-b053-a8e43bde0e44.webp", youtube: null, description: "Alors que la campagne des élections européennes a été une occasion pour certains candidats de diffuser leur discours complotiste et de crier à la fraude électorale, l", date: "2024-06-11", body: "Complorama Par Rudy Reichstadt Alors que la campagne des élections européennes a été une occasion pour certains candidats de diffuser leur discours complotiste et de crier à la fraude électorale, l'annonce de la dissolution de l'Assemblée nationale par le chef de l'État n'a pas manqué de faire réagir la complosphère. Après le succès du Rassemblement national , arrivé largement en tête lors des élections européennes du 9 juin avec 31,37% des voix, Emmanuel Macron a décidé de dissoudre l'Assemblée nationale et de convoquer des élections législatives anticipées, prévues les dimanches 30 juin et 7 juillet. L'annonce a fait basculer la soirée dans une autre dimension. \"Seul point commun entre Macron et Bardella aujourd'hui : la franc-maçonnerie, car c'est bien le Grand Orient de France qui est bien sûr derrière tout cela à la manœuvre\", réagit Richard Boutry, quelques heures après l'annonce de la dissolution. \"On a un exemple assez caricatural, estime Tristan Mendès France, mais de façon plus globale, à chaque moment de crise institutionnelle, on a toujours un moment propice à l'effervescence, à l'activisme complotiste, et on a des tentatives assez flagrantes de captation de l'attention de ce moment spécifique.\" Publicité À écouter La dissolution est-elle vraiment une arme présidentielle ? Le vrai ou faux 1 min La petite musique du complotisme électorale s'est une nouvelle fois fait entendre après les résultats. \"On a fait zéro voix ou très très peu de voix parce que nos bulletin…" },
  { title: "Les prophéties apocalyptiques de la complosphère", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/les-propheties-apocalyptiques-de-la-complosphere-2242962", img: "assets/episodes/1c75b530-af7d-4184-b30a-dfd7b9ea3e55.webp", youtube: null, description: "La complosphère s’empare des grandes peurs qui traversent nos sociétés, réactivant le thème de la \"fin du monde\". Les complotistes se sont engouffrés dans la brèche à coup de prophéties erronées, de prédictions de \"guerre thermonucléaire\" ou de \"génocide vaccinal\" démenties par la réalité.", date: "2024-05-28", body: "Complorama Par Rudy Reichstadt La complosphère s’empare des grandes peurs qui traversent nos sociétés, réactivant le thème de la \"fin du monde\". Les complotistes se sont engouffrés dans la brèche à coup de prophéties erronées, de prédictions de \"guerre thermonucléaire\" ou de \"génocide vaccinal\" démenties par la réalité. \"Notre pays est en désordre, nos frontières sont ouvertes et peu sûres. Neuf mois, c'est long. Pendant cette période, il y a de fortes chances que la troisième guerre mondiale éclate, parce que nous avons quelqu'un qui ne fait pas son travail correctement.\" Interviewé par la chaîne de télévision américaine Fox News, Donald Trump Ouverture dans un nouvel onglet prédisait, le 4 février dernier, un conflit mondial avant la prochaine élection présidentielle en novembre prochain. Publicité Un \"véritable gimmick chez Donald Trump, une corde qu'il va tirer de nombreuses fois durant son mandat et même après, note Tristan Mendès France. C'est une technique qui vise à sidérer son auditoire et radicaliser les opinions.\" L'ex-président n'en est pas à sa première tentative : \"Il l'a fait de nombreuses fois, notamment en novembre 2023, où il expliquait qu'il avait déjà tout prédit et qu'il prévoyait une Troisième Guerre mondiale\". Selon Tristan Mendès France, un conflit n'est pas à écarter, mais le discours de Donald Trump \"a souvent une charge complotiste flagrante\". Le thème de Troisième Guerre mondiale Ouverture dans un nouvel onglet est très fort dans l'imaginaire cons…" },
  { title: "Le complotisme en Inde à l'heure des élections", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/le-complotisme-en-inde-a-l-heure-des-elections-2115883", img: "assets/episodes/2cfe5e6a-4f87-4289-bd3d-0e61fdcc82c5.webp", youtube: null, description: "Les électeurs indiens se pressent dans les bureaux de vote pour élire les 543 députés de la chambre basse du Parlement. Au pouvoir depuis dix ans, le Premier ministre Narendra Modi mène sur la \"plus grande démocratie du monde\" une politique autoritaire où le complotisme n’est jamais loin.", date: "2024-05-14", body: "Complorama Par Rudy Reichstadt Les électeurs indiens se pressent dans les bureaux de vote pour élire les 543 députés de la chambre basse du Parlement. Au pouvoir depuis dix ans, le Premier ministre Narendra Modi mène sur la \"plus grande démocratie du monde\" une politique autoritaire où le complotisme n’est jamais loin. C’est un scrutin hors-norme : près d'un milliard de citoyens sont appelés au urnes jusqu'au 1er juin. Les élections législatives se déroulent depuis le 19 avril, six semaines durant lesquelles les électeurs se pressent dans les bureaux de vote pour élire les 543 députés de la chambre basse du Parlement. Au total, plus d’un million de bureaux de votes déployés à travers le pays. Publicité À lire aussi Face à la dérive autoritaire de Modi, l'Inde est-elle encore la plus grande démocratie du monde ? Le choix de franceinfo 4 min Le Premier ministre nationaliste hindou Narendra Modi est le favori de cette élection. Il se présente pour un troisième mandat consécutif. Son parti, le BJP, est à la tête de l'Alliance démocratique nationale (NDA). Face à la machine électorale élaborée par Narendra Modi, l’opposition indienne réunie au sein de la coalition \"India\" éprouve toutes les peines du monde à exister. Le Congrès, le principal parti d’opposition dirigé par Raoul Gandhi, n’a pas pu mener une campagne digne de ce nom. Existe-t-il un complotisme utilisé à des fins électorales ? \"Il y a un complot qui est fréquemment agité, c'est celui des forces étrangères qui cherche…" },
  { title: "Agent du Pentagone, rituels sataniques, Illuminati... Taylor Swift au cœur de théories du complot", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/taylor-swift-au-coeur-de-theories-du-complot-7000036", img: "assets/episodes/3e2dc28b-1fa6-4e42-a049-a7db94657267.webp", youtube: null, description: "À seulement 34 ans, la pop star devient la première artiste milliardaire uniquement grâce aux revenus de sa musique. Une notoriété qui n", date: "2024-04-30", body: "Complorama Par Rudy Reichstadt À seulement 34 ans, la pop star devient la première artiste milliardaire uniquement grâce aux revenus de sa musique. Une notoriété qui n'est pas sans conséquence pour l'icône pop devenue la cible de fake news, de deepfakes et de théories conspirationnistes. L'événement est tel qu'il a même fait planter la billetterie sur Internet, incapable de gérer l'afflux des fans : Taylor Swift débarque en France Ouverture dans un nouvel onglet avec sa tournée \"The Eras Tour\" pour une série de concerts à la Défense Arena à Paris, du 9 au 12 mai prochain. À peine sorti, son 11e album Ouverture dans un nouvel onglet a encore une fois explosé tous les records Ouverture dans un nouvel onglet . Taylor Swift remplit les stades du monde entier et inspire les théories du complot en tout genre. Publicité >> Taylor Swift, cible de théories complotistes avant la présidentielle américaine Ouverture dans un nouvel onglet À quelques mois de la présidentielle américaine 2024 Ouverture dans un nouvel onglet , une théorie complotiste circule aux Etats-Unis, lancée par des figures d'extrême droite sur des médias conservateurs, accusant la chanteuse pop d'être partie prenante dans une opération de déstabilisation psychologique destinée à truquer la prochaine élection présidentielle et à faire réélire Joe Biden. \"Le ministère américain de la Défense aurait recruté la chanteuse en vue d'inciter les gens à voter pour Joe Biden, c'est de la pure affabulation, note Rudy Reichstadt…" },
  { title: "Les \"citoyens souverains\", de la contestation au complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/les-citoyens-souverains-de-la-mouvance-contestataire-au-complotisme-9016330", img: "assets/episodes/aa11e04b-13dc-4578-9ebc-2bb4cb6eccdc.webp", youtube: null, description: "La vidéo d", date: "2024-04-16", body: "Complorama Par Rudy Reichstadt La vidéo d'un couple qui refuse de se soumettre à un test d'alcoolémie de la gendarmerie est devenue virale sur les réseaux sociaux la semaine dernière. Ils se présentent comme étant des \"citoyens souverains\". Du refus de l'autorité jusqu’au complotisme, quelles sont leurs croyances ? \"On ne contracte pas\", la phrase issue d'une vidéo a cumulé des millions de vues Ouverture dans un nouvel onglet sur les réseaux sociaux la semaine dernière. Sur cette vidéo, un couple d'automobilistes est arrêté par la gendarmerie des Hauts-de-France pour un contrôle routier. Le couple refuse de se soumettre à un test d'alcoolémie et explique, \"Je ne contracte pas avec une société privée. Je n'appartiens plus à l'entreprise française présidence\", explique l'homme. Pour justifier leur refus, ils affirment être \"citoyens souverains\", une mouvance complotiste qui refuse l'autorité de l'État. Publicité Issus à la base d'une mouvance contestataire, les \"citoyens souverains\" refusent toute autorité établie. Il ne respectent pas les lois, ne paient pas leurs impôts et vont jusqu'à refuser l'utilisation de leur nom de famille… Pour se justifier, l'argument des citoyens souverains est qu'un secret serait gardé dans les hautes sphères du pouvoir : l'État serait en réalité une société privée, à laquelle ils ne veulent pas contribuer. \"L'argument généralement utilisé par les citoyens souverains, c'est que la République française a un numéro de SIRET, explique Rudy Reichstadt…" },
  { title: "Attentats, accidents, disparitions… Les catastrophes aériennes au cœur des récits complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/attentats-accidents-disparitions-les-catastrophes-aeriennes-au-coeur-des-recits-complotistes-9080545", img: "assets/episodes/a9d56005-9dbf-4817-a2f3-e93b35153310.webp", youtube: null, description: "Des origines du génocide des Tutsi au Rwanda jusqu", date: "2024-04-02", body: "Complorama Par Rudy Reichstadt Des origines du génocide des Tutsi au Rwanda jusqu'à la disparition inexpliquée du vol MH370 de la Malaysia Airlines, depuis des années, les crashs et les disparitions d'avions fascinent les théoriciens du complot. Le 6 avril 1994, deux missiles abattent un avion transportant le président rwandais, Juvénal Habyarimana. Provoquant la mort du chef de l'État, cet attentat dont on commémore cette année le 30e anniversaire, ravive les tensions entre les Tutsis et les Hutus. Des théories fusent quant à l'origine des missiles, ravivant les hostilités jusqu'à devenir le point de départ du génocide des Tutsis au Rwanda. Pour les partisans de la théorie du complot, cet attentat a été commandité par les forces Tutsis... Publicité \"C'est la théorie génocidaire, explique Rudy Reichstadt, elle permet aux Hutus de se disculper et de faire porter le chapeau du déclenchement du génocide au Front Patriotique Rwandais (FPR), c'est-à-dire aux rebelles Tutsis. Et donc de suggérer que les Tutsis sont leurs propres bourreaux.\" Une théorie révisionniste, car selon le rapport d'analyse balistique remis en 2012, les tirs venaient d'une zone contrôlée par l'armée fidèle au pouvoir. \"Les rebelles du FPR étaient basés à des dizaines de kilomètres de cette même zone\", note Rudy Reichstadt. La théorie génocidaire n'est pas la seule qui entoure un crash d'avion dû à un attentat. L'attentat du 11 septembre 2001 représente pour Tristan Mendes France \"un véritable épisode sémina…" },
  { title: "PODCAST. Brigitte Macron, Michelle Obama, Kate Middleton... Ces femmes visées par le complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/brigitte-macron-michelle-obama-kate-middleton-ces-femmes-visees-par-le-complotisme-1901249", img: "assets/episodes/f3f5e623-adaf-4279-88ed-4fd1f912f7fb.webp", youtube: null, description: "Une théorie nauséabonde a été déterrée par la complosphère : Brigitte Macron serait une femme transgenre. Cette théorie complotiste pourrait n’avoir aucun écho si l’extrême droite américaine ne s’en était pas emparée à la mi-mars. Mais l", date: "2024-03-18", body: "Complorama Par Rudy Reichstadt Une théorie nauséabonde a été déterrée par la complosphère : Brigitte Macron serait une femme transgenre. Cette théorie complotiste pourrait n’avoir aucun écho si l’extrême droite américaine ne s’en était pas emparée à la mi-mars. Mais l'épouse du chef de l'État n'est pas la première femme célèbre visée par la complosphère. \"Les pires des choses, ce sont les fausses informations et les scénarios montés avec des gens qui finissent par y croire et qui vous bousculent dans votre intimité\" : pour la première fois, le président de la République a répondu face caméra à TF1 Info Ouverture dans un nouvel onglet aux théories du complot visant son épouse, Brigitte Macron. Le chef de l'État fait référence à une fake news qui circule depuis plusieurs années et qui affirme que Brigitte Macron est une femme transgenre née sous le nom de Jean-Michel Trogneux. Le livre L'affaire Madame de la journaliste Emmanuelle Anison (StudioFact éditions) à paraître le 22 mars retrace la genèse de cette fake news Ouverture dans un nouvel onglet . Publicité **>> VRAI OU FAUX. D'où vient la rumeur complotiste qui remet en question l'identité de genre de Brigitte Macron ? Ouverture dans un nouvel onglet **\"Cette théorie est complotiste parce qu'elle suppose un complot, une manipulation à très grande échelle pour pouvoir tenir debout, analyse Rudy Reichstadt. Ce n'est pas une simple rumeur. Une rumeur, c'est un message qui circule hors de tout contrôle, qui n'a pas été vérifié…" },
  { title: "Le fantasme complotiste autour de la dynastie Rothschild", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/podcast-le-fantasme-complotiste-autour-de-la-dynastie-rothschild-3051444", img: "assets/episodes/34e8e3eb-e348-4d32-8b90-a781a9a2b0e6.webp", youtube: null, description: "Mainmise sur les banques centrales, influence sur les présidents… Depuis près de deux siècles, de nombreuses théories du complot fleurissent autour de la famille Rothschild.", date: "2024-03-05", body: "Complorama Par Rudy Reichstadt Mainmise sur les banques centrales, influence sur les présidents… Depuis près de deux siècles, de nombreuses théories du complot fleurissent autour de la famille Rothschild. Jacob Rothschild, membre de l’une des dynasties bancaires les plus connues d’Europe, est décédé fin février à 87 ans. Cet homme d’affaire, homme politique et philanthrope est n’est pas connu du grand public, mais l’annonce de sa mort a suscité de vives réactions au sein de la complosphère. Publicité À peine 24 heures après l’annonce de la mort de Jacob Rothschild \"un demi-million de tweets le mentionnant ont été publié et les dix tweets les plus viraux provenaient tous de comptes complotistes\", observe Tristan Mendès France. Le complotiste américain Dom Lucre a par exemple publié sur X (ex-Twitter) une photo générée par l’intelligence artificielle représentant Jacob Rothschild sur un trône fait d’os et de crânes – image qui a fait plus de 18 millions de vues. Cela fait depuis le 19e siècle que la famille Rothschild cristallise de nombreuses théories conspirationnistes. \"C’est là qu’apparaît le mythe Rothschild\" et une \"abondante littérature complotiste\" autour de cette famille, souligne Rudy Reichstadt. Le nom \"Rothschild\" devient alors synonyme d’opulence, de fortune et de succès, mais très vite apparaît aussi la thèse d’une influence démesurée. Les Rothschild sont ainsi tour à tour accusés d’avoir financé les guerres mondiales, d’avoir participé à l’assassinat de John Fit…" },
  { title: "Mort d'Alexeï Navalny : l'opposant russe dans le collimateur des complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/mort-d-alexei-navalny-l-opposant-russe-dans-le-collimateur-des-complotistes-3038205", img: "assets/episodes/9502098e-02a4-4ef2-86bd-0ee6f0f9eda7.webp", youtube: null, description: "Agent de la CIA, complot de l", date: "2024-02-20", body: "Complorama Par Rudy Reichstadt Agent de la CIA, complot de l'Occident, victime du vaccin contre le Covid-19... de nombreuses théories du complot sont apparues à l'annonce de la mort de l'opposant russe en prison, certaines relayées par la propagande du Kremlin. Il était l'opposant et adversaire numéro 1 du Kremlin. Alexeï Navalny Ouverture dans un nouvel onglet est mort vendredi 16 février en prison, selon le service pénitentiaire fédéral de Russie. Un coup de tonnerre en Russie et dans le monde entier, et la complosphère n’a pas tardé à se réveiller. Dès l’annonce de sa mort, les premières théories du complot ont commencé à circuler. Publicité >> DIRECT. Mort d'Alexeï Navalny : la France demande une \"enquête indépendante\" sur le décès de l'opposant russe Ouverture dans un nouvel onglet \"Ça a véritablement électrisé la complosphère internationale, note Tristan Mendès France, et on a eu de nombreux récits complotistes qui ont commencé à faire surface, que ce soit d'ailleurs poussé par le Kremlin lui-même ou les idiots utiles du régime un peu partout autour du monde.\" Parmi les thèses complotistes les plus diffusées : l'opposant à Vladimir Poutine a été tué par la CIA; l'Occident a éliminé Alexeï Navalny; il est mort d'une thrombose liée à l'injection du vaccin contre le Covid-19. \"C’est la stratégie de la réponse du berger à la bergère, estime Rudy Reichstadt. Les complotistes retournent contre leurs détracteurs l’accusation de “complotisme”. Comme si c’était un jeu, comme si…" },
  { title: "Colère des agriculteurs : quand la sphère complotiste tente de récupérer les mouvements sociaux", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/colere-des-agriculteurs-quand-la-sphere-complotiste-tente-de-recuperer-les-mouvements-sociaux-1013817", img: "assets/episodes/25ae6829-7aec-4715-94ac-c1107797c49e.webp", youtube: null, description: "La mobilisation des agriculteurs a été vue et entendue en France comme ailleurs. Sur les réseaux sociaux, le hashtag #AgriculteursEnColère a rapidement été propulsé par des adeptes de théories complotistes. Avec un seul but : profiter de cette colère pour faire passer leur message.", date: "2024-02-06", body: "Complorama Par Rudy Reichstadt La mobilisation des agriculteurs a été vue et entendue en France comme ailleurs. Sur les réseaux sociaux, le hashtag #AgriculteursEnColère a rapidement été propulsé par des adeptes de théories complotistes. Avec un seul but : profiter de cette colère pour faire passer leur message. \"Après les Hollandais, les Roumains, les Polonais, les Allemands, les Français prennent le relais\" : sur les réseaux sociaux, à la mi-janvier, la sphère complotiste s'enthousiasme des actions menées par les agriculteurs français Ouverture dans un nouvel onglet . \"Ils sont aucunement défendus, même totalement délaissés par les syndicats, notamment la FNSEA, syndicat rongé par la franc-maçonnerie\", affirme une figure complotiste. Publicité À lire aussi Colère des agriculteurs : la faute à l'UE ? Les informés de l'Europe du 28 janvier Les informés de l'Europe 15 min Il n'a pas fallu attendre bien longtemps avant d'assister à une tentative de récupération du mouvement par la complosphère. Sur les réseaux sociaux, l'apparition en tendance du hashtag \\#AgriculteursEnColere n'a pas été si spontané que ça. \"Les organisations syndicales poussaient d'autres hashtags, note Tristan Mendès France. Et là, on a vu que, quelques jours après le lancement de ce premier hashtag, qu'il a été poussé par d'anciennes pages Facebook de 'gilets jaunes', des profils de la complosphère, des figures du climatoscepticisme s'emparer de ce hashtag pour essayer de pousser leur propre agenda. Les co…" },
  { title: "Covid-19 : Didier Raoult, figure adulée par la complosphère", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/covid-19-didier-raoult-figure-adulee-par-la-complosphere-2330100", img: "assets/episodes/91474af4-17b3-47d8-b676-a6445425aa78.webp", youtube: null, description: "En quelques années, le microbiologiste, à la personnalité et aux pratiques controversées, est devenu une personnalité phare pour les complotistes.", date: "2024-01-23", body: "Complorama Par Rudy Reichstadt En quelques années, le microbiologiste, à la personnalité et aux pratiques controversées, est devenu une personnalité phare pour les complotistes. \"C'est probablement l'infection respiratoire la plus facile à traiter\" : au début de la pandémie de Covid-19, en février 2020, Didier Raoult se fait connaître par une vidéo où il parle d'un médicament miracle pour soigner les malades du coronavirus : l'hydroxychloroquine Ouverture dans un nouvel onglet . Avec une telle assurance, l'ex-directeur de l'IHU à Marseille Ouverture dans un nouvel onglet suscite immédiatement beaucoup d'espoir chez les Français. Le microbiologist marseillais sort de l'anonymat et devient l'idole de la complosphère, avant d'être décrié et rejeté par la communauté scientifique car le médicament s'avère inefficace Ouverture dans un nouvel onglet selon de nombreuses études. Publicité >> INFOGRAPHIES. De la chloroquine à la politique : on a passé au microscope les groupes Facebook de soutien au professeur Raoult Ouverture dans un nouvel onglet Parmi elles, une étude française, publiée le 2 janvier dernier, affirme qu'au printemps 2020, l’hydroxychloroquine a causé la mort de 16 990 personnes en Belgique, en Espagne, en France, en Italie, en Turquie et aux États-Unis. En France uniquement, cette molécule est à mettre en lien avec 199 décès lors de la première vague du Covid-19. Ce médicament, utilisé contre le paludisme au départ, avait été présenté par le professeur Didier Raoult…" },
  { title: "Jeffrey Epstein, l’affaire de tous les fantasmes pour la complosphère", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/jeffrey-epstein-l-affaire-de-tous-les-fantasmes-pour-la-complosphere-1267530", img: "assets/episodes/f18c7914-6767-48fe-afb9-35b77954c7e4.webp", youtube: null, description: "Depuis des années, l", date: "2024-01-09", body: "Complorama Par Rudy Reichstadt Depuis des années, l'affaire Epstein suscite l'intérêt de la sphère conspirationniste. Début janvier, la publication de documents judiciaires liés au milliardaire américain relance les théories les plus folles. Voilà une affaire qui régale la complosphère : l'affaire Epstein Ouverture dans un nouvel onglet , du nom de ce financier de Wall Street accusé de crimes sexuels et mort à 66 ans. Depuis le 3 janvier, des centaines de documents judiciaires relatifs à l'affaire ont été rendus publics, contenant les noms de personnes liées à Jeffrey Epstein. Selon la complosphère, il s'agirait d'une \"liste\" de clients de Jeffrey Epstein, qui dévoilerait l'identité secrètement gardée de tous les pédophiles qui ont profité du réseau de trafic d'être humain organisé par le milliardaire américain. Publicité Mais que contiennent ces documents ? \"Le terme 'liste' me pose un peu problème parce que d'abord, ce sont des documents qui ont été publiés, et non des 'listes', explique Tristan Mendès France. Cette formule de 'liste', c'est quelque chose qui est très prégnant dans l'imaginaire complotiste, une sorte de millefeuille accusatoire qui donne l'impression d'une collusion généralisée de noms qui sont mentionnés dedans alors qu'ils ne sont accusés pour certains de rien\". Aucun acte répréhensible n'est attribué aux personnes citées dans ces documents. \"On n'a aucune révélation d'importance, les noms pour l'essentiel avaient déjà été mentionnés auparavant dans la p…" },
  { title: "Les dérives sectaires et complotistes du mouvement raëlien", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/les-derives-sectaires-et-complotistes-du-mouvement-raelien-5096118", img: "assets/episodes/694e025e-154c-4f60-a719-df6442180728.webp", youtube: null, description: "La secte Raël, fondée par Claude Vorilhon et qui a fêté mercredi 13 décembre ses 50 ans d", date: "2023-12-12", body: "Complorama Par Rudy Reichstadt La secte Raël, fondée par Claude Vorilhon et qui a fêté mercredi 13 décembre ses 50 ans d'existence, est à l'affiche d'une mini-série documentaire sur Netflix. L’occasion pour Complorama de retracer sa genèse, sa trajectoire conspirationniste et les relents complotistes de son gourou. C'est l'histoire d'un chanteur que l'on dit en quête de notoriété devenu prophète autoproclamé. Claude Vorilhon, surnommé le \"petit Jacques Brel\", passionné de voitures de courses, prétend avoir fait une rencontre du troisième type. Le 13 décembre 1973, les \"Elohim\", ces extraterrestres venus à lui, lui confient un message : ils sont à l'origine de la vie sur Terre. Netflix consacre une mini-série documentaire, Raël, le prophète des extraterrestres, à paraître mercredi 7 février. Publicité Claude, devenu le messager Raël Ouverture dans un nouvel onglet , lance son mouvement. Objectif : répandre la bonne parole et construire des ambassades en vue de célébrer le retour des Elohim sur Terre. \"Ils m'ont dit : 'Arrête ton travail, et va de part le monde, porte ce message. Les gens riront au début mais au fur et à mesure les gens comprendront et prépareront cette ambassade où ils vont venir officiellement, et là je ne serai pas tout seul, tout le monde pourra les voir\", assure-t-il sur le plateau de l’émission de télévision \"Autant en emporte le temps\" sur Antenne 2, le 18 juin 1994. \"C'est un mouvement qui se caractérise vraiment par sa capacité à faire parler de lui,…" },
  { title: "De Vinted au Pizzagate, la théorie du complot du trafic d’enfants sur Internet", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-vinted-au-pizzagate-la-theorie-du-complot-du-trafic-d-enfants-sur-internet-7864273", img: "assets/episodes/07eb23b2-ad8b-4f8b-a642-f2df32e74fd5.webp", youtube: null, description: "Des objets vendus à des prix exorbitants ont attiré l", date: "2023-11-28", body: "Complorama Par Rudy Reichstadt Des objets vendus à des prix exorbitants ont attiré l'œil des complotistes sur le site Vinted. Des pédocriminels se cachent-ils derrière ces annonces ? Si on parle bien ici d’arnaques, de mauvaises blagues ou de vrais malentendus, cette théorie du complot ne date pas d’hier. \"Des réseaux pédo utilisent Vinted pour mettre à disposition des enfants, ils font passer des annonces avec des objets qui n'ont aucune valeur, toujours des objets pour enfant, type petite trottinette, peluche etc\", explique un homme dans une vidéo publiée sur le réseau social TikTok. Depuis le 11 novembre, une rumeur selon laquelle la plate-forme de revente de vêtements et d'objets Ouverture dans un nouvel onglet hébergerait des petites annonces à caractère pédophile circule sur les réseaux sociaux. \"On avait suivi l’affaire de Wayfair. Je me dis : je vais vendre mes fringues, mais je vais d’abord regarder comment ça se passe (...) J’ai commencé à fouiller avec l’esprit d’investigation que l’on a maintenant\", explique celle qui se cache derrière le compte Quantum Leap Traduction sur X dans un live audio en ligne captée par Tristan Mendès France. \"On a des tweets qui ont été vus plus de 5 millions de fois, note-t-il, ce qui semblait être un épiphénomène en ligne était en train de devenir un véritable objet assez inquiétant.\" Publicité \"Ce qui est assez notable ici, remarque Rudy Reichstadt, c'est l'émergence de la figure du citoyen-enquêteur qui est née avec l'affaire Kenne…" },
  { title: "L'assassinat de John Fitzgerald Kennedy, 60 ans de théories du complot", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/l-assassinat-de-john-fitzgerald-kennedy-60-ans-de-theories-du-complot-1119657", img: "assets/episodes/c26155a8-deaf-4142-9009-e0be98fd9684.webp", youtube: null, description: "Le 22 novembre 1963, le président des États-Unis est assassiné lors d’une visite officielle à Dallas (Texas). Le principal suspect, Lee Harvey Oswald, est arrêté puis tué deux jours plus tard. Le pays reste marqué par cet événement qui a nourri de nombreuses thèses conspirationnistes.", date: "2023-11-14", body: "Complorama Par Rudy Reichstadt Le 22 novembre 1963, le président des États-Unis est assassiné lors d’une visite officielle à Dallas (Texas). Le principal suspect, Lee Harvey Oswald, est arrêté puis tué deux jours plus tard. Le pays reste marqué par cet événement qui a nourri de nombreuses thèses conspirationnistes. \"De Dallas au Texas, la nouvelle apparemment officielle : le président Kennedy est mort à 13 heures\". Le présentateur américain de CBS News Walter Cronkite annonce, le 22 novembre 1963, la nouvelle de la mort de John Fitzgerald Kennedy Ouverture dans un nouvel onglet dans un bulletin d’information devenu mythique. \"Le vice-président Lyndon Johnson a quitté l’hôpital de Dallas, mais nous ne savons pas pour quelle destination. Il prêtera probablement serment sous peu et deviendra le 36e président des Etats-Unis.\" Publicité Ce jour-là, le président américain est accompagné de sa femme Jackie, du gouverneur du Texas John Connaly et de son épouse lors d’une visite présidentielle à Dallas, au Texas (États-Unis). John Fitzgerald Kennedy (JFK) est alors à bord d’une voiture décapotable lorsque trois coups de feu retentissent, le blessant mortellement. Le président s’écroule, et est déclaré mort quelques dizaines de minutes plus tard. >> CIA, mafia, extraterrestres... Neuf théories (plus ou moins farfelues) sur l’assassinat de JFK Ouverture dans un nouvel onglet Depuis 60 ans, cet événement n’a jamais cessé d’être le terreau de théories du complot Ouverture dans un nouvel…" },
  { title: "Hongrie : le complotisme à l’ère de Viktor Orban", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/hongrie-le-complotisme-a-l-ere-de-viktor-orban-8783160", img: "assets/episodes/d71f17ba-7f64-4233-bd7d-cd48fe0f8109.webp", youtube: null, description: "La rencontre entre le Premier ministre hongrois Viktor Orban et le président russe Vladimir Poutine, le 17 octobre en Chine, met dans l’embarras l’Europe. Pour légitimer sa politique radicale qui lui vaut d", date: "2023-10-31", body: "Complorama Par Rudy Reichstadt La rencontre entre le Premier ministre hongrois Viktor Orban et le président russe Vladimir Poutine, le 17 octobre en Chine, met dans l’embarras l’Europe. Pour légitimer sa politique radicale qui lui vaut d'être mis au ban de l'UE, Viktor Orban brandit de nombreuses théories du complot. La poignée de main entre Viktor Orban et Vladimir Poutine le 17 octobre en marge du forum des Nouvelles routes de la soie à Pékin a du mal à passer du côté de l'Europe, en pleine guerre en Ukraine. Si le Premier ministre hongrois assure vouloir maintenir le contact avec le Kremlin pour favoriser un accord de paix, cette proximité inquiète. Publicité Viktor Orban est de plus en plus isolé en Europe Ouverture dans un nouvel onglet , mis au ban notamment pour sa politique radicale. Pour tenter de légitimer cette politique ultra conservatrice, il n'hésite pas à brandir des théories complotistes Ouverture dans un nouvel onglet , comme le \"grand remplacement\", le lobby LGBT+ ou encore l'antisémitisme. Arrivé une première fois au pouvoir en 1998, avant d'y revenir en 2010, Viktor Orban est aujourd'hui une figure du populisme Ouverture dans un nouvel onglet . \"Le complotisme fournit une sorte de stock argumentatif dans lequel le discours populiste peut aller puiser selon ses besoins\", explique Rudy Reichstadt. Complotisme et populisme présentent des points communs : \"une diabolisation des élites\", l'idée d'avoir \"deux camps qui s'affrontent\" et le fait de capitaliser su…" },
  { title: "Guerre entre Israël et le Hamas, un nouveau moment complotiste", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/guerre-entre-israel-et-le-hamas-un-nouveau-moment-complotiste-6118752", img: "assets/episodes/e66fa36f-3338-4010-b3ad-ef23a8168b47.webp", youtube: null, description: "Depuis le 7 octobre, les hostilités entre le Hamas et Israël font l’objet d’une déferlante de théories du complot et de désinformation sur les réseaux sociaux. Cette vague inédite de contenus conspirationnistes met à l’épreuve les politiques de modérations des plateformes, déjà pointées du doigt.", date: "2023-10-17", body: "Complorama Par Rudy Reichstadt Depuis le 7 octobre, les hostilités entre le Hamas et Israël font l’objet d’une déferlante de théories du complot et de désinformation sur les réseaux sociaux. Cette vague inédite de contenus conspirationnistes met à l’épreuve les politiques de modérations des plateformes, déjà pointées du doigt. Depuis l’attaque du Hamas dans le sud d’Israël le 7 octobre, les réseaux sociaux sont inondés de désinformation. En quelques heures seulement, les plateformes comme Twitter et Tiktok sont devenues le terrain d’une véritable guerre de la communication. Et parmi ces fausses informations, on retrouve de nombreuses théories du complot : la thèse du terrorisme fabriqué, des images empruntées à d’autres conflits, de la propagande ou encore de la désinformation teintée d’antisémitisme. Publicité Rudy Reichstadt explique que l’attaque du 7 octobre, et ses suites en Israël et dans la bande de Gaza, réunissent \"tous les ingrédients propices à l’apparition d’une version complotiste\". Il cite ainsi \"la surprise, l’ampleur de l’attaque qui nous met dans un état de sidération, or la sidération est propre à paralyser la réflexion\". Dans ce contexte, les conspirationnistes apportent donc tour à tour leur propre analyse à ce conflit qui dure depuis plus de soixante-dix ans. L’influenceur conspirationniste Valerian Ronzeau publie notamment une vidéo sur Twitter le 9 octobre dans laquelle il met en doute l’attaque, expliquant que, selon lui, Israël détient une armée trop…" },
  { title: "De la \"loi Evras\" aux ABCD de l'égalité : quand les complotistes s'attaquent à l'école", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-la-loi-evras-aux-abcd-de-l-egalite-quand-les-complotistes-s-attaquent-a-l-ecole-9403151", img: "assets/episodes/b1d0f390-2503-4089-affc-b0aac4552901.webp", youtube: null, description: "En Belgique, le programme Evras subit une vague de désinformation des milieux conservateurs et religieux radicaux, qu", date: "2023-10-06", body: "Complorama Par Rudy Reichstadt En Belgique, le programme Evras subit une vague de désinformation des milieux conservateurs et religieux radicaux, qu'ils soient musulmans ou catholiques. Des protestations qui rappellent celles vécues il y a dix ans en France contre les ABCD de l'Égalité. \"Ne touchez pas à nos enfants\", \"Nos enfants sont innocents\", \"Pas de sexualité avant la puberté\"... ces slogans écrits sur des pancartes par des manifestants \"anti-Evras\" à Bruxelles lors d’un rassemblement le 30 septembre dernier ont fait la une des médias belges et francophones ces dernières semaines. Le 7 septembre, un décret voté au Parlement de Wallonie Bruxelles pour instituer deux fois deux heures par an aux élèves de collège un cours d’Evras (Éducation à la vie relationnelle, affective et sexuelle) a mis le feu aux poudres. Des écoles ont été incendiées début septembre Ouverture dans un nouvel onglet en région de Charleroi et de Liège. Publicité \"Ce décret est visé par des rumeurs sur fond de théories de complot\", estime Rudy Reichstadt. Que dit la rumeur ? Que l'on va \"enseigner la masturbation à des enfants, leur diffuser des contenues pornogaphiques, les inciter à se toucher mutuellement et même légitimer la pédophilie, poursuit-il. Le fond de théorie du complot à proprement parler, c’est que tout cela serait décidé par les fameuses élites mondialistes qui veulent nous asservir. On a entendu Alain Escada, du parti Civitas - qui vient d’être dissous en conseil des ministres - expli…" },
  { title: "De Thierry Ardisson à Cyril Hanouna, quand le complotisme s’invite à la télévision", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-thierry-ardisson-a-cyril-hanouna-quand-le-complotisme-s-invite-a-la-television-8447818", img: "assets/episodes/40a9317f-3fe8-4648-82c2-0a95136da90b.webp", youtube: null, description: "Il n’est pas rare d’entendre des théories du complot sur les plateaux de télévision. L’infotainment est devenu un business depuis les années 90. La recherche du buzz et des dérapages a ouvert le champ libre aux complotistes sur le petit écran.", date: "2023-09-19", body: "Complorama Par Rudy Reichstadt Il n’est pas rare d’entendre des théories du complot sur les plateaux de télévision. L’infotainment est devenu un business depuis les années 90. La recherche du buzz et des dérapages a ouvert le champ libre aux complotistes sur le petit écran. \"Nous ce qu’on veut, c’est de la confrontation en plateau, c’est ça, la télévision\" : invité de l’émission C Médiatique le 17 septembre, Cyril Hanouna assume, alors que son émission \"Touche pas à mon poste\" multiplie les dérapages depuis la saison dernière. La chaîne C8 a plusieurs fois été sanctionnée par l'Arcom, le régulateur des médias. \"Il y a un acharnement sur 'TPMP'\", dénonçait le producteur et animateur de l'émission phare de C8, le 31 août dernier sur franceinfo Ouverture dans un nouvel onglet . Publicité Pourtant, l'émission donne une visibilité, depuis quelques années, à de nombreuses personnalités connues de la complosphère. \"C'est même un festival conspi, cette émission\", regrette Rudy Reichstadt, rappelant l'interview d'Afida Turner, lors de la pandémie de Covid-19, le 2 avril 2020, qui assurait à l'époque que le coronavirus était un \"coup d'Etat\". \"Ce qui est déconcertant, c'est que Cyril Hanouna qui l'interviewe semble tout à fait conscient de la dangerosité de ces théories du complot, poursuit-t-il, il finira d'ailleurs l'émission en disant 'ces théories du complot sont extrêmement dangereuses, ne rentrez pas là-dedans'. On est face à une émission qui véhicule quand même ce type de théor…" },
  { title: "De Donald Trump au Nuremberg 2.0 : quand les complotistes font le procès de la justice", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/quand-les-complotistes-font-le-proces-de-la-justice-4881168", img: "assets/episodes/d104a2ba-a03b-445f-bf45-456dfc9222b2.webp", youtube: null, description: "Donald Trump est de nouveau inculpé par la justice américaine pour ses pressions électorales lors de l’élection présidentielle de 2020 en Géorgie. L’ex-président des Etats-Unis mais d’autres aussi, en France, se disent parfois victimes d’une instrumentalisation de la justice.", date: "2023-09-05", body: "Complorama Par Rudy Reichstadt Donald Trump est de nouveau inculpé par la justice américaine pour ses pressions électorales lors de l’élection présidentielle de 2020 en Géorgie. L’ex-président des Etats-Unis mais d’autres aussi, en France, se disent parfois victimes d’une instrumentalisation de la justice. \"Ce qui s’est passé ici est une parodie de justice, ce qu’ils font, c’est de l’ingérence électorale\" : Donald Trump Ouverture dans un nouvel onglet s’adresse aux médias à l’aéroport d’Atlanta, dans l’Etat de Géorgie, après s’être rendu à la prison du comté de Fulton, le 24 août 2023. Quelques heures après avoir été placé brièvement en état d’arrestation dans une prison de Géorgie. L’ex-président américain est à ce moment-là inculpé de tentative de manipulation de la présidentielle de 2020 Ouverture dans un nouvel onglet . Face aux journalistes, il dénonce un \"simulacre de justice\". \"C’est une thématique assez classique chez Donald Trump, explique Rudy Rechstadt. Il dénonce un complot politique dont la justice serait le bras armé, crie à la \"chasse aux sorcières\", à la \"persécution\" et retourne l’accusation en faisant le procès public de la procureur Fani Willis, de l’Etat de Géorgie, qui l’a inculpé\". Mais l’ex-président américain a été inculpé par un grand jury qui n’est pas aux ordres de la procureure. Enfin, ce qui lui est reproché à Trump, c’est d’avoir tenté de manipuler le cours de l’élection dans l’Etat de Géorgie. Publicité \"Le discours complotiste autour de la jus…" },
  { title: "Quand la complosphère s'empare des ovnis", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/quand-la-complosphere-s-empare-des-ovnis-8300471", img: "assets/episodes/5eb125e3-e31d-4f05-8598-838242238e49.webp", youtube: null, description: "Les déclarations d", date: "2023-06-20", body: "Complorama Par Rudy Reichstadt Les déclarations d'un ancien membre des services de renseignement américains selon lesquelles \"le gouvernement travaille depuis des décennies sur les objets extraterrestres\" a relancé début juin les théories du complot sur les ovnis. Les extraterrestres sont-ils parmi nous, mais surtout, les gouvernements cherchent-ils à nous cacher leur existence ? Ces thèses restent toujours d'actualité. Aux États-Unis, un entretien télévisé de David Grusch Ouverture dans un nouvel onglet , diffusée le 5 juin, ancien membre des services de renseignement américains, a relancé le débat. L'ex-militaire, qui travaillait à l'Agence nationale de renseignement géospatial, assure que les autorités américaines ont collecté, au cours des dernières décennies, des engins \"intacts et partiellement intacts\". Il s'agit d'éléments \"non humains\", c'est-à-dire d'origine inconnue ou extraterrestre, \"d'après leur forme\" et leurs caractéristiques \"uniques\", comme \"leur signature radiologique\". Publicité Le 31 mai dernier, à Washington, la Nasa a tenu sa première conférence de presse avec 16 scientifiques, pour expliquer comment elle allait s'organiser pour mieux documenter les \"phénomènes anormaux inexpliqués\". Il s'agit de mieux répertorier ces phénomènes de sorte que ceux qui les observent puissent témoigner en toute confiance, sans crainte que cela porte préjudice à leur carrière. Le problème majeur des affirmations de David Grusch, c'est l'absence de preuves. \"Ces révélations…" },
  { title: "De la maladie X au \"nouvel ordre mondial\" : quand les complotistes s'attaquent à l'ONU", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-la-maladie-x-au-nouvel-ordre-mondial-quand-les-complotistes-s-attaquent-a-l-onu-4680509", img: "assets/episodes/99a3c6d1-e39a-4057-a2b6-43b545a08629.webp", youtube: null, description: "La maladie X mentionnée par l", date: "2023-06-05", body: "Complorama Par Rudy Reichstadt La maladie X mentionnée par l'Organisation mondiale de la Santé dans une liste de l'OMS des \"maladies prioritaires\" a alimenté la machine complotiste ces derniers jours, relançant un vieux fantasme : l’ONU n’est qu’un \"gouvernement\" qui travaille à mettre en place un \"nouvel ordre mondial\". \"Mystérieuse Maladie X : que mijote vraiment l’OMS ?\", se demandait Florian Philippot, président du parti Les Patriotes dans une vidéo postée sur YouTube le 27 mai. De quoi relancer les théories du complot sur l'Organisation mondiale de la Santé, et plus largement sur les Nations Unies. Publicité En effet, la maladie X figure sur une liste qui \"vise à identifier quelles maladies représentent un risque pour la santé publique du fait de leur potentiel épidémique et pour lesquelles il n'y a pas, ou pas assez, de traitement existant\". Ainsi, on trouve sur cette liste le Covid-19, la fièvre hémorragique de Crimée-Congo, le virus Ebola ou encore Zika. Et, en dernière position, la maladie X, qui ne désigne rien d'autre qu'une épidémie potentielle qui serait causée par un agent pathogène actuellement inconnu et nuisible pour la santé humaine. Elle a été incluse à la liste pour veiller à ce que la communauté internationale en santé soit prête à s'attaquer à toutes les formes de menaces, y compris les menaces imprévisibles. Donc par souci de prudence plutôt que par volonté de faire peur. L’OMS est régulièrement dans le viseur de la complosphère. Beaucoup d’ailleurs pr…" },
  { title: "La Turquie complotiste à l'heure de l'élection présidentielle", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/la-turquie-complotiste-a-l-heure-de-l-election-presidentielle-6708415", img: "assets/episodes/95e77384-7dc0-4620-a374-6baaade112a5.webp", youtube: null, description: "À quelques jours du second tour en Turquie, Recep Tayyip Erdogan se retrouve en position de force face à son adversaire Kemal Kiliçdaroglu. Le président sortant s’est installé au fil des années en maître dans l’art de fabriquer des théories du complot pour se maintenir au pouvoir.", date: "2023-05-22", body: "Complorama Par Rudy Reichstadt À quelques jours du second tour en Turquie, Recep Tayyip Erdogan se retrouve en position de force face à son adversaire Kemal Kiliçdaroglu. Le président sortant s’est installé au fil des années en maître dans l’art de fabriquer des théories du complot pour se maintenir au pouvoir. \"C'est clair, l'élection du 14 mai est une tentative de coup d'Etat politique de l'occident, une tentative de coup d'Etat où tous les préparatifs sont en place pour éliminer la Turquie Ouverture dans un nouvel onglet \". Le ministre de l'intérieur turc Suleyman Soylu prononçait ces quelques phrases, deux jours avant le premier tour de l'élection présidentielle, devant une foule acquise au chef de l'Etat Recep Tayyip Erdogan, candidat à sa réelection. Face à lui, le candidat de l'opposition Kemal Kiliçdaroglu Ouverture dans un nouvel onglet . Cette théorie d'un coup d'Etat de l'occident, colportée par le camp présidentiel, n'est pas nouvelle. \"On mesure combien populisme et moment électoraux sont propice au complotisme\", note Tristan Mendès France. Publicité >> \"Personne n’a encore gagné, ni perdu l’élection\" : en Turquie, l'opposition se mobilise à quelques jours du second tour de la présidentielle Ouverture dans un nouvel onglet Durant cette campagne, la figure de Georges Soros semble être centrale dans l’imaginaire complotiste turc. Un compte AKP, pro Erdogan, tweetait, avant le premier tour : \"Soit Soros, soit Erdogan\". \"C'est un exemple typique de faux dilemne, de…" },
  { title: "Assassinat de Shinzo Abe, Covid-19, Fukushima : le complotisme au Japon", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/japon-le-complotisme-au-pays-du-soleil-levant-8383232", img: "assets/episodes/43260c88-8c3d-42e0-a80d-c66b6879d6a0.webp", youtube: null, description: "Les manifestations dénonçant la gestion de la crise du Covid-19 par les autorités japonaises se poursuivent, distillant l", date: "2023-05-08", body: "Complorama Par Rudy Reichstadt Les manifestations dénonçant la gestion de la crise du Covid-19 par les autorités japonaises se poursuivent, distillant l'idée que la pandémie est un vaste mensonge. Au-delà de la pandémie, d'autres événements de l'Histoire japonaise ont été la cible des théories du complot. \"Le virus du Covid n’existe pas, il n’y a pas de preuve de son existence, donc il n’y a pas besoin de vaccin, nous avons été trompés par le gouvernement japonais.\" Ce slogan a été scandé par des manifestants, le 16 avril dernier à Kyoto, au Japon Ouverture dans un nouvel onglet . Dénonçant la gestion de la crise du Covid-19 par les autorités japonaises, le groupe Yamato Q se présente comme étant la branche japonaise de la mouvance QAnon aux États-Unis. Limité par son nombre de membres, il se fait néanmoins remarquer sur internet, diffusant des contenus complotistes en ligne. Sur YouTube, les lives d'Ichibei Okamoto, l’un des leaders du groupe, cumule plusieurs dizaines de milliers d’abonnés. Publicité La mouvance QAnon, née en 2017 aux États-Unis, a une certaine résonance au Japon, notamment à travers les positions anti-chinois de l'ancien président Donald Trump Ouverture dans un nouvel onglet . Le mouvement \"J-Anon\" s'est ainsi installé dans l'archipel. \"On a les mêmes références, les mêmes motifs, les mêmes arguments qu'on a pu voir se déployer un peu partout autour de la planète, explique Tristan Mendès France, et qu'on voit cette fois-ci contaminer le Japon avec une dif…" },
  { title: "Clinton, Deep State, QAnon... Donald Trump et les théories du complot", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/clinton-deep-state-qanon-donald-trump-et-les-theories-du-complot-2161455", img: "assets/episodes/4112e544-5772-467e-83ed-d9a617ebbd20.webp", youtube: null, description: "Après son inculpation le 4 avril dernier par un tribunal de New York, Donald Trump, se dit victime d", date: "2023-04-10", body: "Complorama Par Rudy Reichstadt Après son inculpation le 4 avril dernier par un tribunal de New York, Donald Trump, se dit victime d'une \"chasse aux sorcières\" orchestrée par les démocrates. Une petite musique conspirationniste à laquelle nous a habitués l’ancien président des Etats-Unis, et depuis très longtemps. C’est une image historique : Donald Trump, entouré de gardes du corps, la mine grave, entre le 4 avril dernier dans une salle d’audience d'un tribunal de New York. L'ex président des Etats-Unis, âgé de 76 ans, est alors accusé de fraudes comptables Ouverture dans un nouvel onglet , soupçonné d'avoir \"orchestré\" une série de paiements pour étouffer trois affaires avant l'élection présidentielle de 2016. Publicité De retour dans sa résidence en Floride Ouverture dans un nouvel onglet , Donald Trump a qualifié d'\"insulte à la nation\" son inculpation officielle, accusant Alvin Bragg, le procureur de Manhattan \"soutenu par Georges Soros\". De quoi alimenter des attaques aux relents complotistes contre le philanthrope américain. \"Quoi de mieux lorsqu’on veut reporter sur d’autres l’origine de ses ennuis que de se choisir un ennemi connu, identifié, un bouc émissaire ? Et de l’accuser d’être derrière tous les problèmes qu’on rencontre, explique Rudy Reichstadt. Donc Donald Trump joue la carte Soros, c’est une valeur sûre. C’est la certitude que ses partisans se presseront à ses côtés pour le défendre et relaieront son discours de victimisation.\" Soros, ce nom en deux syllab…" },
  { title: "Adrénochrome, crimes rituels : le sang au cœur du complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/adrenochrome-crimes-rituels-le-sang-au-coeur-du-complotisme-7805665", img: "assets/episodes/e524f2cf-d446-41ef-9a17-6e8b1ce2c02f.webp", youtube: null, description: "Le mythe de l", date: "2023-03-27", body: "Complorama Par Rudy Reichstadt Le mythe de l'adrénochrome, une drogue issue du sang d'enfants sacrifiés, a été relancé au début du mois de mars à la télévision. Et si cette théorie ne date pas d’hier, derrière elle se cache l’expression de croyances conspirationnistes beaucoup plus vastes. \"L'adrénochrome, c'est du sang d'enfant, qu'on prend sur des enfants de 3 ans, pour commencer.\" Jeudi 9 mars, Gérard Fauré, ancien dealer de cocaïne, est invité sur le plateau de l'émission \"Touche pas à mon poste\" Ouverture dans un nouvel onglet sur la chaîne C8 pour réagir à l'affaire Pierre Palmade. Devant plus de 2 millions de téléspectateurs, l'auteur complotiste affirme qu'il existe \"peut-être\" une \"histoire d'adrénochrome\" dans l'affaire. Publicité À réécouter Affaire Mia : un enlèvement d’enfant sur fond de complotisme Complorama 27 min \"L'adrénochrome, c'est une substance naturelle qui est produite par oxydation de l'adrénaline et qui, dans la culture complotiste contemporaine, est réputée pour avoir des vertus psychotropes ou alors régénérescence\", explique Rudy Reichstadt. Cette théorie du complot autour de l'adrénochrome, poussée par l'imaginaire QAnon, \"explose littéralement avec le Covid\" selon Tristan Mendès France. \"Dès mars 2020, on avait un pic spectaculaire d'intérêt autour de l'adrénochrome\" concernant les taux d'engagements sur le Google. Les premières occurrences datent de 2014, sur le forum 4Chan. \"Une première vidéo avait été publiée à l'époque qui associait les cri…" },
  { title: "Des réseaux sociaux à la politique, les stratégies du complotisme climatique", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/des-reseaux-sociaux-a-la-politique-les-strategies-du-complotisme-climatique-4808224", img: "assets/episodes/7127bbd3-3799-46e8-a90c-64f7ede73a97.webp", youtube: null, description: "C’est devenu l’activité principale des climatosceptiques sur internet : délégitimer le travail des experts du Giec, dont la synthèse du sixième rapport d", date: "2023-03-14", body: "Complorama Par Rudy Reichstadt C’est devenu l’activité principale des climatosceptiques sur internet : délégitimer le travail des experts du Giec, dont la synthèse du sixième rapport d'évaluation sera publiée le 20 mars. L'occasion d'analyser les méthodes des dénialistes qui visent à minimiser, voire nier l’urgence climatique. Le Giec est \"une machine de propagande politique\", ses scientifiques sont des \"escrolos\". Sur Internet, les climatosceptiques Ouverture dans un nouvel onglet cherchent à démontrer que ce Groupe d'experts intergouvernemental sur l'évolution du climat est corrompu. Mais pas seulement. C'est ce que démontre le projet Climatoscope, lancé en 2015 par le mathématicien David Chavalarias, directeur de l’Institut des systèmes de complexes de Paris, et Maziyar Panahi, ingénieur au CNRS spécialisé en intelligence artificielle. Cet outil analyse les tweets des comptes climatosceptiques Ouverture dans un nouvel onglet sur Twitter. Publicité Selon leur dernière étude Ouverture dans un nouvel onglet publiée à la mi-février, le nombre de comptes climatosceptiques a bondi sur Twitter en France à l'été 2022. a France fait face à un fort regain de climatoscepticisme sur Twitter depuis juillet 2022. \"Si on regarde l'activité climato-sceptique ou climato-dénialiste au niveau de la France sur les cinq ans d'observation, ce qu'on s'aperçoit, c'est que depuis cet été, il y a la formation d'une communauté beaucoup plus structurée, qui reste relativement petite, mais bon qui cr…" },
  { title: "Guerre en Ukraine : un an de théories du complot au service de la propagande", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/guerre-en-ukraine-un-an-de-theories-du-complot-au-service-de-la-propagande-7008439", img: "assets/episodes/9eb7564f-da7a-4fdf-8da3-1765e775d8e0.webp", youtube: null, description: "Le 24 février 2022, Vladimir Poutine annonçait sa décision d’envahir l’Ukraine pour \"dénazifier\" le pays. Un an plus tard, la complosphère a toujours les yeux rivés sur l’Ukraine, chaque événement n’est selon elle qu’un fake orchestré par l’Occident et la \"junte nazie\" au pouvoir à Kiev.", date: "2023-02-21", body: "Complorama Par Rudy Reichstadt Le 24 février 2022, Vladimir Poutine annonçait sa décision d’envahir l’Ukraine pour \"dénazifier\" le pays. Un an plus tard, la complosphère a toujours les yeux rivés sur l’Ukraine, chaque événement n’est selon elle qu’un fake orchestré par l’Occident et la \"junte nazie\" au pouvoir à Kiev. Sourcils froncés, installé derrière son bureau austère du Kremlin, Vladimir Poutine Ouverture dans un nouvel onglet annonce en direct à la télévision russe sa décision d'envahir l'Ukraine. \"J'ai décidé de mener une opération militaire spéciale dont le but est la protection des personnes qui, pendant huit ans, ont subi les abus et le génocide du régime de Kiev\", a déclaré le chef du Kremlin. La dimension obsidionale, paranoïaque et menaçante du discours annonce très clairement l'offensive : Vladimir Poutine parle de la \"folie\" de la \"création\" de l'Ukraine, de \"l'injustice\" que constitue son départ de l'Union soviétique, parle de \"trahison de nos valeurs communes\", évoque l'Ukraine comme une menace pour la sécurité de la Russie. Publicité >> De Boutcha en Ukraine à la Seconde Guerre mondiale : le complotisme en temps de guerre Ouverture dans un nouvel onglet S’en est suivi de nombreux faits pour lesquels la machine complotiste a tourné à plein régime, comme le bombardement de Marioupol Ouverture dans un nouvel onglet et ses femmes enceintes, vue comme une manipulation pour Sergueï Lavrov, ministre des Affaires étrangères, et Alexeï Mechkov, ambassadeur de Russie…" },
  { title: "TikTok, Roblox, Fortnite : la jeunesse dans le viseur des complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/tiktok-roblox-fortnite-la-jeunesse-dans-le-viseur-des-complotistes-4351044", img: "assets/episodes/1073fc96-1607-4182-9026-10b1fd6993d2.webp", youtube: null, description: "S’ils sont encore minoritaires, certains jeunes Français semblent clairement être plus méfiants et sensibles à la désinformation que leurs aînés. Sont-ils aujourd’hui devenus une cible privilégiée de la complosphère ?", date: "2023-02-10", body: "Complorama Par Rudy Reichstadt S’ils sont encore minoritaires, certains jeunes Français semblent clairement être plus méfiants et sensibles à la désinformation que leurs aînés. Sont-ils aujourd’hui devenus une cible privilégiée de la complosphère ? Les jeunes sont-ils plus perméables aux théories du complot ? De nombreuses études, dont une récente de l'Ifop Ouverture dans un nouvel onglet , s'intéressent aux 11-24 ans et à leur porosité au complotisme Ouverture dans un nouvel onglet . Et s'ils sont encore très minoritaires, certains jeunes semblent être plus sensibles aux fake news qui peuvent circuler sur les réseaux sociaux. Publicité \"Ce qu'on voit sur les théories du complot, c'est qu'effectivement, il y a une capacité immédiate à croire à ces choses-là deux à trois fois plus grande chez les moins de 25 ans que chez les plus de 65 ans, explique Rudy Reichstadt. Ce qui est intéressant, ce n'est pas tant les chiffres en soi, c'est-à-dire combien de jeunes croient à ces choses-là, ce sont plutôt les écarts. Je trouve que les écarts nous disent quelque chose d'une imprégnation de la jeunesse par l'imaginaire complotiste.\" Le réseau social TikTok, utilisée par 52% des 16-25 ans en 2022, selon Diplomeo, regorge de vidéos complotistes. Et c’est un réseau social utilisé en majorité par les jeunes. Dans son rapport sur la lutte contre la désinformation, réclamé par la Commission Européenne Ouverture dans un nouvel onglet et publié le 9 février, le réseau social chinois révèle avo…" },
  { title: "ChatGPT : l'intelligence artificielle au service du complotisme ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/chatgpt-l-intelligence-artificielle-au-service-du-complotisme-1527533", img: "assets/episodes/fa025aad-6e5f-4e20-b569-c6c0c51bf1da.webp", youtube: null, description: "Ce robot conversationnel est capable d", date: "2023-01-24", body: "Complorama Par Rudy Reichstadt Ce robot conversationnel est capable d'écrire des textes et de dialoguer avec un langage humain presque troublant. Cinq jours après son lancement, l’intelligence artificielle franchit le million d’utilisateurs gratuits dans le monde. Mais que se passe-t-il quand elle tombe entre de mauvaises mains ? ChatGPT peut-il devenir un propagateur de théories du complot ? ChatGPT Ouverture dans un nouvel onglet , pour \"generative pre-trained transformer\", connait un vif engouement depuis la fin novembre 2022. Ce robot conversationnel est un outil qui va prédire et générer du contenu Ouverture dans un nouvel onglet en fonction des consignes que l'internaute lui donne, comme un SMS qui suggère les mots que l'on va taper en fonction de ce qu'on a déjà écrit. Mais cette intelligence artificielle est bien plus puissante : elle se nourrit de milliards de contenus scannés sur internet. Publicité >> TEMOIGNAGES. Intelligence artificielle : \"triche\" pour certains, \"ressource\" pour d'autres, l'utilisation de ChatGPT fait débat entre étudiants et enseignants à l'université Ouverture dans un nouvel onglet Le générateur de texte créé par OpenAI, lancé en 2015 par Sam Altman et le bien connu Elon Musk, s'appuie sur des probabilités. Qui dit prédictif ne dit pas forcément factuel. Et malgré les limites du programme, il peut être contourné. Selon une étude de Newsguard, une start-up spécialisée dans la lutte contre les fake news, ChatGPT relaie dans 80% des cas des info…" },
  { title: "Elon Musk et Twitter : vers plus d’extrémisme et de complotisme sur le réseau social ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/elon-musk-et-twitter-vers-plus-d-extremisme-et-de-complotisme-sur-le-reseau-social-8604807", img: "assets/episodes/3187508f-4b33-495f-afdc-d0466898270d.webp", youtube: null, description: "Depuis sa prise de pouvoir de Twitter, Elon Musk multiplie les clins d", date: "2023-01-11", body: "Complorama Par Rudy Reichstadt Depuis sa prise de pouvoir de Twitter, Elon Musk multiplie les clins d'œil à la culture conspirationniste sur le réseau social, mais pas seulement. Trois mois après son rachat, la plateforme a bien changé, ouvrant le champ des possibles à la complosphère. Trois mois après son rachat de la plateforme Twitter, Elon Musk a changé la culture de l'entreprise à marche forcée. Vague de licenciements, système d'authentification payant Ouverture dans un nouvel onglet , fin de la politique de lutte contre la désinformation sur le Covid-19, révélation des Twitter Files Ouverture dans un nouvel onglet : le milliardaire a ouvert le champ des possibles à la complosphère, jusqu'à assouplir la modération des contenus. Publicité >> Twitter : des licenciements massifs aux suspensions de compte controversées, les deux premiers mois erratiques d'Elon Musk à la tête du réseau social Ouverture dans un nouvel onglet \"Suivez le lapin blanc\", \"prenez la pilule rouge\", \"je n’ai pas subi de lavage de cerveau\" : les exemples de tweets d'Elon Musk faisant référence à la complosphère ne manquent pas. Sauf qu'un utilisateur sur trois est abonné au compte du milliardaire sur Twitter. \"Elon Musk a joué depuis longtemps sur ces codes, mais il a un auditoire particulier et notamment une frange complotiste qui boit ses paroles et qui reconnaît, quand il envoie ces tweets, un signal complotiste, estime Tristan Mendès France. S'il n'avait pas 120 millions d'abonnés, ce serait quelq…" },
  { title: "Iran : le complotisme à l’heure des manifestations", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/iran-le-complotisme-a-l-heure-des-manifestations-6124511", img: "assets/episodes/d525f752-3864-44a2-8f03-0d7a674833cd.webp", youtube: null, description: "Israël et des services de renseignements occidentaux accusés de “planifier” une guerre civile : c’est l’un des narratifs complotistes générés par la révolte en Iran. Des théories qui peuvent venir de l’intérieur même du pays, pour tenter de convaincre l’opinion iranienne, mais pas seulement.", date: "2022-12-16", body: "Complorama Par Rudy Reichstadt Israël et des services de renseignements occidentaux accusés de “planifier” une guerre civile : c’est l’un des narratifs complotistes générés par la révolte en Iran. Des théories qui peuvent venir de l’intérieur même du pays, pour tenter de convaincre l’opinion iranienne, mais pas seulement. La mort de Mahsa Amini Ouverture dans un nouvel onglet , une Kurde iranienne de 22 ans décédée le 16 septembre trois jours après son arrestation par la police des mœurs pour ne pas avoir porté son voile correctement, a déclenché une vague de protestations en Iran. Trois mois plus tard, la colère populaire ne faiblit pas, malgré la répression. Publicité >> Répression en Iran : \"Le juge m’a dit que, si jamais j’étais repris à manifester, il donnerait personnellement l’ordre de mon exécution\", témoigne un réfugié kurde Ouverture dans un nouvel onglet Le 4 octobre dernier, le guide suprême iranien, l'ayatollah Ali Khamenei, accusait les Etats-Unis et Israël, deux ennemis jurés de l'Iran, d'avoir fomenté le mouvement de contestation Ouverture dans un nouvel onglet déclenché par la mort de Mahsa Amini à Téhéran. \"Ces émeutes et l'insécurité sont l'œuvre des Etats-Unis, du régime sioniste usurpateur [Israël], leurs mercenaires et certains Iraniens traîtres qui les ont aidés à l'étranger\", a-t-il déclaré. Des théories du complot distillées à l'intérieur du pays afin de convaincre l'opinion iranienne. \"C'est la vieille ficelle de 'la main de l'étranger' : l'idée que…" },
  { title: "Des cryptomonnaies aux monnaies alternatives : le complotisme monétaire", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/des-cryptomonnaies-aux-monnaies-alternatives-le-complotisme-monetaire-9082278", img: "assets/episodes/f6eec07b-fe07-475b-b9d6-317eea79d739.webp", youtube: null, description: "C’est un crash éclair qui a abasourdi le monde de la cryptomonnaie : la plateforme FTX s’est déclarée en faillite. Et ça n’a pas manqué de générer des interprétations complotistes. Car crypto ou pas, la monnaie suscite depuis longtemps des fantasmes de manipulation par les puissants.", date: "2022-11-30", body: "Complorama Par Rudy Reichstadt C’est un crash éclair qui a abasourdi le monde de la cryptomonnaie : la plateforme FTX s’est déclarée en faillite. Et ça n’a pas manqué de générer des interprétations complotistes. Car crypto ou pas, la monnaie suscite depuis longtemps des fantasmes de manipulation par les puissants. La chute éclair d'un empire. En moins de deux jours, la société FTX, une des plus importantes plateformes d'échange de cryptomonnaies au monde, a annoncé vendredi 11 novembre son dépôt de bilan Ouverture dans un nouvel onglet et la démission de son patron Ouverture dans un nouvel onglet , Sam Bankman-Fried. Dans sa chute, FTX a emporté le spécialiste américain de prêts en cryptomonnaies BlockFi, qui a annoncé, lundi 28 novembre, s'être placé sous la protection de la loi des faillites aux Etats-Unis. Publicité >> Cryptomonnaies : trois questions sur la faillite de la plateforme FTX qui plonge le secteur dans la crise Ouverture dans un nouvel onglet Au-delà du montage frauduleux qui a amené à la chute de la plateforme FTX, sa chute a donné des ailes aux adeptes de théories conspirationnistes : certains y ont vu par exemple un lien avec les fraudes électorales des élections de mi-mandat aux États-Unis, d'autres ont accusé l'Ukraine d'être responsable alors qu'une plateforme de dons en cryptomonnaies avait été mise en place pour les Ukrainiens. Il y a forcément une résonance entre le discours anti-système issu de l'univers de la cryptomonnaie et le discours antisystème…" },
  { title: "Climat : les \"chemtrails\", une théorie du complot venue du ciel", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/climat-les-chemtrails-une-theorie-du-complot-venue-du-ciel-4501530", img: "assets/episodes/32527c3e-278e-418e-91f4-9bac0aa2b9f8.webp", youtube: null, description: "La COP27 donne l’occasion à certains climatosceptiques de recycler une théorie conspirationniste bien connue : les \"chemtrails\", ou quand les traînées blanches laissées derrière le passage des avions seraient manipulées pour nuire à la population.", date: "2022-11-10", body: "Complorama Par Rudy Reichstadt La COP27 donne l’occasion à certains climatosceptiques de recycler une théorie conspirationniste bien connue : les \"chemtrails\", ou quand les traînées blanches laissées derrière le passage des avions seraient manipulées pour nuire à la population. L’urgence climatique, qui pèse de plus en plus lourd sur les citoyens du monde entier Ouverture dans un nouvel onglet , suscite des peurs et parfois aussi, des fantasmes. Ainsi, la théorie complotiste des \"chemtrails\", littéralement en anglais \"traînées chimiques\", a récemment renforcé sa traction sur les réseaux sociaux. Elle évoque ces traînées blanches laissées dans le ciel par le passage des avions, des traces qui sont en fait des \"contrails\", des traînées de condensation. Dans la version conspirationniste, ces lignes blanches ont un but de nuisance sur la population, elles sont utilisées par diverses puissances ou institutions selon les déclinaisons, en secret. Publicité Depuis sa naissance, estimée aux années 60, la théorie des \"chemtrails\" est devenue un classique de la complosphère aux narratifs multiples. A chacun ses \"chemtrails\" : une arme de Big Pharma pour inoculer le cancer aux gens et ainsi vendre des chimiothérapies, des traînées chargées de produits toxiques pour rendre la population stérile ou prendre son contrôle psychique, ou encore un moyen de transmettre le Covid. Ces traces blanches, que tout le monde peut voir simplement en levant les yeux au ciel, peuvent s’adapter à chaque ph…" },
  { title: "D’Elon Musk à Kanye West : contrôler une plateforme favorise-t-il le complotisme ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/d-elon-musk-a-kanye-west-controler-une-plateforme-favorise-t-il-le-complotisme-5666727", img: "assets/episodes/9e639770-1667-467d-b764-3531a69b55a4.webp", youtube: null, description: "Après la polémique autour des propos à caractère antisémite de Kanye West, le rappeur américain est en passe de devenir le futur patron du réseau social Parler. A-t-il été inspiré par le libertarien Elon Musk, nouveau patron de Twitter ?", date: "2022-10-27", body: "Complorama Par Rudy Reichstadt Après la polémique autour des propos à caractère antisémite de Kanye West, le rappeur américain est en passe de devenir le futur patron du réseau social Parler. A-t-il été inspiré par le libertarien Elon Musk, nouveau patron de Twitter ? \"L'oiseau est libéré\" : c'est par ce tweet qu'Elon Musk, patron de Tesla et Space X, et homme le plus riche au monde, confirme avoir pris le contrôle de Twitter Ouverture dans un nouvel onglet après avoir conclu l'acquisition du réseau social pour 44 milliards de dollars (44 milliards d'euros). Plus tôt cette semaine, c'est Kanye West qui s'est lancé dans la course à l'acquisition d'un réseau social, en signant un accord de principe avec la plateforme ultraconservatrice Parler, née en 2018. L'objectif du rappeur : en faire un \"refuge pour les gens harcelés par la police de la pensée\". Elon Musk estime de son côté qu'il est \"important pour l'avenir de la civilisation d'avoir une place publique en ligne où une grande variété d'opinions peuvent débattre de façon saine, sans recourir à la violence.\" Publicité >> Twitter racheté par Elon Musk : ce qui pourrait changer sur le réseau social Ouverture dans un nouvel onglet De son côté, Donald Trump, banni de Meta, Instagram et Twitter Ouverture dans un nouvel onglet , a fait l'acquisition de Truth Social, devenu un repaire pour les complotistes six mois après son lancement. Les plateformes alternatives sont-elles un eldorado pour la complosphère ? Dans ce nouvel épisod…" },
  { title: "Des drapeaux russes au Burkina Faso à Wagner : la propagande complotiste russe sur le continent africain", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/des-drapeaux-russes-au-burkina-faso-a-wagner-la-propagande-complotiste-russe-sur-le-continent-africain-3712775", img: "assets/episodes/b08efca4-8466-4463-ae21-fcade6707813.webp", youtube: null, description: "Suite au putsch au Burkina Faso, de nombreux drapeaux russes ont été vu dans des manifestations anti-France. Ce soutien affiché à la Russie résulte d’une entreprise d’influence puissante, qui n’hésite pas à utiliser des théories du complot.", date: "2022-10-13", body: "Complorama Par Rudy Reichstadt Suite au putsch au Burkina Faso, de nombreux drapeaux russes ont été vu dans des manifestations anti-France. Ce soutien affiché à la Russie résulte d’une entreprise d’influence puissante, qui n’hésite pas à utiliser des théories du complot. A l'étage d'un bâtiment du grand marché de Ouagadougou, au Burkina Faso théâtre d'un putsch Ouverture dans un nouvel onglet , le tailleur Alassane a vécu des jours chargés, durant lesquels il raconte aux journalistes de l’Agence France Presse avoir \"cousu seulement des drapeaux russes\", devenus très prisés. Pourquoi un tel engouement pour les couleurs de Moscou ? Elles témoignent d’une entreprise d’influence puissante, installée en partie via la propagande et parfois, via les théories du complot. Publicité >> A LIRE AUSSI. \"Info ou Intox\" : Burkina Faso et intervention française, des vidéos de parachutistes sèment le doute Ouverture dans un nouvel onglet Dans ce nouvel épisode de \"Complorama\", Rudy Reichstadt et Tristan Mendès France analysent cette emprise informationnelle avec l'aide de Kevin Limonier, maître de conférences en géographie et en études slaves à l’Institut Français de Géopolitique (Université Paris 8). \"La propagande complotiste russe sur le continent africain\", c'est le 35e épisode de Complorama avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques et membre de l'observatoire…" },
  { title: "Présidentielle au Brésil : le complotisme au service de Jair Bolsonaro", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/presidentielle-au-bresil-le-complotisme-au-service-de-jair-bolsonaro-7705410", img: "assets/episodes/451eef32-b852-487e-9ae7-d5a400d0eaed.webp", youtube: null, description: "Le premier tour de l", date: "2022-09-29", body: "Complorama Par Rudy Reichstadt Le premier tour de l'élection présidentielle au Brésil, dimanche 2 octobre, opposera Jair Bolsonaro à l'ex-président Lula. En cas de victoire de son adversaire, le président sortant laisse planer l'éventualité d'un scénario insurrectionnel à la Trump. À quelques jours du premier tour de l'élection présidentielle au Brésil, le président d'extrême-droite Jair Bolsonaro est en difficulté dans les sondages face à l'ancien président de gauche Luiz Inácio Lula da Silva. Lula, 76 ans, est crédité de 45% des intentions de vote Ouverture dans un nouvel onglet et Jair Bolsonaro de 33%. Publicité >> \"Les années Bolsonaro, c'est la violence au pouvoir\" : la productrice d'un documentaire sur le président sortant évoque ses craintes face à l'élection au Brésil Ouverture dans un nouvel onglet Depuis son arrivée au pouvoir en 2019, le président sortant n’a eu de cesse de propager des théories complotistes. Lors de cette campagne, la machine à désinformation est devenue le quotidien des Brésiliens. Le camp du président sortant en a fait sa stratégie de communication, diffusant des fausses informations dans les médias et sur les réseaux sociaux : 79% des Brésiliens s'informent sur WhatsApp. Dans cet épisode de Complorama, Morgann Jezequel, journaliste freelance au Brésil depuis 2013, revient sur les différentes théories conspirationnistes lancées par le camp Bolsonaro depuis son arrivée au pouvoir. Et une inquiétude persiste : le président sortant refuse toujour…" },
  { title: "Mort d’Elizabeth II : de la \"reine reptilienne\" au \"meurtre\" de Lady Di, théories du complot autour de la famille royale", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/mort-d-elizabeth-ii-les-theories-du-complot-autour-de-la-famille-royale-britannique-3549579", img: "assets/episodes/b6817486-83fd-49d8-9a9c-a76b8bc2b2ad.webp", youtube: null, description: "Elizabeth II, Lady Di, mais aussi le reste de la famille royale britannique : les théories du complot qui les visent sont nombreuses, et anciennes, et se voient réactivées à l’occasion de la mort de la reine d’Angleterre.", date: "2022-09-15", body: "Complorama Par Rudy Reichstadt Elizabeth II, Lady Di, mais aussi le reste de la famille royale britannique : les théories du complot qui les visent sont nombreuses, et anciennes, et se voient réactivées à l’occasion de la mort de la reine d’Angleterre. Les théories conspirationnistes autour de la reine Elizabeth II sont à peu près aussi vieilles que le début de son règne. Et elles ont été réactivées par la mort de la monarque. Une reine qui serait en fait morte depuis des mois et remplacée par une actrice ou un hologramme, une mort qui ne serait pas naturelle, et même l'idée que la reine Elizabeth serait à l'origine des attentats du 11-Septembre. Publicité De QAnon à David Icke, figure de la complosphère, en passant par Lyndon Larouche ce politicien américain qui accuse la couronne britannique de tous les maux, cet épisode de Complorama décrypte les méchanismes autour de ces thèses toujours vivaces, qui concernent également la famille royale dans son ensemble, à commencer par Lady Di et sa mort dans le pont de l'Alma il y a 25 ans. Le complotisme autour de la famille royale britannique, c'est le 33e épisode de Complorama avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques et membre de l'observatoire du conspirationnisme. Un podcast à retrouver sur le site de franceinfo, l'application Radio France et plusieurs autres plateformes comme Apple podcasts Ouvertur…" },
  { title: "De Doctolib à Pôle emploi, la naturopathie en question", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-doctolib-a-pole-emploi-la-naturopathie-en-question-2016509", img: "assets/episodes/ba4f91e4-33f3-4e49-b9b5-4ac275a61065.webp", youtube: null, description: "Fin août, la plateforme Doctolib, au cœur d’une polémique, a supprimé 17 profils de praticiens du bien-être. L’alerte, venue des internautes, marque-t-elle une prise de conscience, quant aux dérives de la naturopathie qui s’offre parfois de bien belles vitrines, sans trop de contrôle ?", date: "2022-09-01", body: "Complorama Par Rudy Reichstadt Fin août, la plateforme Doctolib, au cœur d’une polémique, a supprimé 17 profils de praticiens du bien-être. L’alerte, venue des internautes, marque-t-elle une prise de conscience, quant aux dérives de la naturopathie qui s’offre parfois de bien belles vitrines, sans trop de contrôle ? Sous la pression d'internautes, 17 naturopathes, inscrits sur la plateforme de prise de rendez-vous sur Doctolib Ouverture dans un nouvel onglet , qui se vantaient d'avoir été formés par la naturopathe Irène Grosjean, ont vu leurs profils supprimés de la plateforme Ouverture dans un nouvel onglet . Irène Grosjean, accusée d'agression sexuelle sur mineurs, a notamment été mise en cause pour des pratiques douteuses qui vont jusqu'à l'attouchement sexuel de bébés pour leur faire baisser la fièvre. Mais pour certains, Doctolib abrite beaucoup plus de praticiens proches d'Irène Grosjean que ces quelques profils supprimés récemment. Publicité >> Naturopathie : \"Paul était sous son emprise\", dénonce la compagne d'un homme mort d'un cancer Ouverture dans un nouvel onglet De son côté, la plateforme Doctolib se défend Ouverture dans un nouvel onglet , et avance qu'ils ne représentent que 0,3% des prises de rendez-vous. Ces naturopathes, accusés de charlatanisme Ouverture dans un nouvel onglet , de dérive sectaire, sont également accusés de complotisme par les internautes. Donner pignon sur rue à des discours extrémistes et potentiellement dangereux, non par mauvaise intent…" },
  { title: "Projet nazi, CIA, cheval de Troie du \"grand remplacement\" : l’Union européenne vue par les complotistes", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/projet-nazi-cia-cheval-de-troie-du-grand-remplacement-l-union-europeenne-vue-par-les-complotistes-2823705", img: "assets/episodes/ff0fe4e1-379e-446c-a9ac-0126d93d207b.webp", youtube: null, description: "L’Ukraine et la Moldavie sont désormais des pays candidats à l’entrée dans l’Union européenne, une institution qui depuis des décennies suscite différentes théories conspirationnistes, que ce soit sur ses origines ou sur son rôle aujourd’hui.", date: "2022-06-19", body: "Complorama Par Rudy Reichstadt L’Ukraine et la Moldavie sont désormais des pays candidats à l’entrée dans l’Union européenne, une institution qui depuis des décennies suscite différentes théories conspirationnistes, que ce soit sur ses origines ou sur son rôle aujourd’hui. Alors que l'Ukraine et la Moldavie ont acquis le statut de candidats Ouverture dans un nouvel onglet à l'entrée dans l'Union européenne, zoom sur les théories du complot qui visent l'UE. L'Union européenne qui serait à l'origine un projet orchestré par les nazis, ou encore par la CIA : la désinformation autour de cette institution n'est pas nouvelle, elle est régulièrement réactivée comme par exemple au moment du référendum français sur la Constitution de l'Union européenne en 2005, ou encore dans le cadre du Brexit. Publicité Il n'y a pas que la création de l'UE qui génère des thèses conspirationnistes, son rôle et son action aujourd'hui sont aussi ciblées. \"Dictature\" au service des lobbys pharmaceutiques pour les uns, l'Union est même pour d'autres une arme politique dont le but est de mener la civilisation européenne à sa perte, via le \"grand remplacement\", théorie bien connue de la complosphère et répandue plus largement en France cette année par le candidat à la présidentielle Eric Zemmour. Consciente de ces attaques, l'Union européenne a développé plusieurs outils de lutte contre la désinformation dont elle n'est pas seulement une cible, mais surtout un grand terrain de jeu. Le complotisme autour de…" },
  { title: "Avortement : quand les complotistes s’attaquent au droit à l’IVG", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/avortement-quand-les-complotistes-s-attaquent-au-droit-a-l-ivg-7073910", img: "assets/episodes/536c1946-8e02-4110-a170-31f76bcddb27.webp", youtube: null, description: "La remise en cause du droit à l’IVG aux États-Unis a relancé, dans ce pays mais également en France, les théories complotistes autour de l’avortement.", date: "2022-06-09", body: "Complorama Par Rudy Reichstadt La remise en cause du droit à l’IVG aux États-Unis a relancé, dans ce pays mais également en France, les théories complotistes autour de l’avortement. Cinquante ans après sa décision de protéger le droit à l’IVG aux Etats-Unis, la Cour suprême pourrait revenir en arrière. Elle envisage, la décision sera rendue d’ici la fin du mois, de laisser les Etats américains choisir, seuls, d’interdire ou d’autoriser l’avortement sur leur territoire. Cette perspective agite la complosphère, aux Etats-Unis mais aussi ici, en France car l’avortement est l’une des nombreuses marottes des conspirationnistes. Publicité Il y a d'une part des figures de la lutte anti-IVG qui versent dans le complotisme. Kandiss Taylor par exemple, candidate pour devenir gouverneure aux Etats-Unis, qui parle dans son programme de se battre contre le \"Nouvel ordre mondial\", thème cher aux complotistes, vision du monde dans laquelle l’avortement ne serait qu’une forme de sacrifice pour caresser Satan dans le sens du poil. Ou encore, en France, Xavier Dor, aussi connu dans le milieu catholique intégriste que pour le site web qu'il a créé et qui est encore aujourd'hui l'une des plus grosses plateformes conspirationnistes francophones. D'autre part, un nombre croissant de complotistes bien connus en France, pour leurs covidoscepticisme ou autres, affichent leur hostilité à l'avortement sous ce même prisme du complot. Thierry Casasnovas par exemple, naturopathe, influenceur, 570 000 abo…" },
  { title: "Guerre en Ukraine, Covid, Ouïghours : en Chine, un complotisme d’État décomplexé", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/guerre-en-ukraine-covid-ouighours-en-chine-un-complotisme-d-etat-decomplexe-4624397", img: "assets/episodes/a5012149-61df-4077-abb4-86fc13313a3c.webp", youtube: null, description: "La Chine est un émetteur majeur de la propagande complotiste russe sur la guerre en Ukraine. L’occasion d’analyser la politique de Pékin d’utiliser le conspirationnisme comme une véritable arme informationnelle.", date: "2022-05-12", body: "Complorama Par Rudy Reichstadt La Chine est un émetteur majeur de la propagande complotiste russe sur la guerre en Ukraine. L’occasion d’analyser la politique de Pékin d’utiliser le conspirationnisme comme une véritable arme informationnelle. L’immense majorité des contenus de désinformation pro-Russie sur la guerre en Ukraine ne vient pas de Russie… Mais de Chine ! C’est ce qu’affirme une étude publiée le 4 mai dernier par NewsGuard, une organisation de lutte contre la propagande en ligne. Car si Facebook est interdit en Chine, les médias chinois eux ne se privent pas de Facebook : plus d’un demi-milliard d’utilisateurs de ce réseau suivent des médias publics affiliés au Parti communiste chinois. Publicité Par exemple nous dit Newsguard, “la page Facebook francophone de la chaîne de télévision publique chinoise CGTN compte 20 millions de followers”. C’est avec cet énorme levier, sans doute sous-évalué en Occident, que la Chine relaie nombre de théories du complot. Et pour Antoine Bondaz, chercheur à la Fondation pour la recherche stratégique, spécialiste de la Chine et invité de cet épisode, Pékin ne soutient pas les thèses du Kremlin par alignement idéologique sur l'Ukraine, mais pour atteindre au travers de cette propagande un objectif qui lui est propre : nuire aux États-Unis. La stratégie était la même au moment du Covid : user de tous les moyens possibles pour atteindre son ennemi juré, par exemple en poussant fortement l'idée selon laquelle le Covid-19 ne serait pas o…" },
  { title: "WikiLeaks : portrait de Julian Assange, figure controversée au centre de théories du complot", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/wikileaks-portrait-de-julian-assange-figure-controversee-au-centre-de-theories-du-complot-7635818", img: "assets/episodes/9293f272-3b25-4084-b97f-1bc5d8d14946.webp", youtube: null, description: "À travers ses prises de position et ses méthodes parfois critiquées, le fondateur de WikiLeaks a parfois été la cible de théories conspirationnistes... Mais aussi la source.", date: "2022-04-28", body: "Complorama Par Rudy Reichstadt À travers ses prises de position et ses méthodes parfois critiquées, le fondateur de WikiLeaks a parfois été la cible de théories conspirationnistes... Mais aussi la source. C’est une affaire tentaculaire qui n’en finit pas : la justice britannique a formellement autorisé l'extradition Ouverture dans un nouvel onglet de Julian Assange, mercredi 20 avril. Un tribunal londonien a officiellement rendu une ordonnance d'extradition à l'encontre de l'Australien de 50 ans, poursuivi par la justice des Etats-Unis pour la diffusion, à partir de 2010, de plus de 700 000 documents classifiés sur les activités militaires et diplomatiques américaines, notamment en Irak et en Afghanistan. Il risque 175 ans de prison, ce que ses soutiens dénoncent comme une attaque gravissime contre la liberté de la presse. Publicité Génie persécuté pour les uns, manipulateur paranoïaque pour les autres, la figure controversée de Julian Assange est au centre de multiples théories conspirationnistes. Sans remettre en cause le rôle majeur joué par WikiLeaks dans la révélation de crimes de guerre depuis 2006, ce nouvel épisode de \"Complorama\" revient la personnalité complexe du fondateur de WikiLeaks, ses liens avec la complosphère. Mais aussi sur les différentes théories du complot ayant émergé aux Etats-Unis après la fuite de documents, et la relation paradoxale entretenue entre Julian Assange et la Russie. WikiLeaks et complotisme\", c’est le 28e épisode de Complorama, avec Ru…" },
  { title: "De Boutcha en Ukraine à la Seconde Guerre mondiale : le complotisme en temps de guerre", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-boutcha-en-ukraine-a-la-seconde-guerre-mondiale-le-complotisme-en-temps-de-guerre-4157471", img: "assets/episodes/556b68ce-f581-4b0b-bbe3-c497132281a8.webp", youtube: null, description: "Le massacre de Boutcha a déclenché une déferlante dans les milieux complotistes, réveillant des mécanismes qui ne datent pas de la guerre en Ukraine. Zoom sur les mécanismes de propagande conspirationniste en temps de guerre.", date: "2022-04-14", body: "Complorama Par Rudy Reichstadt Le massacre de Boutcha a déclenché une déferlante dans les milieux complotistes, réveillant des mécanismes qui ne datent pas de la guerre en Ukraine. Zoom sur les mécanismes de propagande conspirationniste en temps de guerre. Le procureur de la Cour pénale internationale, le Britannique Karim Khan, a qualifié mercredi l'Ukraine de \"scène de crime\" Ouverture dans un nouvel onglet , lors d'une visite à Boutcha, près de Kiev. \"L'Ukraine est une scène de crime. Nous sommes ici parce que nous avons de bonnes raisons de penser que des crimes relevant de la compétence de la Cour sont commis\", a-t-il déclaré lors d'une visite de cette ville où des centaines de civils, selon les autorités ukrainiennes, ont été retrouvés morts après l'occupation russe Ouverture dans un nouvel onglet . Publicité Mais aux yeux de la complosphère, Boutcha n’est qu’une mise en scène, un \"fake\" orchestré par le pouvoir ukrainien, ou encore les services secrets britanniques. Si la guerre en Ukraine a tout de suite enclenché une phase conspirationniste autour de ce conflit, Boutcha a déclenché la vitesse supérieure, avec des théories souvent relayées en tout premier lieu par le pouvoir russe. Acteurs de crise, révisionnisme en temps réel, cette multiplication des narratifs destinée à créer un écran de fumée autour des faits avérés est la clé de voûte du discours de Moscou, qui ne le destine pas seulement à la communauté internationale, mais avant tout à sa population. Le corres…" },
  { title: "Présidentielle 2022 : l’élection qui serait truquée, cette petite musique du complotisme électoral", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/presidentielle-2022-l-election-qui-serait-truquee-cette-petite-musique-du-complotisme-electoral-6719850", img: "assets/episodes/34363b11-c665-4655-997d-62c677d6e3f8.webp", youtube: null, description: "La théorie selon laquelle l’élection présidentielle ne serait qu’une machination et non un processus démocratique n’est pas nouvelle, elle résonne en France en 2022, y compris à travers les propos de candidats à ce scrutin.", date: "2022-03-31", body: "Complorama Par Rudy Reichstadt La théorie selon laquelle l’élection présidentielle ne serait qu’une machination et non un processus démocratique n’est pas nouvelle, elle résonne en France en 2022, y compris à travers les propos de candidats à ce scrutin. Nous sommes à quelques jours du premier tour, et dans cet épisode \"Complorama\" explore le complotisme électoral, c'est-à-dire la théorie du complot selon laquelle l'élection serait truquée, jouée d'avance, au profit du pouvoir en place, ou encore de puissants agissant en secret et tirant les manettes. Publicité Un argumentaire qui n'est pas relayé que par des habitués de la complosphère, mais aussi par certains candidats à cette présidentielle 2022, comme Nicolas Dupont-Aignan. . @dupontaignan Ouverture dans un nouvel onglet : “L'équité, c'est le mot habile pour l'inégalité. C'est une élection truquée, une élection d'une oligarchie, qui vise à faire taire ceux qui pensent différemment.” \\#QuestionsPol Ouverture dans un nouvel onglet \\#Elysée2022 Ouverture dans un nouvel onglet pic.twitter.com/eY7AC5q0rN Ouverture dans un nouvel onglet — France Inter (@franceinter) March 27, 2022 Ouverture dans un nouvel onglet Nicolas Dupont-Aignan, pour qui \"l'élection est truquée de A à Z\", est appuyé par son soutien Florian Philippot, pour qui \"Nicolas Dupont Aignan a totalement raison ! Macron fait tout pour truquer l’élection depuis des mois ! S’il était réélu, il ne serait pas légitime.\" À ne pas confondre avec l'usage du complotisme d…" },
  { title: "De Booba à Kroc Blanc, du Covid à l’Ukraine : le complotisme dans le rap", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-booba-a-kroc-blanc-du-covid-a-l-ukraine-le-complotisme-dans-le-rap-7695979", img: "assets/episodes/1154f74e-d2f9-4525-b8c0-375889ce9411.webp", youtube: null, description: "Une frange minoritaire du rap tombe parfois dans le complotisme, comme lorsque Booba devient l’un des plus gros vecteurs de propagande russe sur les réseaux sociaux francophones.", date: "2022-03-18", body: "Complorama Par Rudy Reichstadt Une frange minoritaire du rap tombe parfois dans le complotisme, comme lorsque Booba devient l’un des plus gros vecteurs de propagande russe sur les réseaux sociaux francophones. Quel est le rapport entre le rappeur Booba et la guerre en Ukraine ? Le complotisme. Le rappeur français aux 20 ans de carrière, qui compte plus de 5 millions d’abonnés rien que sur Twitter, a embrassé la cause de Vladimir Poutine et est devenu une nouvelle figure de proue du complotisme sur les réseaux sociaux, une dynamique déjà enclenchée avec la crise du Covid. Publicité Il n'est pas le seul dans ce cas, même si cette tendance est marginale au sein du rap : Keny Arkana, Rohff, ils ont aussi montré une adhésion à des théories du complot à travers leur musique, tout comme Freeze Corleone qui a même fait l'objet d'une dénonciation de la Licra et d'une enquête, en 2020, pour des références douteuses dans plusieurs de ces morceaux, ce qui lui avait valu à l'époque dêtre lâché par Universal. Pourquoi les références conspis sont-elles plus présentes dans le rap que dans d’autres genres musicaux ? Est-ce une histoire de codes, de style, ou l’expression d’un vrai courant politique parmi ces musiciens ? Il y a sans doute des deux, de certains artistes qui s'approprient des mythologies complotistes le temps d'un morceau ou d'un clip, à la frange identitaire du rap, avec des rappeurs qui assument leur message d'extrême droite, comme Kroc Blanc. Le complotisme dans le rap, c'es…" },
  { title: "La guerre en Ukraine, entre propagande russe et complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/la-guerre-en-ukraine-entre-propagande-russe-et-complotisme-9355565", img: "assets/episodes/fda5e4ff-d354-43bc-8883-231510e010b8.webp", youtube: null, description: "Depuis le début de l’invasion russe en Ukraine, de nombreuses théories conspirationnistes surgissent sur les réseaux sociaux. À cela s’ajoute la propagande de guerre du Kremlin qui souffle sur les braises de la désinformation.", date: "2022-03-04", body: "Complorama Par Rudy Reichstadt Depuis le début de l’invasion russe en Ukraine, de nombreuses théories conspirationnistes surgissent sur les réseaux sociaux. À cela s’ajoute la propagande de guerre du Kremlin qui souffle sur les braises de la désinformation. Et si la guerre en Ukraine n’était qu’une vaste opération de nos dirigeants destinée à cacher un scandale mondial : celui des vaccins contre le Covid-19 ? C’est l’une des théories qui embrase les milieux complotistes depuis le début de l'invasion russe en Ukraine, le 24 février. Quelques jours plus tôt, le 21 février, dans un discours prononcé aux médias russes, Vladimir Poutine a reconnu l’indépendance des zones séparatistes pro-russes, et a ordonné à son armée d’entrer en Ukraine dans ces territoires. Publicité >> De Staline à Poutine, le complotisme en Russie Ouverture dans un nouvel onglet Le président russe, qualifié de \"dictateur\" par le président américain Joe Biden, se dit prêt à accepter un cessez-le-feu à plusieurs conditions : la reconnaissance de la Crimée en tant que territoire russe, la démilitarisation et \"dénazification\" de l'Ukraine, ainsi qu'un \"statut neutre\" pour le pays, reprenant les éléments de langage de l'époque stalinienne. Cet épisode de Complorama revient sur l'usage du complotisme dans les médias tenus par le Kremlin. Il analyse aussi les diverses théories du complot présentes sur les réseaux sociaux, et les tentatives de l'Union européenne pour endiguer le phénomène. \"La guerre en Ukraine, en…" },
  { title: "\"Grand remplacement\" : de Renaud Camus à Valérie Pécresse et Éric Zemmour, itinéraire d'une théorie complotiste", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-renaud-camus-a-valerie-pecresse-en-passant-par-eric-zemmour-le-parcours-de-la-theorie-du-grand-remplacement-2669634", img: "assets/episodes/8bca056f-476f-4ba6-bf39-4a1c2b7cf862.webp", youtube: null, description: "La théorie du grand remplacement, dont l’usage par Valérie Pécresse lors d’un meeting de la candidate LR à la présidentielle a fait beaucoup de bruit, a une origine et un parcours à forte imprégnation complotiste.", date: "2022-02-18", body: "Complorama Par Rudy Reichstadt La théorie du grand remplacement, dont l’usage par Valérie Pécresse lors d’un meeting de la candidate LR à la présidentielle a fait beaucoup de bruit, a une origine et un parcours à forte imprégnation complotiste. Une notion souvent associée au complotisme fait parler d’elle dans la campagne présidentielle : la théorie du grand remplacement. Valérie Pécresse, la candidate Les Républicains à la présidentielle, l'a utilisée lors de son premier grand meeting de campagne dimanche 13 février au Zénith de Paris. Et elle s'est ainsi attiré une pluie de reproches Ouverture dans un nouvel onglet . Dans son camp, Xavier Bertrand et Jean-François Copé ont appelé la candidate à se repositionner suite à ces propos. Et parmi les nombreuses réactions scandalisées de l’opposition, le patron du Parti socialiste, Olivier Faure, a déclaré sur franceinfo : \"Nous avions déjà deux candidats d'extrême droite, nous n'avions pas besoin d'une troisième.\" Ouverture dans un nouvel onglet Publicité Valérie Pécresse qui parle de “grand remplacement” ➡️ Olivier Faure fait part de sa \"sidération de voir une candidate qui se dit républicaine reprendre les mots et les concepts de l’extrême-droite. Je ne comprends pas cette dérive permanente de la droite.” pic.twitter.com/G7ddVWOFCE Ouverture dans un nouvel onglet — franceinfo (@franceinfo) February 14, 2022 Ouverture dans un nouvel onglet Valérie Pécresse s’est depuis défendue : “Justement, je ne me résigne pas aux théories de…" },
  { title: "Covid : où en est le complotisme antivax, plus d’un an après le début de la campagne de vaccination ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/covid-ou-en-est-le-complotisme-antivax-plus-d-un-an-apres-le-debut-de-la-campagne-de-vaccination-5596302", img: "assets/episodes/0d60e1f1-d540-4d71-b00b-cbfd83dfcd14.webp", youtube: null, description: "Augmentation des cancers, modification de l’ADN ou 5G, disparitions de faux morts du Covid… Les théories du complot autour du vaccin se portent bien, en ce début d’année 2022. Mais le complotisme antivax a évolué, depuis le lancement de la campagne de vaccination il y a un peu plus d’un an.", date: "2022-02-04", body: "Complorama Par Rudy Reichstadt Augmentation des cancers, modification de l’ADN ou 5G, disparitions de faux morts du Covid… Les théories du complot autour du vaccin se portent bien, en ce début d’année 2022. Mais le complotisme antivax a évolué, depuis le lancement de la campagne de vaccination il y a un peu plus d’un an. Si vous avez un ou plusieurs comptes sur les réseaux sociaux, il y a beaucoup de chances que vous ayez vu la vidéo de Karim. Le 14 décembre dernier, les caméras de l’AFP, l’agence France presse, filment dans son lit de réanimation, à Montreuil, Abdelkrim Azzaoui, dit Karim, atteint du Covid. C’est là qu’il exprime ses regrets de ne pas s’être fait vacciner. La vidéo est mise en ligne par l’AFP et Karim est la cible de nombreuses fausses affirmations, notamment de la part de figures complotistes. Cet homme est mort des suites du Covid le 20 décembre. Mais même après son décès, il sera victime d'une théorie du complot, celle des “faux” morts du Covid qui circule beaucoup en ce moment. Publicité Qu’est-ce qui a évolué, dans le complotisme antivax, entre le début de la campagne vaccinale contre le Covid il y a un peu plus d’un an, et aujourd’hui ? D'abord les figures de proue du mouvement, comme par exemple le professeur Christian Perronne, dont l'intervention le 12 janvier 2022 lors d’un débat public au Parlement du Luxembourg est devenu une vidéo virale sur internet. Huit minutes d’un discours truffé d’informations fausses voire mensongères. La toute récente a…" },
  { title: "De Staline à Poutine, le complotisme en Russie", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-staline-a-poutine-le-complotisme-en-russie-2335469", img: "assets/episodes/49cf72d3-11ab-4f3a-adf2-8d40210f8b0f.webp", youtube: null, description: "La crise en Ukraine a relancé la puissante machine à désinformation de la Russie, dont le complotisme est l’un des leviers.", date: "2022-01-25", body: "Complorama Par Rudy Reichstadt La crise en Ukraine a relancé la puissante machine à désinformation de la Russie, dont le complotisme est l’un des leviers. Une invasion russe en Ukraine : cette perspective nourrit une crise internationale Ouverture dans un nouvel onglet depuis plusieurs semaines. Le Kremlin s’est lancé dans un bras de fer politique, mais aussi dans une nouvelle bataille de l’information. Et sur ce front, le complotisme fait partie de la stratégie de Moscou depuis longtemps. Le conspirationnisme russe est nationaliste, anti-occidental, et nostalgique. Publicité De Staline à Poutine, de la famille Romanov au Covid en passant par l'empoisonnement de l'opposant Alexeï Navalny Ouverture dans un nouvel onglet , quelle est la genèse de ce mouvement en Russie ? Quels en sont aujourd'hui les leviers et les objectifs ? Maxime Audinet, docteur en sciences politiques et en études slaves de l’Université Paris Nanterre, chercheur à l’IRSEM et auteur du livre Russia Today : un média d’influence au service de l’Etat russe aux éditions Ina, décrypte pour Complorama l'usage du complotisme par les médias aux mains du Kremlin. Cet épisode revient aussi sur ce qu'a provoqué la chute de l'URSS, il y a tout juste 30 ans : une aspiration du pouvoir russe et notamment de Vladimir Poutine, ancien officier du KGB, à redonner à la Russie sa grandeur, son rayonnement passés, quitte pour cela à réécrire l'Histoire. \"Le complotisme en Russie\", c’est le 20e épisode de Complorama, avec Rudy…" },
  { title: "Assaut du Capitole : un an après l’attaque, que nous dit-il du complotisme aux États-Unis ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/assaut-du-capitole-un-an-apres-l-attaque-que-nous-dit-il-du-complotisme-aux-etats-unis-2850443", img: "assets/episodes/48d99133-533d-48ad-a81f-93481109b591.webp", youtube: null, description: "L’assaut du Capitole, le 6 janvier 2021, est un évènement complotiste majeur, et qui continue d’avoir des conséquences sur la vie américaine. Il révèle la place qu’occupe la mouvance complotiste aujourd’hui aux Etats-Unis, pays dans lequel elle est profondément ancrée, de Kennedy à QAnon.", date: "2022-01-07", body: "Complorama Par Rudy Reichstadt L’assaut du Capitole, le 6 janvier 2021, est un évènement complotiste majeur, et qui continue d’avoir des conséquences sur la vie américaine. Il révèle la place qu’occupe la mouvance complotiste aujourd’hui aux Etats-Unis, pays dans lequel elle est profondément ancrée, de Kennedy à QAnon. [Le 6 janvier 2021](https://www.francetvinfo.fr/monde/usa/attaque-du-capitole-par-des-militants-pro-trump/assaut-du-capitole-un-an-apres-ou-en-est-l-enquete-qui-tente-d-etablir-la-responsabilite-de-donald-trump_4896613.html) parmi les partisans extrémistes de Trump, des complotistes étaient en première ligne. L’irruption dans le réel d’un phénomène ancien et profondément ancré aux États-Unis, le complotisme, qui ponctue l'Histoire du pays, de l’assassinat de Kennedy à QAnon aujourd'hui. Publicité Que dit l'assaut du Capitole de l'importance des théories du complot dans un pays où la liberté d'expression est protégée par le Premier amendement de la Constitution ? Le professeur d'histoire, spécialiste de la politique américaine Corentin Sellin revient sur la genèse de ces violences, la montée du complotisme au coeur du pouvoir de Donald Trump et la légitimité que l'ancien Président en personne lui a donné durant son mandat, affirmant dès 2020 que s'il perdait l'élection, cela serait nécessairement une fraude. Aujourd'hui, l'administration Biden post-assaut du Capitole a intégré le complotisme comme une potentielle menace de terrorisme intérieur. Loin d'avoir cal…" },
  { title: "Fêtes de Noël : quand le complotisme divise dans les familles", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/fetes-de-noel-quand-le-complotisme-divise-dans-les-familles-4365459", img: "assets/episodes/99cb7c14-c1c7-4110-af80-0376e2edfd8e.webp", youtube: null, description: "Les repas de fêtes approchent, et avec eux les discussions parfois mouvementées en famille ou entre amis. Parfois, le complotisme peut entraîner de véritables ruptures des liens entre proches.", date: "2021-12-10", body: "Complorama Par Rudy Reichstadt Les repas de fêtes approchent, et avec eux les discussions parfois mouvementées en famille ou entre amis. Parfois, le complotisme peut entraîner de véritables ruptures des liens entre proches. À quelques semaines de Noël et du Nouvel an, on pense aux repas de fêtes et à leurs discussions parfois enflammées. Histoires de famille, politique, mais aussi parfois complotisme.... théories antivax, grand remplacement : quand la conspiration s'invite à côté du chapon cela peut avoir de vraies conséquences Ouverture dans un nouvel onglet sur les relations familiales et amicales. Publicité Sylvain Cavalier, connu sous le pseudo de DeBunKer des Etoiles Ouverture dans un nouvel onglet sur les réseaux sociaux, se présente comme un détricoteur de théories du complot.Sur sa chaîne YouTube et son compte Twitter, Sylvain diffuse des contenus pour aller à l’encontre des théories complotistes. \"Il y a une dizaine d'années, je suis tombé dedans, un ami m'avait montré un documentaire très convaincant sur le fait que les pyramides n'avaient pas été construites par les égyptiens mais par une civilisation ancienne aujourd'hui disparue, qui serait technologiquement avancée, raconte Sylvain Cavalier. Tout ça m'a donné une ouverture sur des tas de suggestions de vidéos YouTube sur le 11-Septembre, les chemtrails... Je suis tombé dedans pendant environ deux ans.\" \"Le déclic ne se fait pas du jour au lendemain, c'est un processus assez long, il y a un petit doute qui naît…" },
  { title: "COP26, réchauffement : les théories du complot autour du climat", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/cop26-rechauffement-les-theories-du-complot-autour-du-climat-5649462", img: "assets/episodes/ca4e624a-d0c1-4e3c-be8f-2ee6715f60a5.webp", youtube: null, description: "Des \"chemtrails\" au réchauffement climatique, en passant par les incendies géants, le complotisme climatique a de beaux jours devant lui et se nourrit en ce moment de la sémantique sanitaire.", date: "2021-11-26", body: "Complorama Par Rudy Reichstadt Des \"chemtrails\" au réchauffement climatique, en passant par les incendies géants, le complotisme climatique a de beaux jours devant lui et se nourrit en ce moment de la sémantique sanitaire. Vous connaissiez les climato-sceptiques, voici les climato-complotistes. Qu’importe pour eux le bilan de la COP26, puisque le réchauffement est un mensonge des puissants. Ils se nourrissent du complotisme sanitaire et réinterprètent les lois de la nature sur les réseaux sociaux. Publicité Exemple récent, le tweet de Florian Philippot sur le \"confinement climatique qui précédera le pass climatique\". Pour le président du parti d’extrême droite Les Patriotes, envisager de demander aux gens de rester chez eux en cas de pollution de l’air trop forte relève de \"la logique mortifère du mondialisme\". Voilà le « confinement climatique », qui précédera le « Pass climatique ». Qui s’ajoutera au Pass sanitaire, etc. ➡️ C’est la logique mortifère du mondialisme, que nous avons le devoir de bloquer radicalement ! Pour vivre libre ! https://t.co/9XzWeohOWT Ouverture dans un nouvel onglet — Florian Philippot (@f_philippot) November 15, 2021 Ouverture dans un nouvel onglet En 2012, c’était Donald Trump qui accusait les Chinois d’avoir créé le réchauffement climatique pour rendre l’industrie américaine moins compétitive. L’une des théories du complot les plus anciennes et les plus répandues sur ce thème, c’est celle des \"chemtrails \", \"traînées chimiques\", qui sous-entend q…" },
  { title: "Procès du 13-Novembre : le complotisme n’est jamais loin des attentats", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/proces-du-13-novembre-le-complotisme-n-est-jamais-loin-des-attentats-4384239", img: "assets/episodes/c59b5fcf-f65c-4ca9-ad53-80a49b9e783c.webp", youtube: null, description: "Six ans après les attentats du 13-Novembre, une théorie du complot s’est invitée au procès de ces attaques. Le complotisme est à la fois un instrument de radicalisation, et un outil pour prolonger l’effroi terroriste.", date: "2021-11-12", body: "Complorama Par Rudy Reichstadt Six ans après les attentats du 13-Novembre, une théorie du complot s’est invitée au procès de ces attaques. Le complotisme est à la fois un instrument de radicalisation, et un outil pour prolonger l’effroi terroriste. Des tortures, infligées aux victimes de l’attentat du Bataclan le 13 novembre 2015, seraient depuis cachées par les autorités : c’est la théorie du complot relayée au procès du 13-Novembre il y a quelques semaines, via un échange entre un père endeuillé et le président de la cour d’assises, qui a pris le temps de lui expliquer pourquoi il n’y a aucun crédit à donner à cette hypothèse. Publicité Mais sur les réseaux sociaux, seuls les doutes allant dans le sens de cette théorie ont été récupérés par certains comptes d’extrême droite. C’est ce que raconte pour Complorama Aurélia Gilbert, rescapée du Bataclan et partie civile au procès, qui tente via les réseaux sociaux d’aller contre la propagation du complotisme au sujet du 13-Novembre. \"Parfois, les gens finissent par savoir mieux que moi ce qui m’est arrivé\", regrette-t-elle. Dans ce nouvel épisode de Complorama, zoom sur les liens entre complotisme et terrorisme : les notions de \"false flag\" ou encore de \"crisis actors\", ces supposés acteurs qui seraient payés mettre en scène de faux attentats commandités par les gouvernements ou les services secrets. Rudy Reichstadt et Tristan Mendès France reviennent aussi sur le \"comme par hasard\" qui accompagne tous les attentats, comme lors…" },
  { title: "Du \"Qui ?\" de Cassandre Fristot aux protocoles des Sages de Sion : antisémitisme et complotisme, une longue histoire", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/du-qui-de-cassandre-fristot-aux-protocoles-des-sages-de-sion-antisemitisme-et-complotisme-une-longue-histoire-4576382", img: "assets/episodes/8fec5ca4-614b-40ac-8620-8f21125cdb5c.webp", youtube: null, description: "Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférence associé et membre de l’observatoire du conspirationnisme, reviennent sur les thèses complotistes qui se sont propagées durant la crise sanitaire et décryptent les liens entre antisémitisme et complotisme.", date: "2021-10-29", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférence associé et membre de l’observatoire du conspirationnisme, reviennent sur les thèses complotistes qui se sont propagées durant la crise sanitaire et décryptent les liens entre antisémitisme et complotisme. Cassandre Fristot a été condamnée le 20 octobre dernier à six mois de prison avec sursis par le tribunal correctionnel de Metz pour avoir brandi une pancarte antisémite lors d'une manifestation anti-pass sanitaire Ouverture dans un nouvel onglet à Metz, le 7 août. Sur cette pancarte, on pouvait lire les noms de politiques, d'hommes d'affaires et d'intellectuels pour la plupart juifs, des noms écrits autour du slogan \"Qui ?\". Une pancarte qui, selon les avocats des 13 parties civiles dans ce dossier, portait à la fois \"les stigmates profondes de l'antisémitisme et les codes du complotisme.\" Publicité L'occasion pour Complorama de poser cette question, dans ce 16e épisode : pourquoi antisémitisme et complotisme sont-ils souvent liés ? >> À lire aussi : du complotisme au sein des manifestations contre le pass sanitaire Ouverture dans un nouvel onglet Du regain d'antisémitisme tout au long de la crise sanitaire Ouverture dans un nouvel onglet au mouvement QAnon Ouverture dans un nouvel onglet , Rudy Reichstadt et Tristan Mendès France expliquent pourquoi l'antisémitisme reste le terreau des théories du complot. Ils reviennent aussi sur les protocoles des…" },
  { title: "Commission Bronner, régulation des réseaux sociaux : comment lutter contre l’essor du complotisme ?", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/commission-bronner-regulation-des-reseaux-sociaux-education-aux-medias-comment-lutter-contre-l-essor-du-complotisme-9263729", img: "assets/episodes/e6404f07-5302-4fb4-9419-9a7fa0a96643.webp", youtube: null, description: "Par quels moyens endiguer la propagation des théories du complot ? À l’occasion du lancement de la commission Bronner, zoom sur les questions et obstacles rencontrés dans cette lutte.", date: "2021-10-14", body: "Complorama Par Rudy Reichstadt Par quels moyens endiguer la propagation des théories du complot ? À l’occasion du lancement de la commission Bronner, zoom sur les questions et obstacles rencontrés dans cette lutte. Une commission sur le complotisme vient d’être lancée par Emmanuel Macron, la commission Bronner Ouverture dans un nouvel onglet , du nom du sociologue Gérald Bronner qui la dirige. Publicité L’occasion pour Complorama de poser cette question, dans ce 15e épisode : comment endiguer la propagation des théories du complot ? Les institutions sont-elles une solution ? Faut-il encadrer les réseaux sociaux ou est-ce de la censure ? >> A lire aussi : la commission sur le complotisme a pour but \"d'éclairer le public\" sur les mécaniques de la désinformation Ouverture dans un nouvel onglet Nous parlons aussi du nerf de cette guerre : l’argent. Certains complotistes en ont beaucoup pour promouvoir leurs idées grâce aux revenus publicitaires, quand l’éducation aux médias en France en manque cruellement. \"Comment lutter contre l'essor du complotisme\", c’est le 15e épisode de Complorama, avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques et membre de l'observatoire du conspirationnisme. Un podcast à retrouver sur le site de franceinfo, l'application Radio France et plusieurs autres plateformes comme Apple podcasts Ouverture dans un nouvel onglet , Podcast Add…" },
  { title: "De Dune à Matrix en passant par X-Files : fiction et complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-dune-a-matrix-en-passant-par-x-files-fiction-et-complotisme-8060629", img: "assets/episodes/4dfcd423-3a0a-427c-9243-56f47145362f.webp", youtube: null, description: "Dune, le film événement de la rentrée, est l’une des grandes histoires fictionnelles truffées de complots. Si ces derniers inspirent depuis toujours la fiction, il arrive aussi comme avec Matrix que la fiction inspire le complotisme contemporain.", date: "2021-09-30", body: "Complorama Par Rudy Reichstadt Dune, le film événement de la rentrée, est l’une des grandes histoires fictionnelles truffées de complots. Si ces derniers inspirent depuis toujours la fiction, il arrive aussi comme avec Matrix que la fiction inspire le complotisme contemporain. Quoi de mieux qu’une salle obscure pour les messes basses ? Le complot est omniprésent sur les grands écrans en ce moment. Dans Dune, le film événement de la rentrée, dans Boite Noire où la victime est Pierre Niney… Et dans les Matrix, dont le 4e opus sort en décembre. Publicité Le complot inspire la fiction, mais la fiction inspire aussi le complotisme actuel. Les covido-complotistes, qui s'appellent entre eux des \"éveillés\", savent-ils que Leto Atréides, le père de Paul dans Dune, lui dit à plusieurs reprises que \"le dormeur doit se réveiller\" ? On peut aussi citer James Bond avec la société secrète et tentaculaire Spectre, le nouvel opus sort dans quelques jours également. Mais les histoires de complot qui font le bonheur des inventeurs d’histoire, ça ne date pas d’hier. Dans la littérature populaire du 19e siècle déjà le complot a fait les beaux jours de nombreux auteurs, comme Alexandre Dumas avec Les Trois mousquetaires, où le lecteur découvre une conspiration de Richelieu pour compromettre la reine de France. Mais l'œuvre incontournable quand on évoque le rôle de la fiction dans le complotisme contemporain, c'est Matrix. Le lapin blanc, la pilule bleue et la pilule rouge, ces notions sont carrém…" },
  { title: "Du complotisme au sein des manifestations contre le pass sanitaire", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/du-complotisme-au-sein-des-manifestations-contre-le-pass-sanitaire-2257834", img: "assets/episodes/8dc1f322-0359-4820-8eee-ff2b13448ece.webp", youtube: null, description: "Les manifestations contre le pass sanitaire, chaque samedi depuis le début de l’été, attirent certaines figures de la complosphère, et traduisent dans le réel certains discours extrémistes ayant pris leur essor en ligne.", date: "2021-09-16", body: "Complorama Par Rudy Reichstadt Les manifestations contre le pass sanitaire, chaque samedi depuis le début de l’été, attirent certaines figures de la complosphère, et traduisent dans le réel certains discours extrémistes ayant pris leur essor en ligne. Les manifestations contre le pass sanitaire durent depuis plusieurs mois maintenant. Un mouvement que certains refusent de soutenir, comme Laurent Berger, le secrétaire général de la CFDT qui parle de personnes “infréquentables” au sein de ces rassemblements. Quelles sont ces personnes, et quels messages poussent-elles au gré de cette contestation ? Certaines sont bien connues au sein de la complosphère, comme le général Delawarde, visé par une enquête pour propos antisémites sur CNews. Publicité En novembre dernier sur un blog, Dominique Delawarde avait évoqué une \"meute médiatique occidentale, dont nous savons qui la contrôle”. Interrogé sur CNews, à la question \"Qui ?\" contrôle cette prétendue meute, le militaire finit par répondre à Claude Posternak : “C’est la communauté que vous connaissez bien ». Ce \"Qui ?\" antisémite s’est retrouvé depuis à plusieurs reprises sur des pancartes dans les cortèges anti pass sanitaire, et l’une de ces pancartes appartenait à Cassandre Fristot, à Metz, une enseignante bien connue pour ses liens avec l’extrême droite. Elle a été suspendue de ses fonctions et poursuivie en justice, trois mois de prison avec sursis ont été requis et le jugement sera rendu le 20 octobre. De Florian Philippot à l…" },
  { title: "Le 11 septembre, point de bascule du complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/le-11-septembre-point-de-bascule-du-complotisme-2355188", img: "assets/episodes/045aaee6-80f6-4303-b7bc-cbe7faac6853.webp", youtube: null, description: "Cela fait 20 ans cette année que ces attaques ont frappé les Etats-Unis, 20 ans aussi que les attentats du 11 septembre nourrissent de folles théories, parfois élaborées en France.", date: "2021-09-03", body: "Complorama Par Rudy Reichstadt Cela fait 20 ans cette année que ces attaques ont frappé les Etats-Unis, 20 ans aussi que les attentats du 11 septembre nourrissent de folles théories, parfois élaborées en France. Bienvenue dans cette nouvelle saison de Complorama, elle s’ouvre sur un épisode fondateur de la complosphère moderne : les attentats du 11 septembre. Vingt ans cette année que ces attaques ont frappé les Etats-Unis et qu’elles nourrissent de folles théories, parfois élaborées en France… Publicité Aujourd’hui encore, certains ne croient pas que le 11 septembre soit une série d’attentats perpétrés par Al-Qaïda. Quelle est la place du 11 septembre dans l’écosystème conspirationniste actuel ? Comment s'est créée la narration complotiste autour de ces attentats, aux Etats-Unis et en France ? Ce 20e anniversaire peut-il raviver certaines théories ? De Lyndon Larouche à Thierry Meyssan, en passant par le film \"Loose change\", Rudy Reichstadt et Tristan Mendès France expliquent pourquoi le 11 septembre 2001 a changé la face du complotisme. \"Le 11 septembre, point de bascule du complotisme\", c’est le 12e épisode de Complorama, avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques et membre de l'observatoire du conspirationnisme. Un podcast à retrouver sur le site de franceinfo, l'application Radio France et plusieurs autres plateformes comme Apple podcasts Ouve…" },
  { title: "Les plateformes, pilier du complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/les-plateformes-pilier-du-complotisme-5269575", img: "assets/episodes/b948fbe4-b519-4cf7-bf79-cf548f68aa9d.webp", youtube: null, description: "L’avènement d’internet, des sites et des réseaux sociaux, ces plateformes et leurs algorithmes ont donné naissance à l’état des lieux actuel du complotisme.", date: "2021-06-25", body: "Complorama Par Rudy Reichstadt L’avènement d’internet, des sites et des réseaux sociaux, ces plateformes et leurs algorithmes ont donné naissance à l’état des lieux actuel du complotisme. Twitter, YouTube, SnapChat, Amazon… Ces plateformes, sur lesquelles nous passons tant de temps, ont un rôle essentiel dans la vie de la complosphère… Donald Trump suspendu de Facebook ? C’est la conséquence de l’assaut du Capitole en janvier 2021, où se trouvaient nombre de complotistes. Publicité L’occasion aussi de parler de la partie immergée de l’iceberg de ces plateformes sociales : algorithmes, “rabbit hole”, leur fonctionnement fait-il le jeu de la conspiration, au détriment de l’information ? Les attentats du 11 septembre sont à ce jour l'évènement qui a généré le plus de production complotiste en ligne, des productions propulsées par l'essor d'internet qui s'est produit au même moment. C'était le début d'une nouvelle ère dans l'information, une ère de liberté mais aussi de dérégulation. Depuis, les théories du complot s'invitent sur les grandes plateformes généralistes telles YouTube ou Facebook, mais elles font aussi naître des sites \"spécialisés\", comme France Soir, qui s'appuient souvent beaucoup sur la viralité des réseaux sociaux. \"Les plateformes, pilier du complotisme\", c’est le 11e épisode de Complorama, avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques…" },
  { title: "Thomas Pesquet hypnotisé par la CIA, aliens, platisme : la conquête complotiste de l’espace", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/thomas-pesquet-hypnotise-par-la-cia-aliens-platisme-la-conquete-complotiste-de-l-espace-8901240", img: "assets/episodes/3d59ebd3-5926-452f-9ad4-b7321da4def7.webp", youtube: null, description: "Reptiliens, platistes, ou encore supposée supercherie du voyage de l’Homme sur la Lune : les théories du complot n’épargnent pas l’espace, et ne sont pas que folkloriques.", date: "2021-06-11", body: "Complorama Par Rudy Reichstadt Reptiliens, platistes, ou encore supposée supercherie du voyage de l’Homme sur la Lune : les théories du complot n’épargnent pas l’espace, et ne sont pas que folkloriques. Des reptiliens parmi nous, la Terre qui serait plate et au centre du monde, la Lune sur laquelle aucun homme n’aurait en réalité marché… Ou encore, la station spatiale internationale qui n’existerait pas... Car Thomas Pesquet n’échappe pas au complotisme spatial. C'est l’un des sujets qui nourrit les thèses les plus folles, elles peuvent faire sourire mais ne sont pourtant pas inoffensives. Publicité De QAnon au gourou Raël, les adeptes de ces thèses conspirationnistes concernant l'espace sont le plus souvent liés de manière globale à l'univers complotiste, covido-sceptiques, ou membres de mouvances d'extrême droite. Ils relaient des contenus via YouTube, notamment, énorme accélérateur de ces thèses, celle du platisme par exemple, qui depuis quelques années prend de l'ampleur. \"La conquête complotiste de l'espace\", c’est le 10e épisode de Complorama, avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, spécialiste des cultures numériques et membre de l'observatoire du conspirationnisme. Un podcast à retrouver sur le site de franceinfo, l'application Radio France et plusieurs autres plateformes comme Apple podcasts Ouverture dans un nouvel onglet , Podcast Addict Ouverture dans un nouvel onglet…" },
  { title: "Régionales : ces complotistes aux ambitions politiques", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/regionales-ces-complotistes-aux-ambitions-politiques-6872217", img: "assets/episodes/463132fc-28fa-4f87-b07d-49c21c0d5cc8.webp", youtube: null, description: "Plusieurs listes aux relents complotistes sont en lice aux prochaines régionales, poussées par le covido-scepticisme.", date: "2021-05-27", body: "Complorama Par Rudy Reichstadt Plusieurs listes aux relents complotistes sont en lice aux prochaines régionales, poussées par le covido-scepticisme. Derrière certaines listes aux élections régionales se trouvent des candidats inconnus en politique mais bien connus de la complosphère. Publicité “Un notre monde”, c’est le nom de ce mouvement qui présente des listes en PACA, Bretagne et Pays de la Loire aux régionales des 20 et 27 juin prochains. Un mouvement sans étiquette, qui n’est affilié à aucun parti traditionnel, qui se dit “citoyenniste” et dont les têtes de liste ont des accents complotistes. Il y a notamment deux hommes derrière ces listes : Louis Fouché, un médecin réanimateur à Marseille à l’origine du site de désinformations Reinfo Covid, et Hayssam Hoballah, \"coach bien-être santé holistique\", également activiste d’un groupuscule, le Conseil national de transition qui appelait au putsch en 2015. Ces deux figures complotistes ont émergées pendant la crise du coronavirus et dénoncent la dictature sanitaire. Si ces listes prônent la démocratie, l'écologie, l'éthique ou encore la paix, elles restent assez théoriques. Elles se prémunissent donc d’une défaite annoncée en affirmant que les élections sont truquées. Pour Rudy Reichstadt, \"ces listes-là, a priori, ne vont pas renverser la table politiquement, mais servent de tribune\" aux idées complotistes. \"Des complotistes aux ambitions politiques\", c’est le 9e épisode de Complorama, avec Rudy Reichstadt, directeur de Con…" },
  { title: "De Francis Lalanne à Kim Glow : ces \"people\" séduits par les théories du complot", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/de-francis-lalanne-a-kim-glow-ces-people-seduits-par-les-theories-du-complot-2763645", img: "assets/episodes/4852c8cb-9ac0-4b4f-a4f8-10b02fbfd2d4.webp", youtube: null, description: "À la télévision ou sur les réseaux sociaux, certaines personnalités relaient auprès d", date: "2021-05-13", body: "Complorama Par Marina Cabiten À la télévision ou sur les réseaux sociaux, certaines personnalités relaient auprès d'une large audience des idées complotistes, phénomène accéléré par la crise du covid. Quel est le point commun entre Jean-Marie Bigard, Kim Glow, Mathieu Kassovitz ou encore… Gérard Depardieu ? Ce n’est pas un projet de superproduction, mais un penchant pour la conspiration, qui s’affiche sur nos “petits” écrans de smartphone. Publicité Parmi les personnalités qui partagent publiquement leurs sympathies complotistes, il y a Francis Lalanne, chanteur, militant, très mobilisé en ce moment contre le vaccin et le masque face au Covid. Ces noms connus du grand public offrent-ils une visibilité, voire une crédibilité supplémentaire au complotisme ? Impossible de ne pas parler, dans ce 8e épisode de Complorama, du cas de Dieudonné. Il y a aussi l'influenceuse et star de la télé-réalité Kim Glow, suivie par plus d’un million de personnes sur Instagram, qui a une “story” permanente en une de son profil nommée “La vérité” pour partager des théories complotistes. Elle propulse donc ces théories au sein de sa communauté, pas forcément complotiste. C’est inquiétant, selon Tristan Mendès France, car “la plupart de ses followers sont jeunes et exposés à des contenus extrêmement toxiques alors qu’ils ne sont parfois pas encore formés idéologiquement”. Aujourd’hui, il y a une mode à pousser des discours complotistes car ils génèrent de fortes audiences. Il y a également l’incont…" },
  { title: "Affaire Mia : un enlèvement d’enfant sur fond de complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/affaire-mia-un-enlevement-d-enfant-sur-fond-de-complotisme-8404106", img: "assets/episodes/6284f980-6883-48a4-8e52-0e722ea35a3b.webp", youtube: null, description: "Un gourou conspirationniste, des ravisseurs survivalistes, une mère adepte de théories du complot… l’affaire Mia renvoie à l’une des théories les plus partagées par la complosphère : celle d’une pédocriminalité organisée à l’échelle mondiale par les élites et les autorités.", date: "2021-04-16", body: "Complorama Par Rudy Reichstadt Un gourou conspirationniste, des ravisseurs survivalistes, une mère adepte de théories du complot… l’affaire Mia renvoie à l’une des théories les plus partagées par la complosphère : celle d’une pédocriminalité organisée à l’échelle mondiale par les élites et les autorités. Rémy Daillet-Wiedemann, ancien président du Modem de Haute-Garonne, est aujourd’hui la cible d’un mandat d’arrêt international émis suite à l’enlèvement de Mia, 8 ans, retrouvée le 18 avril. Exilé en Malaisie, Rémy Daillet-Wiedemann est soupçonné d'avoir “joué un rôle” dans l'enlèvement de l’enfant selon les mots du procureur, et d’être “l’animateur principal de la mouvance” dans laquelle s’inscrivent les ravisseurs. Publicité Le profil de cet homme est “assez déroutant”, explique Tristan Mendès France. Complotiste d’extrême droite, Rémy Daillet-Wiedemann dénonce, dans un programme baptisé \"Appel au renversement du gouvernement de la République française\", le port du masque, les campagnes de vaccination massives, le confinement, la 5G mais aussi les organisations comme “la maçonnerie et autres sectes dangereuses”… Un programme qui synthétise toutes les grandes théories complotistes actuelles. Les profils du gourou, des ravisseurs, et même celui de la mère de Mia, montrent que ce dossier baigne dans l'univers complotiste et l'une de ses théories récurrentes relayées notamment par QAnon : celle qui voit “les élites” derrière un complot pédo-criminel mondialisé où la police, la…" },
  { title: "Vaccin contre le Covid-19 : la flambée \"antivax\" complotiste en France", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/vaccin-contre-le-covid-19-la-flambee-antivax-complotiste-en-france-9183131", img: "assets/episodes/7f4381d7-89cb-40ec-a54a-b8c5818c5ba5.webp", youtube: null, description: "Face aux réelles inconnues et aux contradictions dans la communication quant aux vaccins contre le Covid-19, la tendance anti-vaccin s’accélère. Le doute s", date: "2021-04-02", body: "Complorama Par Rudy Reichstadt Face aux réelles inconnues et aux contradictions dans la communication quant aux vaccins contre le Covid-19, la tendance anti-vaccin s’accélère. Le doute s'empare d'une grande partie de la population... et favorise l’avancée du complotisme. La mouvance \"antivax\", bien qu'ancienne, gagne du terrain depuis le début de l'épidémie et notamment depuis quelques semaines. Différents événements ont renforcé la méfiance, voire le rejet des vaccins. Publicité Une question obsède par exemple de nombreux internautes : \"Où est Tiffany Dover Ouverture dans un nouvel onglet ?\" Car pour certains, cette infirmière américaine, qui s’était évanouie après s’être fait vacciner le 17 décembre 2020, est morte depuis. Pour ces mêmes internautes, son changement de coupe de cheveux prouverait qu’elle aurait été remplacée par un sosie. Même après de nombreux démentis, la rumeur selon laquelle Tiffany Dover est morte après son injection persiste. Une autre théorie du complot circule en ce moment : la vaccination contre le Covid serait à l’origine de variants plus dangereux. L'argument a été réfuté clairement par la communauté mondiale des immunologues, pourtant on peut lire sur Facebook : \"Les personnes vaccinées sont des bombes bactériologiques à retardement ambulantes et une MENACE pour la société.\" Les gens vaccinés ne seraient donc pas victimes mais des complices du complot… La méfiance envers les vaccins n'est pas uniquement alimentée par la complosphère sur les rése…" },
  { title: "Des reclus de Monflanquin à Vivian Kubrick : dérives sectaires et complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/des-reclus-de-monflanquin-a-vivian-kubrick-derives-sectaires-et-complotisme-6124557", img: "assets/episodes/ebb3e692-114c-48a3-9721-da8de0e3b665.webp", youtube: null, description: "Dans les affaires Xavier Dupont de Ligonnès ou des reclus de Monflanquin, il est question d", date: "2021-03-19", body: "Complorama Par Rudy Reichstadt Dans les affaires Xavier Dupont de Ligonnès ou des reclus de Monflanquin, il est question d'emprise mentale, un mécanisme commun au complotisme et aux dérives sectaires. Nouvel épisode de Complorama dédié aux dérives sectaires dont les liens avec le complotisme sont soulignés dans le récent rapport de la Miviludes, la mission interministérielle de vigilance et de lutte contre les dérives sectaires. Publicité Un exemple récent : celui de Vivian Kubrick, la fille du réalisateur Stanley Kubrick, scientologue depuis 30 ans mais également complotiste Ouverture dans un nouvel onglet . Sur Twitter, elle multiplie les prises de position conspirationnistes : Bill Gates et les élites, par exemple, auraient mis en place le vaccin à ARN messager pour stériliser une partie de la population. La dimension complotiste des mouvements sectaires est notable dans différents faits divers : Xavier Dupont de Ligonnès faisait partie de l'Eglise de Philadelphie, un groupuscule sectaire fondé par sa mère qui prônait une vision du monde mêlant références à Satan et “complot judéo-maçonnique”. Autre exemple édifiant : celui des reclus de Montflanquin, une famille entière sous l'emprise d'un homme, Thierry Tilly qui prétendait être un agent secret descendant des Habsbourg, et affirmait que les francs-maçons et le fisc en voulaient à cette famille de tradition protestante. Ils vivront près de dix ans coupés du monde. A l'inverse, un mouvement complotiste peut progressivemen…" },
  { title: "Dissolution de Génération identitaire : les liens qui unissent droite radicale et complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/dissolution-de-generation-identitaire-les-liens-qui-unissent-droite-radicale-et-complotisme-9817801", img: "assets/episodes/e7a43587-57c8-4ef9-9d4c-e3360c0f0f6b.webp", youtube: null, description: "Théorie du grand remplacement ou remigration, certains concepts et symboles sont communs à la sphère complotiste et à la droite radicale, comme par exemple Génération identitaire.", date: "2021-03-05", body: "Complorama Par Rudy Reichstadt Théorie du grand remplacement ou remigration, certains concepts et symboles sont communs à la sphère complotiste et à la droite radicale, comme par exemple Génération identitaire. Le groupe d'extrême droite Génération identitaire, créé en 2012, a été dissous le 3 mars dernier. Dans le décret de dissolution Ouverture dans un nouvel onglet , il est écrit qu'il s'agit d'une association qui \"promeut une idéologie incitant à haine, à la violence ou à la discrimination des individus à raison de leur origine, de leur race ou de leur religion\", mais le complotisme ne fait pas partie des griefs évoqués dans ce décret. Publicité Plusieurs liens unissent un groupe comme Génération identitaire et le complotisme. Un homme incarne ce mélange des genres : Brenton Tarrant. Selon Tracfin Ouverture dans un nouvel onglet , un organisme chargé de lutter contre le financement du terrorisme, cet Australien qui a exécuté 51 musulmans en mars 2019 à Christchurch en Nouvelle-Zélande, participait au financement de Génération identitaire. L'extrêmiste a également écrit le manifeste \"The great replacement\" (le grand remplacement), une théorie largement diffusée au sein de la sphère complotiste et forgée par Renaud Camus. Autre notion diffusée à la fois par les complotistes et les militants de la droite identitaire : la remigration. Au delà des idées, il y a aussi des symboles qui naviguent entre ces deux mondes. C'est le cas du lambda grec (λ), autrefois sur les boucliers…" },
  { title: "Russie, Chine, Iran : géopolitique du complotisme", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/russie-chine-iran-geopolitique-du-complotisme-5018814", img: "assets/episodes/9c1b20c9-517b-4483-aaa7-67c6da8dac74.webp", youtube: null, description: "Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé et membre de l’observatoire du conspirationnisme, décryptent les phénomènes complotistes en lien avec l", date: "2021-02-19", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé et membre de l’observatoire du conspirationnisme, décryptent les phénomènes complotistes en lien avec l'actualité. Quand la Chine bannit la BBC Ouverture dans un nouvel onglet en l’accusant de “fake news”, cela a bien un lien avec le complotisme… Quand Aleixeï Navalny Ouverture dans un nouvel onglet attaque le pouvoir russe, Moscou crie au complot occidental… Et en Iran, une chaîne de télé contrôlée par l’Etat diffuse des théories du complot sur le Covid-19 Ouverture dans un nouvel onglet . Publicité Le complotisme est, pour certains régimes, une arme de propagande internationale. Que ce soit en Russie, en Chine ou encore en Iran, certains médias étatiques ou contrôlés par le pouvoir en place n'hésitent pas à relayer des théories du complot, notamment pour étendre leur influence et leur vision du monde à l'étranger, en France par exemple. Emmanuel Macron l'évoquait en 2017, lors d'une conférence de presse aux côtés de Vladimir Poutine, en répondant à une journaliste de Russia Today France : \"Quand des organes de presse répandent des contre-vérités infamantes, ce ne sont plus des journalistes, ce sont des organes d'influence.\" Géopolitique du complotisme : c’est le troisième épisode de Complorama, avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé à l'université Paris-Cité, spécialiste…" },
  { title: "Les complotistes et le business du Covid-19", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/les-complotistes-et-le-business-du-covid-19-4467590", img: "assets/episodes/164c2b2c-6410-4067-af59-0408e34d65ea.webp", youtube: null, description: "Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé et membre de l’observatoire du conspirationnisme, décryptent les phénomènes complotistes en lien avec l", date: "2021-02-05", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférences associé et membre de l’observatoire du conspirationnisme, décryptent les phénomènes complotistes en lien avec l'actualité. Le cas du site France Soir inquiète le gouvernement, comme l'a montré un tweet de la ministre de la Culture, Roselyne Bachelot. Un homme d’affaires a fait de l’ancien journal de référence, qui ne compte [plus aucun journaliste](https://www.francetvinfo.fr/replay-radio/le-choix-franceinfo/si-jetais-ministre-de-la-sante-ce-serait-regle-rapido-les-charlatans-surfent-sur-la-peur-du-covid-19_4114189.html) aujourd'hui, un site internet complotiste à la faveur de l’épidémie. Cet homme, Xavier Azalbert, un entrepreneur, affirme cumuler plus de 3 millions de vues mensuelles sur son site, et \"gagner de l'argent\" avec \"son\" France Soir. Publicité Un exemple parmi d'autres de la façon dont la complosphère s'est emparée du Covid, et de façon lucrative. Le Covid est tout simplement le plus gros accélérateur des théories conspirationnistes sur la planète. J’ai demandé que soit réexaminé le certificat d’IPG (information politique et générale) délivré au service de presse en ligne \\#Francesoir Ouverture dans un nouvel onglet , dont le terme est en principe septembre 2022, afin de vérifier dès maintenant que ses conditions d’octroi sont bien toujours respectées.— Roselyne Bachelot (@R_Bachelot) January 29, 2021 Ouverture dans un nouvel onglet “Hol…" },
  { title: "États-Unis : les complotistes et l'après Donald Trump", url: "https://www.radiofrance.fr/franceinfo/podcasts/complorama/etats-unis-les-complotistes-et-l-apres-donald-trump-7971806", img: "assets/episodes/9a3943a1-97a6-4648-8b3d-e9636e90a166.webp", youtube: null, description: "Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférence associé et membre de l’observatoire du conspirationnisme, décryptent les phénomènes complotistes en lien avec l", date: "2021-01-22", body: "Complorama Par Rudy Reichstadt Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférence associé et membre de l’observatoire du conspirationnisme, décryptent les phénomènes complotistes en lien avec l'actualité. C'est une page qui se tourne dans l’histoire du complotisme : l’ère Trump. Donald Trump est un personnage essentiel de l’univers de la conspiration aux États-Unis. Et cela déjà bien avant qu’il ne soit Président. Publicité Logique, donc, que ses quatre années à la Maison Blanche aient eu l’effet d’un détonateur pour la complosphère. Le mandat Trump, c’est notamment celui de la naissance de QAnon. Alors maintenant que c’est fini, qu’est-ce qui va se passer pour ses partisans ? Qu’est-ce qui va rester de cette période dans l’Amérique de Joe Biden ? Donald Trump laisse derrière lui des complotistes entre dépit et déni. Les complotistes et l’après-Trump : c’est le premier épisode de Complorama, avec Rudy Reichstadt, directeur de Conspiracy Watch, et Tristan Mendès France, maître de conférence et membre de l’observatoire du conspirationnisme, spécialiste des cultures numériques. Un podcast à retrouver un vendredi sur deux sur l'application Radio France et plusieurs autres plateformes comme Apple podcasts Ouverture dans un nouvel onglet , Spotify Ouverture dans un nouvel onglet , ou Deezer Ouverture dans un nouvel onglet ." },
];

// Deduplicate by exact title (Radio France lists some episodes under
// multiple URLs — keep the first occurrence).
const _seen = new Set();
const _unique = [];
for (const ep of RAW_EPISODES) {
  if (_seen.has(ep.title)) continue;
  _seen.add(ep.title);
  _unique.push(ep);
}

// Anchor episode numbers on "PODCAST. La 100e de Complorama". If the anchor
// is at index N (0-based), then index 0 = episode (N + 100). Falls back to
// counting from the array length if the anchor is missing.
const _anchorIdx = _unique.findIndex(e => /\b100e\b/i.test(e.title));
const TOP_NUMBER = _anchorIdx >= 0 ? _anchorIdx + 100 : _unique.length;

window.EPISODES = _unique.map((ep, i) => {
  const out = {
    n: TOP_NUMBER - i,
    title: ep.title,
    img: ep.img,
    url: ep.url,
  };
  if (ep.youtube) out.youtube = ep.youtube;
  if (ep.description) out.description = ep.description;
  if (ep.date) out.date = ep.date; // yyyy-mm-dd
  if (ep.body) out.body = ep.body; // search-only article text
  return out;
});
